import TenantSwitcher from './TenantSwitcher';
import React, { useState, useEffect, useRef } from 'react';
import { API_BASE_URL } from '../config/api';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import { useSidebar } from '../contexts/SidebarContext';
import { useSearch } from '../contexts/SearchContext';
import { useNavigate, useLocation } from 'react-router-dom';
import { useRWFilter } from '../contexts/RWFilterContext';
import { useKelurahanFilter } from '../contexts/KelurahanFilterContext';
import { Search, Bell, Siren, Sun, Moon, LogOut, User, Menu, X, Loader2, Key } from 'lucide-react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogOverlay } from '../components/ui/dialog';
import { Label } from '../components/ui/label';
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuPortal
} from '../components/ui/dropdown-menu';
import { Button } from '../components/ui/button';
import { Input } from '../components/ui/input';
import { Card } from '../components/ui/card';
import { toast } from '../components/ui/sonner';
import { cn } from '../lib/utils';

function playPanicSound() {
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    [0, 0.35, 0.7].forEach(t => {
      const osc  = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain); gain.connect(ctx.destination);
      osc.frequency.value = 880;
      osc.type = 'sawtooth';
      gain.gain.setValueAtTime(0.3, ctx.currentTime + t);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + t + 0.3);
      osc.start(ctx.currentTime + t);
      osc.stop(ctx.currentTime  + t + 0.3);
    });
  } catch { /* Audio API tidak tersedia */ }
}

const ROLE_DISPLAY_LABELS = {
  admin:               'RT Admin',
  warga:               'Warga',
  karyawan:            'Karyawan',
  staff:               'Staff',
  pengurus_rw:         'RW Admin',
  pengurus_kelurahan:  'Kelurahan Admin',
};

const Header = () => {
  const { user, logout, token } = useAuth();
  const { theme, toggleTheme } = useTheme();
  const { toggleSidebar, isMobile } = useSidebar();
  const { searchQuery, searchResults, isSearching, performSearch, clearSearch } = useSearch();
  const navigate = useNavigate();
  const location = useLocation();
  const { rtList, selectedRT, setSelectedRT } = useRWFilter();
  const { rwList, selectedRW, setSelectedRW } = useKelurahanFilter();
  const isRWRoute = location.pathname.startsWith('/rw/');
  const isKelRoute = location.pathname.startsWith('/kelurahan/');
  const [localQuery, setLocalQuery] = useState('');
  const [showResults, setShowResults] = useState(false);
  const searchRef = useRef(null);

  // Notifikasi Warga
  const [notifOpen, setNotifOpen] = useState(false);
  const [notifList, setNotifList] = useState([]);
  const notifRef = useRef(null);
  const isWarga = user?.role === 'warga';
  const isRTAdmin = user?.role === 'admin';
  const isPengurusRW = user?.role === 'pengurus_rw';
  const isPengurusKelurahan = user?.role === 'pengurus_kelurahan';
  const showNotifBell = isWarga || isRTAdmin || isPengurusRW;
  const showPanicBellOnly = isPengurusKelurahan; // Kelurahan: hanya panic bell
  const notifStorageKey = `notif_read_${user?.username || 'u'}`;
  const [readIds, setReadIds] = useState(() => {
    try { return JSON.parse(localStorage.getItem(`notif_read_${user?.username || 'u'}`) || '[]'); }
    catch { return []; }
  });
  const unreadCount = notifList.filter(n => !readIds.includes(n.id)).length;

  // ── PANIC ALERT POLLING ──────────────────────────────────────────
  const [panicCount, setPanicCount] = useState(0);
  const prevPanicCountRef = useRef(0);
  const isAdminRole = ['admin', 'pengurus_rw', 'pengurus_kelurahan'].includes(user?.role);

  useEffect(() => {
    if (!token || !isAdminRole) return;
    const poll = async () => {
      try {
        const res = await fetch(`${API_BASE_URL}/api/panic-button/active-count`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (!res.ok) return;
        const data = await res.json();
        const count = data.count || 0;
        // Siren + haptic jika ada alert baru masuk
        if (count > prevPanicCountRef.current) {
          playPanicSound();
          navigator.vibrate?.([300, 100, 300, 100, 300]);
        }
        prevPanicCountRef.current = count;
        setPanicCount(count);
      } catch { /* silent */ }
    };
    poll(); // langsung saat mount
    const id = setInterval(poll, 5000);
    return () => clearInterval(id);
  }, [token, isAdminRole]);

  const handleNotifClick = (n) => {
    if (!readIds.includes(n.id)) {
      const next = [...readIds, n.id];
      setReadIds(next);
      localStorage.setItem(notifStorageKey, JSON.stringify(next));
    }
    setNotifOpen(false);
    if (isPengurusRW) navigate('/rw/announcements');
    else if (isRTAdmin) {
      const tab = n._from === 'kelurahan' ? 'kel' : 'rw';
      navigate('/pengumuman', { state: { viewItem: n, tab } });
    } else navigate('/pengumuman', { state: { viewItem: n } });
  };

  useEffect(() => {
    if (!showNotifBell || !token) return;
    const fetchInbox = async () => {
      try {
        if (isRTAdmin) {
          const [rwRes, kelRes] = await Promise.all([
            fetch(`${API_BASE_URL}/api/pengumuman/inbox-rt`, { headers: { Authorization: `Bearer ${token}` } }),
            fetch(`${API_BASE_URL}/api/pengumuman/inbox-rt-kelurahan`, { headers: { Authorization: `Bearer ${token}` } }),
          ]);
          const rwJson = rwRes.ok ? await rwRes.json() : { data: [] };
          const kelJson = kelRes.ok ? await kelRes.json() : { data: [] };
          const combined = [
            ...(rwJson.data || []).map(n => ({ ...n, _from: 'rw' })),
            ...(kelJson.data || []).map(n => ({ ...n, _from: 'kelurahan' })),
          ].sort((a, b) => new Date(b.published_at || b.created_at) - new Date(a.published_at || a.created_at));
          setNotifList(combined);
        } else {
          const inboxUrl = isPengurusRW
            ? `${API_BASE_URL}/api/pengumuman/inbox-rw`
            : `${API_BASE_URL}/api/pengumuman/inbox`;
          const res = await fetch(inboxUrl, { headers: { Authorization: `Bearer ${token}` } });
          if (res.ok) {
            const json = await res.json();
            setNotifList(json.data || []);
          }
        }
      } catch (_) {}
    };
    fetchInbox();
  }, [showNotifBell, token]);

  useEffect(() => {
    const handleClickOutside = (e) => {
      if (notifRef.current && !notifRef.current.contains(e.target)) setNotifOpen(false);
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Password Change Modal
  const [openChangePassword, setOpenChangePassword] = useState(false);
  const [passwordForm, setPasswordForm] = useState({
    oldPassword: "",
    newPassword: "",
    confirmPassword: ""
  });

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const handleChangePassword = async () => {
    if (!passwordForm.oldPassword || !passwordForm.newPassword || !passwordForm.confirmPassword) {
      toast.error("Semua field harus diisi");
      return;
    }
    if (passwordForm.newPassword !== passwordForm.confirmPassword) {
      toast.error("Password baru dan konfirmasi tidak cocok");
      return;
    }
    if (passwordForm.newPassword.length < 6) {
      toast.error("Password baru minimal 6 karakter");
      return;
    }

    try {
      const res = await fetch(`${API_BASE_URL}/api/users/change-password`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify({
          old_password: passwordForm.oldPassword,
          new_password: passwordForm.newPassword
        })
      });

      if (!res.ok) {
        const data = await res.json();
        toast.error(data.detail || "Gagal mengganti password");
        return;
      }

      const data = await res.json();
      toast.success("Password berhasil diubah");
      setOpenChangePassword(false);
      setPasswordForm({ oldPassword: "", newPassword: "", confirmPassword: "" });
    } catch (err) {
      console.error("Error changing password:", err);
      toast.error(err.message || "Tidak dapat terhubung ke server");
    }
  };

  const handleSearchChange = (e) => {
    const value = e.target.value;
    setLocalQuery(value);
    performSearch(value);
    setShowResults(true);
  };

  const handleClearSearch = () => {
    setLocalQuery('');
    clearSearch();
    setShowResults(false);
  };

  // Keyboard shortcut: "/" untuk focus search
  const searchInputRef = useRef(null);
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.key === "/" && !["INPUT", "TEXTAREA"].includes(document.activeElement?.tagName)) {
        e.preventDefault();
        searchInputRef.current?.focus();
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, []);

  // Close search results when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (searchRef.current && !searchRef.current.contains(event.target)) {
        setShowResults(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <header className="h-16 bg-[#f7f1de] dark:bg-gray-900 border-b border-[#d5cebc] dark:border-gray-800 px-4 lg:px-6 flex items-center justify-between relative">
      {/* Left Section - Hamburger + Search */}
      <div className="flex items-center gap-3 flex-1">
          <TenantSwitcher />
          {/* RT Filter Dropdown — hanya tampil di halaman RW */}
          {isRWRoute && rtList.length > 0 && (
            <select
              value={selectedRT?.id || ''}
              onChange={e => {
                const found = rtList.find(r => r.id === e.target.value);
                setSelectedRT(found || null);
              }}
              className="text-sm border border-[#d5cebc] dark:border-gray-700 bg-[#f7f1de] dark:bg-gray-800 text-gray-700 dark:text-gray-200 rounded-lg px-3 py-1.5 focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]/40 cursor-pointer min-w-[130px]"
            >
              <option value="">Semua RT</option>
              {rtList.map(rt => (
                <option key={rt.id} value={rt.id}>{rt.name}</option>
              ))}
            </select>
          )}
          {/* RW Filter Dropdown — hanya tampil di halaman Kelurahan */}
          {isKelRoute && rwList.length > 0 && (
            <select
              value={selectedRW?.id || ''}
              onChange={e => {
                const found = rwList.find(r => r.id === e.target.value);
                setSelectedRW(found || null);
              }}
              className="text-sm border border-[#d5cebc] dark:border-gray-700 bg-[#f7f1de] dark:bg-gray-800 text-gray-700 dark:text-gray-200 rounded-lg px-3 py-1.5 focus:outline-none focus:ring-2 focus:ring-emerald-500/40 cursor-pointer min-w-[130px]"
            >
              <option value="">Semua RW</option>
              {rwList.map(rw => (
                <option key={rw.id} value={rw.id}>{rw.name}</option>
              ))}
            </select>
          )}
        {/* Hamburger Menu for Mobile/Tablet */}
        {isMobile && (
          <Button
            variant="ghost"
            size="icon"
            onClick={toggleSidebar}
            className="lg:hidden hover:bg-[#e4dcc8] dark:hover:bg-gray-800"
          >
            <Menu className="h-5 w-5 text-gray-600 dark:text-gray-400" />
          </Button>
        )}

        {/* Search Bar */}
        <div className="flex-1 max-w-md relative" ref={searchRef}>
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
            <Input
              ref={searchInputRef}
              type="text"
              placeholder="search" 
              value={localQuery}
              onChange={handleSearchChange}
              onFocus={() => localQuery && setShowResults(true)}
              className="pl-10 pr-10 bg-[#efe7d2] dark:bg-gray-800 border-[#d5cebc] dark:border-gray-700 text-gray-700 dark:text-gray-200"
            />
            {localQuery && (
              <button
                onClick={handleClearSearch}
                className="absolute right-3 top-1/2 -translate-y-1/2 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full p-1"
              >
                <X className="h-3 w-3 text-gray-400" />
              </button>
            )}
          </div>

          {/* Search Results Dropdown */}
          {showResults && localQuery && (
            <Card className="absolute top-full mt-2 w-full max-w-md z-50 shadow-lg">
              <div className="p-2">
                {isSearching ? (
                  <div className="flex items-center justify-center py-8">
                    <Loader2 className="h-6 w-6 animate-spin text-cyan-500" />
                    <span className="ml-2 text-sm text-gray-600 dark:text-gray-400">Mencari...</span>
                  </div>
                ) : searchResults.length > 0 ? (
                  <div className="space-y-1">
                    <div className="px-3 py-2 text-xs font-semibold text-gray-500 dark:text-gray-400">
                      Hasil Pencarian untuk "{localQuery}"
                    </div>
                    {searchResults.map((result, index) => (
                      <div
                        key={index}
                        onClick={() => {
                          navigate(result.path);
                          handleClearSearch();
                        }}
                        className="px-3 py-2 hover:bg-[#e4dcc8] dark:hover:bg-gray-800 rounded-md cursor-pointer transition-colors"
                      >
                        <div className="text-sm font-medium text-gray-900 dark:text-white">
                          {result.label}
                        </div>
                        <div className="text-xs text-gray-600 dark:text-gray-400">
                          {result.type === 'submenu' ? '└─ ' : ''}{result.id}
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="px-3 py-8 text-center">
                    <Search className="h-8 w-8 text-gray-400 mx-auto mb-2" />
                    <p className="text-sm text-gray-600 dark:text-gray-400">
                      Tidak ada hasil untuk "{localQuery}"
                    </p>
                    <p className="text-xs text-gray-500 dark:text-gray-500 mt-1">
                      Coba kata kunci lain
                    </p>
                  </div>
                )}
              </div>
            </Card>
          )}
        </div>
      </div>

      {/* Right Section */}
      <div className="flex items-center gap-2 lg:gap-4">
        {/* Panic Bell — khusus Kelurahan */}
        {showPanicBellOnly && (
          <button
            onClick={() => navigate('/kelurahan/panic-alerts')}
            className="relative p-2 rounded-lg hover:bg-[#e4dcc8] dark:hover:bg-gray-800 transition-colors"
            title="Alert Darurat"
          >
            <Siren className="h-5 w-5 text-gray-600 dark:text-gray-400" />
            {panicCount > 0 && (
              <span className="absolute -top-0.5 -right-0.5 w-4 h-4 bg-red-600 text-white text-[9px] font-bold rounded-full flex items-center justify-center animate-bounce">
                {panicCount > 9 ? '9+' : panicCount}
              </span>
            )}
          </button>
        )}

        {/* Notifications — untuk warga & RT admin */}
        {showNotifBell && (
          <div className="relative" ref={notifRef}>
            <Button
              variant="ghost" size="icon"
              className="relative hover:bg-[#e4dcc8] dark:hover:bg-gray-800"
              onClick={() => setNotifOpen(o => !o)}
            >
              <Bell className="h-5 w-5 text-gray-600 dark:text-gray-400" />
              {/* Badge panik (merah lebih gelap) — prioritas di atas badge notif biasa */}
              {panicCount > 0 && (
                <span className="absolute -top-0.5 -right-0.5 w-4 h-4 bg-red-600 text-white text-[9px] font-bold rounded-full flex items-center justify-center animate-bounce">
                  {panicCount > 9 ? '9+' : panicCount}
                </span>
              )}
              {panicCount === 0 && unreadCount > 0 && (
                <span className="absolute top-1.5 right-1.5 w-4 h-4 bg-[#ed6f5c] text-white text-[9px] font-bold rounded-full flex items-center justify-center">
                  {unreadCount > 9 ? '9+' : unreadCount}
                </span>
              )}
            </Button>
            {notifOpen && (
              <div className="absolute right-0 mt-2 w-80 bg-[#f7f1de] dark:bg-gray-900 border border-[#d5cebc] dark:border-gray-700 rounded-xl shadow-xl z-50 overflow-hidden">
                <div className="p-3 border-b border-[#d5cebc] dark:border-gray-700 flex items-center justify-between">
                  <span className="text-sm font-semibold text-gray-800 dark:text-white">
                    {isRTAdmin ? 'Pengumuman RW & Kelurahan' : isPengurusRW ? 'Broadcast dari Kelurahan' : 'Pengumuman'}
                  </span>
                  <span className="text-xs text-gray-400">{unreadCount > 0 ? `${unreadCount} baru` : 'semua terbaca'}</span>
                </div>
                <div className="max-h-72 overflow-y-auto">
                  {notifList.length === 0 ? (
                    <div className="py-8 text-center text-sm text-gray-400">Tidak ada pengumuman</div>
                  ) : notifList.map((n) => {
                    const isRead = readIds.includes(n.id);
                    return (
                      <div key={n.id} onClick={() => handleNotifClick(n)} className={`px-4 py-3 border-b border-[#e8e0cb] dark:border-gray-800 hover:bg-[#ece4cf] dark:hover:bg-gray-800 cursor-pointer flex items-start gap-2 ${isRead ? 'opacity-60' : ''}`}>
                        <span className={`mt-1.5 w-2 h-2 rounded-full flex-shrink-0 ${isRead ? 'bg-transparent' : 'bg-[#ed6f5c]'}`} />
                        <div className="min-w-0 flex-1">
                          <div className="flex items-center gap-1.5 flex-wrap">
                            <p className={`text-sm truncate ${isRead ? 'font-normal text-gray-600 dark:text-gray-400' : 'font-semibold text-gray-800 dark:text-white'}`}>{n.judul}</p>
                            {n._from === 'kelurahan' && (
                              <span className="flex-shrink-0 text-[9px] px-1.5 py-0.5 rounded-full font-medium bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-400">Kel</span>
                            )}
                            {n._from === 'rw' && (
                              <span className="flex-shrink-0 text-[9px] px-1.5 py-0.5 rounded-full font-medium bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-400">RW</span>
                            )}
                          </div>
                          <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5 line-clamp-2">{n.isi}</p>
                          <p className="text-[10px] text-gray-400 mt-1">
                            {n.published_at ? new Date(n.published_at).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' }) : ''}
                          </p>
                        </div>
                      </div>
                    );
                  })}
                </div>
                {(isRTAdmin || isPengurusRW) && (
                  <div className="p-2 border-t border-[#d5cebc] dark:border-gray-700">
                    <button
                      onClick={() => {
                        setNotifOpen(false);
                        if (isPengurusRW) navigate('/rw/announcements');
                        else navigate('/pengumuman', { state: { tab: 'rw' } });
                      }}
                      className="w-full text-center text-sm text-[#ed6f5c] hover:text-[#e05544] py-1.5 font-medium transition-colors"
                    >
                      Lihat Semua
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {/* Theme Toggle */}
        <Button
          variant="ghost"
          size="icon"
          onClick={toggleTheme}
          className="hover:bg-[#e4dcc8] dark:hover:bg-gray-800"
          title={theme === 'light' ? 'Switch to Dark' : 'Switch to Light'}
        >
          {theme === 'light' ? (
            <Moon className="h-5 w-5 text-gray-600" />
          ) : (
            <Sun className="h-5 w-5 text-gray-400" />
          )}
        </Button>

        {/* User Dropdown */}
       <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button variant="ghost" className="flex items-center gap-2 hover:bg-[#e4dcc8] dark:hover:bg-gray-800">
            <div className="w-8 h-8 rounded-full bg-[#ed6f5c] flex items-center justify-center">
              <span className="text-sm font-semibold text-white">
                {user?.fullname?.charAt(0) || 'U'}
              </span>
            </div>
            <span className="text-sm font-medium text-gray-700 dark:text-gray-300 hidden sm:inline">
              {user?.fullname || 'User'}
            </span>
          </Button>
        </DropdownMenuTrigger>

        {/* 🔥 INI KUNCINYA */}
        <DropdownMenuPortal>
          <DropdownMenuContent 
            align="end" 
            className="w-56 z-[9999]"
          >
            <DropdownMenuLabel>
              <div className="space-y-0.5">
                <p className="font-semibold text-gray-800 dark:text-white">{user?.fullname}</p>
                <p className="text-xs text-gray-500 dark:text-gray-400">
                  {ROLE_DISPLAY_LABELS[user?.role] || user?.role}
                </p>
                {user?.block_house && (
                  <p className="text-xs text-cyan-600 dark:text-cyan-400 font-medium">
                    {user.block_house}
                  </p>
                )}
              </div>
            </DropdownMenuLabel>

            <DropdownMenuSeparator />

            <DropdownMenuItem onClick={() => setOpenChangePassword(true)}>
              <Key className="mr-2 h-4 w-4" />
              <span>Ganti Kata Sandi</span>
            </DropdownMenuItem>

            <DropdownMenuSeparator />

            <DropdownMenuItem 
              onClick={handleLogout} 
              className="text-red-600 dark:text-red-400"
            >
              <LogOut className="mr-2 h-4 w-4" />
              <span>Keluar</span>
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenuPortal>
      </DropdownMenu>
      </div>

      {/* GANTI PASSWORD MODAL */}
      <Dialog open={openChangePassword} onOpenChange={setOpenChangePassword}>
         <DialogOverlay className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[9998]" />

         <DialogContent className="z-[9999] dark:bg-gray-900 dark:text-gray-100">
          <DialogHeader>
            <DialogTitle>Ganti Kata Sandi</DialogTitle>
          </DialogHeader>
          
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="oldPassword">Kata Sandi Lama</Label>
              <Input
                id="oldPassword"
                type="password"
                placeholder="Kata Sandi Lama"
                value={passwordForm.oldPassword}
                onChange={(e) => setPasswordForm({ ...passwordForm, oldPassword: e.target.value })}
                className="dark:bg-gray-800"
              />
            </div>
            
            <div className="space-y-2">
              <Label htmlFor="newPassword">Kata Sandi Baru</Label>
              <Input
                id="newPassword"
                type="password"
                placeholder="Kata Sandi Baru"
                value={passwordForm.newPassword}
                onChange={(e) => setPasswordForm({ ...passwordForm, newPassword: e.target.value })}
                className="dark:bg-gray-800"
              />
            </div>
            
            <div className="space-y-2">
              <Label htmlFor="confirmPassword">Ulangi Kata Sandi</Label>
              <Input
                id="confirmPassword"
                type="password"
                placeholder="Ulangi Kata Sandi"
                value={passwordForm.confirmPassword}
                onChange={(e) => setPasswordForm({ ...passwordForm, confirmPassword: e.target.value })}
                className="dark:bg-gray-800"
              />
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setOpenChangePassword(false)}>
              Batal
            </Button>
            <Button onClick={handleChangePassword}
            className="bg-[#ed6f5c] hover:bg-[#e05544] text-white"
            >
              Simpan
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </header>
  );
};

export default Header;