import React, { useState } from 'react';
import { Bell, X, AlertCircle } from 'lucide-react';

export default function NotificationPermissionBanner({ onEnable, onDismiss }) {
  const [blocked, setBlocked] = useState(false);
  const [loading, setLoading] = useState(false);

  const handleEnable = async () => {
    setLoading(true);
    try {
      // Cek dulu apakah permission sudah di-deny
      if (Notification.permission === 'denied') {
        setBlocked(true);
        setLoading(false);
        return;
      }
      const ok = await onEnable();
      if (!ok && Notification.permission === 'denied') {
        setBlocked(true);
      }
    } finally {
      setLoading(false);
    }
  };

  if (blocked) {
    return (
      <div className="flex items-start gap-3 px-4 py-2 bg-red-50 dark:bg-red-900/30 border-b border-red-200 dark:border-red-700 text-sm">
        <AlertCircle size={15} className="text-red-500 shrink-0 mt-0.5" />
        <span className="flex-1 text-red-800 dark:text-red-300">
          Notifikasi diblokir browser. Aktifkan manual:&nbsp;
          <strong>Klik ikon 🔒 di address bar → Notifications → Allow</strong>
          &nbsp;atau buka&nbsp;
          <a
            href="edge://settings/content/notifications"
            className="underline font-semibold"
            onClick={e => { e.preventDefault(); navigator.clipboard?.writeText('edge://settings/content/notifications'); alert('Salin ke address bar: edge://settings/content/notifications'); }}
          >
            Edge Settings
          </a>
          &nbsp;→ Allow → tambah localhost:3001
        </span>
        <button type="button" onClick={onDismiss} className="shrink-0 text-red-400 hover:text-red-600">
          <X size={14} />
        </button>
      </div>
    );
  }

  return (
    <div className="flex items-center gap-3 px-4 py-2 bg-amber-50 dark:bg-amber-900/30 border-b border-amber-200 dark:border-amber-700 text-sm">
      <Bell size={15} className="text-amber-600 dark:text-amber-400 shrink-0" />
      <span className="flex-1 text-amber-800 dark:text-amber-300">
        Aktifkan notifikasi browser agar mendapat alert darurat dari warga secara real-time.
      </span>
      <button
        type="button"
        onClick={handleEnable}
        disabled={loading}
        className="shrink-0 px-3 py-1 rounded-md bg-amber-500 hover:bg-amber-600 disabled:opacity-60 text-white text-xs font-semibold transition-colors"
      >
        {loading ? 'Meminta...' : 'Aktifkan'}
      </button>
      <button
        type="button"
        onClick={onDismiss}
        className="shrink-0 text-amber-500 hover:text-amber-700 dark:text-amber-400"
        aria-label="Tutup"
      >
        <X size={14} />
      </button>
    </div>
  );
}
