import { useEffect, useState } from "react";
import { API_BASE_URL } from "@/config/api";
import { useAuth } from "@/contexts/AuthContext";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import { TrendingUp, TrendingDown, Minus, RefreshCw } from "lucide-react";

const formatRp = (val) =>
  new Intl.NumberFormat("id-ID", { style: "currency", currency: "IDR", minimumFractionDigits: 0 }).format(val);

const MONTHS = ["", "Jan", "Feb", "Mar", "Apr", "Mei", "Jun", "Jul", "Agu", "Sep", "Okt", "Nov", "Des"];
const FULL_MONTHS = ["", "Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];

export default function LaporanPosAnggaran() {
  const { token } = useAuth();
  const now = new Date();
  const [tahun,       setTahun]       = useState(String(now.getFullYear()));
  const [bulanDari,   setBulanDari]   = useState("1");
  const [bulanSampai, setBulanSampai] = useState(String(now.getMonth() + 1));
  const [data,        setData]        = useState([]);
  const [loading,     setLoading]     = useState(false);

  const years = Array.from({ length: 5 }, (_, i) => String(now.getFullYear() - i));

  const loadData = async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams({
        tahun_dari: tahun,
        bulan_dari: bulanDari,
        tahun_sampai: tahun,
        bulan_sampai: bulanSampai,
      });
      const res = await fetch(`${API_BASE_URL}/api/laporan/pos-anggaran?${params}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) setData(await res.json());
      else setData([]);
    } catch { setData([]); }
    setLoading(false);
  };

  useEffect(() => { loadData(); }, []);

  const totalPemasukan  = data.reduce((s, d) => s + d.total_pemasukan,  0);
  const totalPengeluaran = data.reduce((s, d) => s + d.total_pengeluaran, 0);
  const totalSaldo       = totalPemasukan - totalPengeluaran;

  return (
    <div className="space-y-6">
      {/* Header + filter */}
      <div className="bg-[#f7f1de] dark:bg-gray-900 rounded-lg border dark:border-gray-700 p-5">
        <div className="flex flex-wrap items-end gap-3 justify-between">
          <div>
            <h2 className="text-xl font-bold dark:text-white">Laporan Pos Anggaran</h2>
            <p className="text-sm text-gray-500 dark:text-gray-400 mt-0.5">
              Saldo per pos iuran — pemasukan terkumpul vs pengeluaran
            </p>
          </div>
          <div className="flex flex-wrap items-end gap-2">
            <div>
              <label className="text-xs text-gray-500 block mb-1">Tahun</label>
              <Select value={tahun} onValueChange={setTahun}>
                <SelectTrigger className="w-28"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {years.map(y => <SelectItem key={y} value={y}>{y}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <label className="text-xs text-gray-500 block mb-1">Dari Bulan</label>
              <Select value={bulanDari} onValueChange={setBulanDari}>
                <SelectTrigger className="w-32"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {FULL_MONTHS.slice(1).map((m, i) => (
                    <SelectItem key={i+1} value={String(i+1)}>{m}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div>
              <label className="text-xs text-gray-500 block mb-1">Sampai Bulan</label>
              <Select value={bulanSampai} onValueChange={setBulanSampai}>
                <SelectTrigger className="w-32"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {FULL_MONTHS.slice(1).map((m, i) => (
                    <SelectItem key={i+1} value={String(i+1)}>{m}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <Button onClick={loadData} disabled={loading} className="bg-[#ed6f5c] hover:bg-[#e05544] text-white gap-2">
              <RefreshCw size={14} className={loading ? "animate-spin" : ""} />
              {loading ? "Memuat..." : "Tampilkan"}
            </Button>
          </div>
        </div>
      </div>

      {/* Summary totals */}
      {data.length > 0 && (
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          <div className="bg-[#f7f1de] dark:bg-gray-900 rounded-lg border dark:border-gray-700 p-4">
            <p className="text-xs font-semibold text-gray-500 uppercase">Total Pemasukan</p>
            <p className="text-xl sm:text-2xl font-bold text-green-600 dark:text-green-400 mt-1 break-all">{formatRp(totalPemasukan)}</p>
          </div>
          <div className="bg-[#f7f1de] dark:bg-gray-900 rounded-lg border dark:border-gray-700 p-4">
            <p className="text-xs font-semibold text-gray-500 uppercase">Total Pengeluaran</p>
            <p className="text-xl sm:text-2xl font-bold text-red-600 dark:text-red-400 mt-1 break-all">{formatRp(totalPengeluaran)}</p>
          </div>
          <div className="bg-[#f7f1de] dark:bg-gray-900 rounded-lg border dark:border-gray-700 p-4">
            <p className="text-xs font-semibold text-gray-500 uppercase">Saldo Total</p>
            <p className={`text-xl sm:text-2xl font-bold mt-1 break-all ${totalSaldo >= 0 ? "text-green-600 dark:text-green-400" : "text-red-600 dark:text-red-400"}`}>
              {formatRp(totalSaldo)}
            </p>
          </div>
        </div>
      )}

      {/* Pos cards */}
      {loading ? (
        <div className="text-center py-16 text-gray-400">Memuat data...</div>
      ) : data.length === 0 ? (
        <div className="text-center py-16 text-gray-400">
          <p className="font-medium">Belum ada data Pos Anggaran</p>
          <p className="text-sm mt-1">
            Pastikan Kategori Biaya sudah dipasangkan (Pemasukan ↔ Pengeluaran) di menu Kategori Biaya,
            dan komponen IPL sudah dihubungkan ke kategori tersebut.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
          {data.map((pos) => {
            const surplus = pos.saldo >= 0;
            const pct = pos.total_pemasukan > 0
              ? Math.min(100, Math.round((pos.total_pengeluaran / pos.total_pemasukan) * 100))
              : 0;
            return (
              <Card key={pos.kategori_pemasukan_id} className="border dark:border-gray-700 shadow-sm overflow-hidden">
                <div className={`h-1.5 w-full ${surplus ? "bg-green-400" : "bg-red-400"}`} />
                <CardContent className="p-5">
                  <div className="flex items-start justify-between mb-3">
                    <div>
                      <h3 className="font-semibold text-gray-800 dark:text-gray-100">{pos.nama_pos}</h3>
                      {pos.kategori_pengeluaran_nama && (
                        <p className="text-xs text-gray-400 mt-0.5">↔ {pos.kategori_pengeluaran_nama}</p>
                      )}
                    </div>
                    <div className={`p-1.5 rounded-full ${surplus ? "bg-green-100 text-green-600" : "bg-red-100 text-red-600"}`}>
                      {surplus ? <TrendingUp size={16} /> : <TrendingDown size={16} />}
                    </div>
                  </div>

                  <div className="space-y-1.5 text-sm">
                    <div className="flex justify-between">
                      <span className="text-gray-500">Pemasukan</span>
                      <span className="font-medium text-green-600">{formatRp(pos.total_pemasukan)}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-gray-500">Pengeluaran</span>
                      <span className="font-medium text-red-600">{formatRp(pos.total_pengeluaran)}</span>
                    </div>
                    {pos.total_pemasukan > 0 && (
                      <div className="pt-1">
                        <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-1.5">
                          <div
                            className={`h-1.5 rounded-full transition-all ${surplus ? "bg-green-400" : "bg-red-400"}`}
                            style={{ width: `${pct}%` }}
                          />
                        </div>
                        <p className="text-xs text-gray-400 mt-0.5">{pct}% terpakai</p>
                      </div>
                    )}
                  </div>

                  <div className={`mt-3 pt-3 border-t dark:border-gray-700 flex justify-between items-center`}>
                    <span className="text-xs font-semibold text-gray-500 uppercase">Saldo</span>
                    <span className={`text-lg font-bold ${surplus ? "text-green-600 dark:text-green-400" : "text-red-600 dark:text-red-400"}`}>
                      {formatRp(pos.saldo)}
                    </span>
                  </div>
                  {!surplus && (
                    <p className="text-xs text-red-500 mt-1">⚠ Defisit — disubsidi sementara dari pos lain</p>
                  )}
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );
}
