import React, { useState, useEffect, useRef } from 'react';
import { API_BASE_URL } from '@/config/api';
import { useAuth } from "@/contexts/AuthContext";

/* ========================= */
/* 🔧 HELPER AUTH FETCH */
/* ========================= */
async function fetchWithAuth(url, token) {
  const res = await fetch(url, {
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json'
    }
  });

  if (!res.ok) {
    throw new Error(`HTTP ${res.status}`);
  }

  return res.json();
}

function safeArray(v) { return Array.isArray(v) ? v : []; }

function resolveUrl(cctv, token) {
  if (!cctv?.url) return null;
  if (cctv.stream_type === 'rtsp') return null;
  if (cctv.use_proxy) return `${API_BASE_URL}/api/cctv/hls-proxy/playlist?url=${encodeURIComponent(cctv.url)}&token=${token}`;
  return cctv.url;
}


/* ── Fullscreen Modal ── */
function FullscreenModal({ cctv, onClose , token}) {
  const videoRef = useRef(null);
  const imgRef   = useRef(null);
  const hlsRef   = useRef(null);
  const wrapRef  = useRef(null);
  const [status, setStatus] = useState('loading');
  const [clockStr, setClockStr] = useState('');
  const isRTSP = cctv?.stream_type === 'rtsp';

  useEffect(() => {
    const tick = () => setClockStr(new Date().toLocaleTimeString('id-ID'));
    tick(); const t = setInterval(tick, 1000); return () => clearInterval(t);
  }, []);

  useEffect(() => {
    const onKey = e => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    document.body.style.overflow = 'hidden';
    return () => {
      window.removeEventListener('keydown', onKey);
      document.body.style.overflow = '';
    };
  }, [onClose]);

  useEffect(() => {
    setStatus('loading');
    if (isRTSP) {
      const src = `${API_BASE_URL}/api/rtsp-proxy?url=${encodeURIComponent(cctv.url)}&token=${token}`;
      if (imgRef.current) {
        imgRef.current.src = src;
        imgRef.current.onload  = () => setStatus('playing');
        imgRef.current.onerror = () => setStatus('error');
      }
      return;
    }
    const src = resolveUrl(cctv, token);
    const video = videoRef.current;
    if (!video || !src) { setStatus('error'); return; }
    let dead = false;
    const setup = async () => {
      try {
        const { default: Hls } = await import('hls.js');
        if (Hls.isSupported()) {
          const hls = new Hls({
            enableWorker: true,
            lowLatencyMode: true,
            xhrSetup: (xhr, url) => {
              if (url && url.startsWith(API_BASE_URL)) {
                xhr.setRequestHeader('ngrok-skip-browser-warning', 'true');
              }
            },
          });
          hlsRef.current = hls;
          hls.loadSource(src);
          hls.attachMedia(video);
          hls.on(Hls.Events.MANIFEST_PARSED, () => { if (!dead) { video.play().catch(()=>{}); setStatus('playing'); } });
          hls.on(Hls.Events.ERROR, (_,d) => { if (d.fatal && !dead) setStatus('error'); });
        } else if (video.canPlayType('application/vnd.apple.mpegurl')) {
          video.src = src;
          video.onloadedmetadata = () => { video.play().catch(()=>{}); setStatus('playing'); };
          video.onerror = () => setStatus('error');
        } else { setStatus('error'); }
      } catch { if (!dead) setStatus('error'); }
    };
    setup();
    return () => {
      dead = true;
      if (hlsRef.current) { hlsRef.current.destroy(); hlsRef.current = null; }
      if (video) video.src = '';
    };
  }, [cctv?.id, cctv?.url, cctv?.stream_type, cctv?.use_proxy, token]);

  const goNative = () => {
    const el = wrapRef.current;
    if (!el) return;
    const req = el.requestFullscreen || el.webkitRequestFullscreen || el.mozRequestFullScreen || el.msRequestFullscreen;
    if (req) req.call(el);
  };

  const typeColor = { hls:'#38bdf8', rtsp:'#f59e0b', rtmp:'#ef4444' }[cctv?.stream_type] || '#888';
  const btnStyle = {
    background:'rgba(0,0,0,0.55)', border:'1px solid rgba(255,255,255,0.2)',
    color:'#fff', borderRadius:8, padding:'6px 10px', cursor:'pointer',
    display:'flex', alignItems:'center', gap:5, fontSize:12, fontWeight:600,
    backdropFilter:'blur(4px)', WebkitBackdropFilter:'blur(4px)',
  };

  return (
    <div className="fs-overlay" onClick={e => e.target===e.currentTarget && onClose()}>
      {/* Top bar */}
      <div className="fs-topbar">
        <div style={{ display:'flex', alignItems:'center', gap:8, minWidth:0 }}>
          {status==='playing' && <span className="dot-live" style={{ flexShrink:0 }}/>}
          <span style={{ fontSize:14,fontWeight:700,color:'#fff',overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap' }}>{cctv?.name}</span>
          <span style={{ fontSize:9,fontWeight:700,padding:'1px 5px',borderRadius:3,flexShrink:0,
            background:`${typeColor}30`,color:typeColor,fontFamily:'monospace' }}>
            {(cctv?.stream_type||'hls').toUpperCase()}
          </span>
          {!!cctv?.use_proxy && (
            <span style={{ fontSize:9,fontWeight:700,padding:'1px 5px',borderRadius:3,flexShrink:0,
              background:'rgba(245,158,11,0.25)',color:'#f59e0b',fontFamily:'monospace' }}>PROXY</span>
          )}
        </div>
        <div style={{ display:'flex', gap:8, flexShrink:0 }}>
          <button onClick={goNative} style={btnStyle} title="Layar Penuh Perangkat">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <polyline points="15 3 21 3 21 9"/><polyline points="9 21 3 21 3 15"/>
              <line x1="21" y1="3" x2="14" y2="10"/><line x1="3" y1="21" x2="10" y2="14"/>
            </svg>
            <span className="fs-btn-label">Layar Penuh</span>
          </button>
          <button onClick={onClose} style={{ ...btnStyle, padding:'6px 12px', fontSize:16 }} title="Tutup (Esc)">✕</button>
        </div>
      </div>

      {/* Video */}
      <div ref={wrapRef} className="fs-video-wrap">
        {isRTSP
          ? <img ref={imgRef} alt="stream" className="fs-video"/>
          : <video ref={videoRef} muted playsInline controls className="fs-video"/>
        }
        {status === 'loading' && (
          <div className="fs-status-overlay">
            <div className="spinner" style={{ width:36,height:36,borderWidth:3 }}/>
            <div style={{ color:'rgba(255,255,255,0.7)',fontSize:13,marginTop:8 }}>Memuat stream…</div>
          </div>
        )}
        {status === 'error' && (
          <div className="fs-status-overlay">
            <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="var(--danger)" strokeWidth="1.5">
              <circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/>
            </svg>
            <div style={{ color:'var(--danger)',fontSize:14,fontWeight:700,marginTop:8 }}>Stream Error</div>
            <button onClick={() => setStatus('loading')}
              style={{ marginTop:10,fontSize:12,padding:'5px 16px',borderRadius:6,
                background:'rgba(255,255,255,0.1)',border:'1px solid rgba(255,255,255,0.2)',color:'#fff',cursor:'pointer' }}>
              ↺ Coba Lagi
            </button>
          </div>
        )}
      </div>

      {/* Bottom info */}
      <div className="fs-bottombar">
        <div style={{ color:'rgba(255,255,255,0.65)',fontSize:12 }}>
          📍 {cctv?.location}
          {cctv?.group_name && <span style={{ marginLeft:10,color:'rgba(255,255,255,0.4)' }}>🏷 {cctv.group_name}</span>}
        </div>
        <div style={{ color:'rgba(255,255,255,0.45)',fontSize:11,fontFamily:'monospace' }}>{clockStr}</div>
      </div>
    </div>
  );
}

