const LAYOUTS = [{id:1,slots:1},{id:4,slots:4},{id:9,slots:9},{id:16,slots:16},{id:25,slots:25}];

/* ── localStorage helpers ── */
const LS_KEY = 'kbbs_viewer';

function lsSave(layoutId, slots) {
  try {
    const prev = lsLoad() || {};
    // Store slotIds per layoutId so switching layouts doesn't lose other layouts' slots
    const allSlots = prev.allSlots || {};
    allSlots[layoutId] = slots.map(s => s ? s.id : null);
    localStorage.setItem(LS_KEY, JSON.stringify({ layoutId, allSlots }));
  } catch {}
}

function lsLoad() {
  try {
    const raw = localStorage.getItem(LS_KEY);
    if (raw) return JSON.parse(raw);
  } catch {}
  return null;
}

function lsGetSlotIds(layoutId, slotCount) {
  try {
    const data = lsLoad();
    if (!data) return null;
    const allSlots = data.allSlots || {};
    // Try exact layout match first
    if (allSlots[layoutId] && allSlots[layoutId].length === slotCount) {
      return allSlots[layoutId];
    }
  } catch {}
  return null;
}

/* ── Main Viewer ── */
export default function CCTVViewer() {
  // Read localStorage ONCE at module init time — before any useState
  const _saved      = lsLoad();
  const _initLayout = _saved ? (LAYOUTS.find(l => l.id === _saved.layoutId) || LAYOUTS[1]) : LAYOUTS[1];

  const [grouped,       setGrouped]       = useState([]);
  const [loading,       setLoading]       = useState(true);
  const [layout,        setLayout]        = useState(_initLayout);
  const [slots,         setSlots]         = useState(() => Array(_initLayout.slots).fill(null));
  const [selectingSlot, setSelectingSlot] = useState(null);
  const [openGroups,    setOpenGroups]    = useState({});
  const [filterGroup,   setFilterGroup]   = useState('all');
  const [error,         setError]         = useState(null);
  const [sidebarOpen,   setSidebarOpen]   = useState(false);
  const [fullscreenCctv,setFullscreenCctv] = useState(null);
  const { token } = useAuth();

  // Track whether fetchData has completed its first load
  const dataReady = useRef(false);

  const fetchData = async () => {
    setLoading(true); 
    setError(null);

    try {
      const headers = token
        ? { Authorization: `Bearer ${token}` }
        : {};

      const [g, a] = await Promise.all([
        fetch(`${API_BASE_URL}/api/cctv/grouped`, { headers }).then(r => {
          if (!r.ok) throw new Error(`grouped: HTTP ${r.status}`);
          return r.json();
        }),
        fetch(`${API_BASE_URL}/api/cctv/active`, { headers }).then(r => {
          if (!r.ok) throw new Error(`active: HTTP ${r.status}`);
          return r.json();
        }),
      ]);

      const safeG = safeArray(g);
      const safeA = safeArray(a);

      setGrouped(safeG);

      const open = {};
      safeG.forEach(({ group }) => { if (group) open[group] = true; });
      setOpenGroups(open);

      // Restore saved slot arrangement for current layout
      const savedIds = lsGetSlotIds(_initLayout.id, _initLayout.slots);

      if (savedIds) {
        const restored = savedIds.map(id =>
          id ? (safeA.find(c => c.id === id) || null) : null
        );
        setSlots(restored);
      } else {
        // No saved data — auto-fill with first N active CCTVs
        const next = Array(_initLayout.slots).fill(null);
        safeA.slice(0, _initLayout.slots).forEach((c, i) => {
          next[i] = c;
        });
        setSlots(next);
      }

    } catch (e) {
      console.error('fetchData error:', e);
      setError(e.message);
    } finally {
      dataReady.current = true;
      setLoading(false);
    }
  };

  useEffect(() => { 
    fetchData(); 
  }, [token]); // ⬅️ penting: refetch kalau token berubah

  // Save to localStorage ONLY after first data load is done
  useEffect(() => {
    if (!dataReady.current) return;
    lsSave(layout.id, slots);
  }, [layout, slots]);

  const changeLayout = (l) => {
    lsSave(layout.id, slots);
    setLayout(l);

    setSlots(prev => {
      const savedIds = lsGetSlotIds(l.id, l.slots);

      if (savedIds) {
        const allCctv = safeArray(grouped).flatMap(g => safeArray(g.items));
        const restored = savedIds.map(id =>
          id ? (allCctv.find(c => c.id === id) || null) : null
        );
        lsSave(l.id, restored);
        return restored;
      }

      const next = Array(l.slots).fill(null);
      for (let i = 0; i < Math.min(prev.length, l.slots); i++) {
        next[i] = prev[i];
      }

      lsSave(l.id, next);
      return next;
    });
  };

  const handleClick = (c) => {
    if (selectingSlot !== null) {
      setSlots(prev => {
        const n = [...prev];
        n[selectingSlot] = c;
        return n;
      });
      setSelectingSlot(null);
    } else {
      const idx = slots.findIndex(s => !s);
      if (idx >= 0) {
        setSlots(prev => {
          const n = [...prev];
          n[idx] = c;
          return n;
        });
      }
    }

    if (window.innerWidth <= 900) {
      setSidebarOpen(false);
    }
  };

  const removeSlot  = (idx) =>
    setSlots(prev => {
      const n = [...prev];
      n[idx] = null;
      return n;
    });

  const usedIds     = slots.filter(Boolean).map(s => s.id);

  const gridClass   =
    {1:'grid-1',2:'grid-2',4:'grid-4 grid-mobile-4',6:'grid-3',9:'grid-3',16:'grid-4x4',25:'grid-4x4'}[layout.slots] || 'grid-4';

  const safeGrouped = safeArray(grouped);
  const shownGroups = filterGroup==='all'
    ? safeGrouped
    : safeGrouped.filter(g => g.group===filterGroup);

  if (loading) return (
    <div className="loading">
      <div className="spinner"/>
      <span>Memuat data CCTV…</span>
    </div>
  );

  if (error) return (
    <div style={{ textAlign:'center',padding:40,color:'var(--danger)' }}>
      <div style={{ fontSize:15,fontWeight:700,marginBottom:8 }}>Gagal memuat data</div>
      <div style={{ fontSize:12,color:'var(--text-muted)',marginBottom:16 }}>{error}</div>
      <button className="btn btn-primary" onClick={fetchData}>↺ Coba Lagi</button>
    </div>
  );

  return (
    <div>
      {/* Toolbar */}
      <div className="viewer-toolbar">
        <div>
          <div className="viewer-title">Monitor CCTV</div>
          <div style={{ fontSize:12,color:'var(--text-muted)',marginTop:2 }}>
            {slots.filter(Boolean).length}/{layout.slots} kamera aktif
          </div>
        </div>
        <div style={{ display:'flex',alignItems:'center',gap:8,flexWrap:'wrap' }}>
          <span style={{ fontSize:12,color:'var(--text-muted)' }}>Layout:</span>
          <div className="layout-btns">
            {LAYOUTS.map(l => (
              <button key={l.id} className={`layout-btn ${layout.id===l.id?'active':''}`}
                onClick={() => changeLayout(l)} title={`${l.slots} kamera`}>
                <LayoutIcon slots={l.slots}/>
              </button>
            ))}
          </div>

        </div>
      </div>

      {/* Mobile-only: "Pilih CCTV" button positioned ABOVE the grid */}
      <div className="mobile-select-bar">
        <button
          className="sidebar-toggle-btn mobile-select-btn"
          onClick={() => setSidebarOpen(o => !o)}
        >
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <rect x="2" y="3" width="20" height="14" rx="2"/>
            <line x1="8" y1="21" x2="16" y2="21"/><line x1="12" y1="17" x2="12" y2="21"/>
          </svg>
          {sidebarOpen ? '✕ Tutup' : '📹 Pilih CCTV'}
        </button>
      </div>

      <div className="viewer-layout">
        {/* Grid */}
        <div className="viewer-main">
          <div className={`cctv-grid ${gridClass}`}>
            {slots.map((cctv, idx) =>
              cctv
                ? <StreamCell key={`${cctv.id}-${idx}`} cctv={cctv} token={token} onRemove={() => removeSlot(idx)} onExpand={c => setFullscreenCctv(c)}/>
                : <EmptySlot  key={`empty-${idx}`} index={idx} onSelect={setSelectingSlot} onOpenSidebar={() => setSidebarOpen(true)}/>
            )}
          </div>
        </div>

        {/* Sidebar — always visible on desktop, toggled on mobile via CSS class */}
        <div className={`cctv-sidebar-select${sidebarOpen ? ' sidebar-open' : ''}`}>
          <div className="cctv-select-header">📹 Daftar CCTV</div>

          {/* Filter pills */}
          <div style={{ padding:'8px 10px',display:'flex',flexWrap:'wrap',gap:4,borderBottom:'1px solid var(--border)' }}>
            <Pill label="Semua" active={filterGroup==='all'} onClick={() => setFilterGroup('all')}/>
            {safeGrouped.map(({ group }) => group
              ? <Pill key={group} label={group} active={filterGroup===group} onClick={() => setFilterGroup(group)}/>
              : null
            )}
          </div>

          {/* Accordion list */}
          <div className="cctv-select-list">
            {shownGroups.length === 0
              ? <div style={{ padding:16,fontSize:12,color:'var(--text-muted)',textAlign:'center' }}>
                  {safeGrouped.length === 0 ? 'Belum ada CCTV aktif' : 'Tidak ada kamera di group ini'}
                </div>
              : shownGroups.map(({ group, items }) => {
                  const safeItems = safeArray(items);
                  return (
                    <div key={group || 'tanpa-group'}>
                      <div className="cctv-group-header" onClick={() => setOpenGroups(o => ({ ...o, [group]:!o[group] }))}>
                        <div style={{ display:'flex',alignItems:'center',gap:6 }}>
                          <span style={{ fontSize:11 }}>🏷</span>
                          <span style={{ fontSize:11,fontWeight:700,color:'var(--text-primary)',
                            textTransform:'uppercase',letterSpacing:'0.6px' }}>{group || 'Tanpa Group'}</span>
                          <span style={{ fontSize:9,background:'var(--accent-dim)',color:'var(--accent)',
                            border:'1px solid var(--border-accent)',borderRadius:10,
                            padding:'1px 5px',fontWeight:700 }}>{safeItems.length}</span>
                        </div>
                        <span style={{ color:'var(--text-muted)',fontSize:12,display:'inline-block',
                          transition:'transform 0.2s',
                          transform: openGroups[group] ? 'rotate(0deg)':'rotate(-90deg)' }}>▾</span>
                      </div>

                      {openGroups[group] && safeItems.map(c => {
                        const inUse = usedIds.includes(c.id);
                        const typeColor = { hls:'var(--accent)',rtsp:'#f59e0b',rtmp:'var(--danger)' }[c.stream_type]||'#888';
                        return (
                          <div key={c.id} className={`cctv-select-item ${inUse?'in-use':''}`}
                            onClick={() => handleClick(c)} style={{ paddingLeft:20 }}
                            title={inUse ? 'Sedang ditampilkan' : selectingSlot!==null ? `Pilih slot ${selectingSlot+1}` : 'Klik untuk tampilkan'}>
                            <div className={`csi-dot ${inUse?'':'off'}`}/>
                            <div className="csi-info">
                              <div className="csi-name" style={{ display:'flex',alignItems:'center',gap:4,flexWrap:'wrap' }}>
                                {c.name}
                                <span style={{ fontSize:8,padding:'1px 4px',borderRadius:3,fontWeight:700,
                                  background:`${typeColor}22`,color:typeColor,fontFamily:'monospace' }}>
                                  {(c.stream_type||'hls').toUpperCase()}
                                </span>
                                {!!c.use_proxy && (
                                  <span style={{ fontSize:8,padding:'1px 4px',borderRadius:3,fontWeight:700,
                                    background:'rgba(245,158,11,0.15)',color:'#f59e0b',fontFamily:'monospace' }}>PROXY</span>
                                )}
                              </div>
                              <div className="csi-loc">{c.location}</div>
                            </div>
                            {inUse && <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="var(--accent)" strokeWidth="2.5"><polyline points="20 6 9 17 4 12"/></svg>}
                          </div>
                        );
                      })}
                    </div>
                  );
                })
            }
          </div>

          {selectingSlot !== null && (
            <div style={{ padding:'8px 14px',fontSize:11,background:'var(--accent-dim)',
              borderTop:'1px solid var(--border-accent)',color:'var(--accent)',
              display:'flex',alignItems:'center',justifyContent:'space-between' }}>
              <span>Pilih kamera untuk slot {selectingSlot+1}</span>
              <button onClick={() => setSelectingSlot(null)}
                style={{ background:'none',border:'none',color:'var(--accent)',cursor:'pointer',fontSize:14 }}>✕</button>
            </div>
          )}
        </div>
      </div>
      {/* Fullscreen Modal */}
      {fullscreenCctv && (
        <FullscreenModal
          cctv={fullscreenCctv}
          token={token}
          onClose={() => setFullscreenCctv(null)}
        />
      )}
    </div>
  );
}

function Pill({ label, active, onClick }) {
  return (
    <button onClick={onClick} style={{ fontSize:10,padding:'2px 8px',borderRadius:10,cursor:'pointer',
      fontFamily:'Sora,sans-serif', border:'1px solid var(--border)',
      background: active ? 'var(--accent)' : 'transparent',
      color: active ? '#fff' : 'var(--text-muted)' }}>{label}</button>
  );
}

function LayoutIcon({ slots }) {
  const s=16;
  if(slots===1) return <svg width={s} height={s} viewBox="0 0 16 16" fill="none"><rect x="2" y="2" width="12" height="12" rx="1.5" fill="currentColor" opacity="0.8"/></svg>;
  if(slots===2) return <svg width={s} height={s} viewBox="0 0 16 16" fill="none"><rect x="2" y="2" width="5.5" height="12" rx="1" fill="currentColor" opacity="0.8"/><rect x="8.5" y="2" width="5.5" height="12" rx="1" fill="currentColor" opacity="0.8"/></svg>;
  if(slots===4) return <svg width={s} height={s} viewBox="0 0 16 16" fill="none"><rect x="2" y="2" width="5.5" height="5.5" rx="1" fill="currentColor" opacity="0.8"/><rect x="8.5" y="2" width="5.5" height="5.5" rx="1" fill="currentColor" opacity="0.8"/><rect x="2" y="8.5" width="5.5" height="5.5" rx="1" fill="currentColor" opacity="0.8"/><rect x="8.5" y="8.5" width="5.5" height="5.5" rx="1" fill="currentColor" opacity="0.8"/></svg>;
  if(slots===6) return <svg width={s} height={s} viewBox="0 0 16 16" fill="none">{[0,1,2].map(c=>[0,1].map(r=><rect key={`${c}${r}`} x={2+c*4.5} y={2+r*7} width="3.5" height="6" rx="0.8" fill="currentColor" opacity="0.8"/>))}</svg>;
  if(slots===9) return <svg width={s} height={s} viewBox="0 0 16 16" fill="none">{[0,1,2].map(c=>[0,1,2].map(r=><rect key={`${c}${r}`} x={2+c*4.5} y={2+r*4.5} width="3.5" height="3.5" rx="0.6" fill="currentColor" opacity="0.8"/>))}</svg>;
  if(slots===16) return <svg width={s} height={s} viewBox="0 0 16 16" fill="none">{[0,1,2,3].map(c=>[0,1,2,3].map(r=><rect key={`${c}${r}`} x={2+c*3.5} y={2+r*3.5} width="2.8" height="2.8" rx="0.4" fill="currentColor" opacity="0.8"/>))}</svg>;
  return <svg width={s} height={s} viewBox="0 0 16 16" fill="none">{[0,1,2,3,4].map(c=>[0,1,2,3,4].map(r=><rect key={`${c}${r}`} x={1.5+c*2.8} y={1.5+r*2.8} width="2.2" height="2.2" rx="0.3" fill="currentColor" opacity="0.8"/>))}</svg>;
}
