import React, { useState, useEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { useAuth } from '../../contexts/AuthContext';
import { API_BASE_URL } from '../../config/api';
import {
  CreditCard, Receipt, Clock, CheckCircle, AlertCircle, XCircle,
  ExternalLink, Copy, RefreshCw, AlertTriangle, X, Landmark,
  Search, ChevronDown, Eye, ArrowLeftRight, Package, CalendarDays,
  Plus, PlusCircle,
} from 'lucide-react';
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from '@/components/ui/table';

// ── Helpers ────────────────────────────────────────────────────────────────
const fmt = (n) =>
  new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(n || 0);

const fmtDate = (d) =>
  d ? new Date(d).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' }) : '-';

const fmtDateTime = (d) =>
  d ? new Date(d).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '-';

// ── Constants ──────────────────────────────────────────────────────────────
const TX_EXPIRY_MIN = 60;

const INV_STATUS = {
  unpaid:    { label: 'Belum Dibayar', cls: 'bg-amber-100 text-amber-700 border-amber-200' },
  overdue:   { label: 'Jatuh Tempo',   cls: 'bg-red-100 text-red-700 border-red-200' },
  paid:      { label: 'Sudah Dibayar', cls: 'bg-emerald-100 text-emerald-700 border-emerald-200' },
  cancelled: { label: 'Dibatalkan',    cls: 'bg-gray-100 text-gray-500 border-gray-200' },
};

// Returns remaining ms until tx expires (60 min from created_at). 0 if expired.
const txRemainingMs = (createdAt, now) => {
  if (!createdAt) return 0;
  const expires = new Date(createdAt).getTime() + TX_EXPIRY_MIN * 60_000;
  return Math.max(0, expires - now);
};

const TX_STATUS = {
  pending: { label: 'Pending',  cls: 'bg-amber-100 text-amber-700 border-amber-200',      Icon: Clock },
  paid:    { label: 'Berhasil', cls: 'bg-emerald-100 text-emerald-700 border-emerald-200', Icon: CheckCircle },
  failed:  { label: 'Gagal',    cls: 'bg-red-100 text-red-700 border-red-200',             Icon: XCircle },
  expired: { label: 'Expired',  cls: 'bg-gray-100 text-gray-500 border-gray-200',          Icon: AlertCircle },
};

const GW_META = {
  xendit:   { name: 'Xendit',   cls: 'bg-blue-100 text-blue-700' },
  midtrans: { name: 'Midtrans', cls: 'bg-cyan-100 text-cyan-700' },
};

// ── CopyButton ─────────────────────────────────────────────────────────────
function CopyButton({ text, className = '', disabled = false }) {
  const [copied, setCopied] = useState(false);
  return (
    <button
      onClick={() => { if (disabled) return; navigator.clipboard.writeText(text).then(() => { setCopied(true); setTimeout(() => setCopied(false), 1800); }); }}
      disabled={disabled}
      className={`flex items-center gap-1 px-2 py-1 rounded text-xs font-medium transition-colors ${disabled ? 'bg-gray-100 text-gray-400 cursor-not-allowed opacity-50' : copied ? 'bg-emerald-100 text-emerald-700' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'} ${className}`}>
      <Copy size={12} />{copied ? 'Disalin' : 'Salin'}
    </button>
  );
}

// ── PaymentModal ───────────────────────────────────────────────────────────
function PaymentModal({ invoice, activeGateways, token, onClose, onSuccess }) {
  const [gateway, setGateway] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!invoice) return;
    setGateway(activeGateways.length === 1 ? activeGateways[0].provider : '');
    setError('');
  }, [invoice, activeGateways]);

  if (!invoice) return null;

  const handleGenerate = async () => {
    if (!gateway) { setError('Pilih metode pembayaran terlebih dahulu.'); return; }
    setLoading(true); setError('');
    try {
      const res = await fetch(`${API_BASE_URL}/api/tenant/payment-link`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ invoice_id: invoice.id, gateway }),
      });
      if (!res.ok) {
        let detail = `HTTP ${res.status}`;
        try { const j = await res.json(); detail = j.detail || detail; } catch (_) {}
        throw new Error(detail);
      }
      const data = await res.json();
      try { if (data?.payment_url) window.open(data.payment_url, '_blank', 'noopener,noreferrer'); } catch (_) {}
      if (onSuccess) onSuccess(data);
    } catch (e) {
      setError(e.message || 'Gagal membuat link pembayaran.');
    } finally { setLoading(false); }
  };

  return createPortal(
    <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-white dark:bg-gray-800 rounded-2xl shadow-2xl w-full max-w-md z-10">
        <div className="flex items-center justify-between px-6 py-4 border-b dark:border-gray-700">
          <div className="flex items-center gap-2">
            <CreditCard size={18} className="text-emerald-600" />
            <h3 className="font-semibold text-gray-900 dark:text-gray-100">Bayar Tagihan</h3>
          </div>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><X size={18} /></button>
        </div>
        <div className="p-6 space-y-4">
          {/* Invoice info */}
          <div className="bg-gray-50 dark:bg-gray-700/40 rounded-xl p-4 space-y-2 text-sm">
            {[['No. Invoice', invoice.invoice_number], ['Paket', invoice.package_name || '-'], ['Jatuh Tempo', fmtDate(invoice.due_date)]].map(([l, v]) => (
              <div key={l} className="flex justify-between">
                <span className="text-gray-500 dark:text-gray-400">{l}</span>
                <span className="font-medium text-gray-800 dark:text-gray-200">{v}</span>
              </div>
            ))}
            <div className="flex justify-between pt-1 border-t dark:border-gray-600">
              <span className="text-gray-500 dark:text-gray-400">Nominal</span>
              <span className="font-bold text-emerald-600 text-base">{fmt(invoice.amount)}</span>
            </div>
          </div>

          {/* Gateway selection */}
          {activeGateways.length === 0 ? (
            <div className="flex items-start gap-3 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-700 rounded-xl p-4">
              <AlertTriangle size={17} className="text-amber-600 flex-shrink-0 mt-0.5" />
              <p className="text-sm text-amber-800 dark:text-amber-300">Pembayaran online belum tersedia. Hubungi administrator untuk mengaktifkan payment gateway.</p>
            </div>
          ) : (
            <div className="space-y-2">
              <p className="text-sm font-medium text-gray-700 dark:text-gray-300">Metode Pembayaran</p>
              <div className="grid grid-cols-2 gap-2">
                {activeGateways.map((gw) => (
                  <button key={gw.provider} onClick={() => setGateway(gw.provider)}
                    className={`flex items-center gap-2 px-4 py-3 rounded-xl border-2 text-sm font-medium transition-all ${gateway === gw.provider ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700' : 'border-gray-200 dark:border-gray-600 text-gray-700 dark:text-gray-300 hover:border-gray-300'}`}>
                    <Landmark size={15} />
                    {GW_META[gw.provider]?.name || gw.provider}
                    {!gw.is_production && <span className="ml-auto text-xs bg-amber-100 text-amber-700 px-1.5 py-0.5 rounded">Sandbox</span>}
                  </button>
                ))}
              </div>
            </div>
          )}

          {error && (
            <div className="flex items-start gap-2 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-700 rounded-lg p-3 text-sm text-red-700 dark:text-red-300">
              <AlertTriangle size={14} className="flex-shrink-0 mt-0.5" />{error}
            </div>
          )}

          <div className="flex gap-3">
            <button onClick={onClose} className="flex-1 py-2.5 rounded-xl border border-gray-200 dark:border-gray-600 text-sm font-medium text-gray-600 dark:text-gray-300 hover:bg-gray-50 transition-colors">Batal</button>
            {activeGateways.length > 0 && (
              <button onClick={handleGenerate} disabled={loading || !gateway}
                className="flex-1 py-2.5 rounded-xl bg-emerald-600 text-white text-sm font-medium hover:bg-emerald-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center justify-center gap-2">
                {loading ? <RefreshCw size={13} className="animate-spin" /> : <CreditCard size={13} />}
                {loading ? 'Membuat...' : 'Buat Link Pembayaran'}
              </button>
            )}
          </div>
        </div>
      </div>
    </div>,
    document.body
  );
}

// ── TxDetailModal ──────────────────────────────────────────────────────────
function TxDetailModal({ tx, onClose }) {
  if (!tx) return null;
  const st = TX_STATUS[tx.status] || TX_STATUS.pending;
  const isExpired = tx.status === 'expired';
  return createPortal(
    <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-white dark:bg-gray-800 rounded-2xl shadow-2xl w-full max-w-md z-10">
        <div className="flex items-center justify-between px-6 py-4 border-b dark:border-gray-700">
          <div className="flex items-center gap-2">
            <ArrowLeftRight size={17} className="text-gray-500" />
            <h3 className="font-semibold text-gray-900 dark:text-gray-100">Detail Transaksi</h3>
          </div>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><X size={18} /></button>
        </div>
        <div className="p-6 space-y-4 text-sm">
          <div className="flex items-center gap-2 flex-wrap">
            <span className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full border text-xs font-medium ${st.cls}`}>
              <st.Icon size={12} />{st.label}
            </span>
            <span className={`px-2.5 py-1 rounded-full text-xs font-medium ${GW_META[tx.gateway]?.cls || 'bg-gray-100 text-gray-600'}`}>
              {GW_META[tx.gateway]?.name || tx.gateway}
            </span>
          </div>
          <div className="bg-gray-50 dark:bg-gray-700/40 rounded-xl p-4 space-y-3">
            {[['No. Referensi', tx.external_id], ['No. Invoice', tx.invoice_number || '-'], ['Nominal', fmt(tx.amount)], ['Tanggal', fmtDateTime(tx.created_at)]].map(([l, v]) => (
              <div key={l} className="flex justify-between gap-4">
                <span className="text-gray-500 dark:text-gray-400 flex-shrink-0">{l}</span>
                <span className="font-medium text-gray-800 dark:text-gray-200 text-right break-all">{v}</span>
              </div>
            ))}
          </div>
          {tx.payment_url && (
            <div className="space-y-2">
              <p className="text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wide">Link Pembayaran</p>
              <div className={`bg-gray-50 dark:bg-gray-700/40 rounded-xl p-3 text-xs font-mono break-all border dark:border-gray-600 select-none ${isExpired ? 'text-gray-400 dark:text-gray-600 opacity-50 cursor-not-allowed' : 'text-gray-700 dark:text-gray-300'}`}>{tx.payment_url}</div>
              <div className="flex gap-2">
                <CopyButton text={tx.payment_url} className="flex-1 justify-center" disabled={isExpired} />
                {isExpired ? (
                  <button disabled
                    className="flex-1 flex items-center justify-center gap-1 px-2 py-1 rounded text-xs font-medium bg-emerald-600 text-white opacity-50 cursor-not-allowed">
                    <ExternalLink size={12} />Buka
                  </button>
                ) : (
                  <a href={tx.payment_url} target="_blank" rel="noreferrer"
                    className="flex-1 flex items-center justify-center gap-1 px-2 py-1 rounded text-xs font-medium bg-emerald-600 text-white hover:bg-emerald-700 transition-colors">
                    <ExternalLink size={12} />Buka
                  </a>
                )}
              </div>
            </div>
          )}
          <button onClick={onClose} className="w-full py-2.5 rounded-xl bg-gray-100 dark:bg-gray-700 text-sm font-medium text-gray-600 dark:text-gray-300 hover:bg-gray-200 transition-colors">Tutup</button>
        </div>
      </div>
    </div>,
    document.body
  );
}

// ── Dropdown ───────────────────────────────────────────────────────────────
function Dropdown({ value, onChange, options }) {
  const [open, setOpen] = useState(false);
  const sel = options.find((o) => o.value === value);
  return (
    <div className="relative">
      <button onClick={() => setOpen((p) => !p)}
        className="flex items-center gap-2 px-3 py-2 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-50 transition-colors min-w-[130px]">
        <span className="flex-1 text-left">{sel?.label}</span>
        <ChevronDown size={13} className="text-gray-400" />
      </button>
      {open && (
        <>
          <div className="fixed inset-0 z-10" onClick={() => setOpen(false)} />
          <div className="absolute left-0 top-full mt-1 z-20 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl shadow-lg min-w-full overflow-hidden">
            {options.map((o) => (
              <button key={o.value} onClick={() => { onChange(o.value); setOpen(false); }}
                className={`w-full text-left px-4 py-2.5 text-sm transition-colors ${o.value === value ? 'bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700' : 'text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700'}`}>
                {o.label}
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

// ── AddonRequestModal ──────────────────────────────────────────────────────
function AddonRequestModal({ sub, token, onClose, onSuccess }) {
  const [qty, setQty] = useState(5);
  const [loading, setLoading] = useState(false);
  const [error, setError]     = useState('');
  const [done, setDone]       = useState(false);

  const handleSubmit = async () => {
    if (!qty || qty < 1) { setError('Jumlah RT harus minimal 1'); return; }
    setLoading(true); setError('');
    try {
      const res = await fetch(`${API_BASE_URL}/api/tenant/addon-request`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ quantity: parseInt(qty) }),
      });
      if (!res.ok) {
        const j = await res.json().catch(() => ({}));
        throw new Error(j.detail || `HTTP ${res.status}`);
      }
      setDone(true);
      if (onSuccess) onSuccess();
    } catch (e) { setError(e.message); }
    setLoading(false);
  };

  return createPortal(
    <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-white dark:bg-gray-800 rounded-2xl shadow-2xl w-full max-w-sm z-10 p-6 space-y-4">
        <div className="flex items-center justify-between">
          <h3 className="font-bold text-gray-800 dark:text-gray-100 flex items-center gap-2">
            <PlusCircle size={16} className="text-violet-600" /> Request Tambah RT
          </h3>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><X size={17} /></button>
        </div>
        {done ? (
          <div className="text-center space-y-3 py-4">
            <CheckCircle size={40} className="text-emerald-500 mx-auto" />
            <p className="font-semibold text-gray-800 dark:text-gray-100">Request Terkirim!</p>
            <p className="text-sm text-gray-500">Menunggu persetujuan vendor. Anda akan mendapat invoice setelah disetujui.</p>
            <button onClick={onClose} className="w-full py-2.5 rounded-xl bg-emerald-600 text-white text-sm font-semibold">Tutup</button>
          </div>
        ) : (
          <>
            <div className="bg-gray-50 dark:bg-gray-700/40 rounded-xl p-3 text-sm space-y-1">
              <div className="flex justify-between"><span className="text-gray-500">Paket saat ini</span><span className="font-medium">{sub.package_name}</span></div>
              {sub.rt_max && <div className="flex justify-between"><span className="text-gray-500">Batas RT paket</span><span className="font-medium">{sub.rt_max} RT</span></div>}
              {sub.addon_rt_active > 0 && <div className="flex justify-between"><span className="text-gray-500">Addon aktif</span><span className="font-medium text-emerald-600">+{sub.addon_rt_active} RT</span></div>}
              {sub.rt_max_effective && <div className="flex justify-between border-t pt-1 mt-1 dark:border-gray-600"><span className="text-gray-500">Total efektif sekarang</span><span className="font-bold">{sub.rt_max_effective} RT</span></div>}
            </div>
            <div>
              <label className="text-sm font-medium text-gray-700 dark:text-gray-300 block mb-1">Jumlah RT tambahan yang dibutuhkan</label>
              <input type="number" min="1" value={qty} onChange={e => setQty(e.target.value)}
                className="w-full border border-gray-200 dark:border-gray-600 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-violet-500 dark:bg-gray-700 dark:text-gray-100" />
              <p className="text-xs text-gray-400 mt-1">Vendor akan menetapkan harga dan membuat invoice setelah menyetujui request.</p>
            </div>
            {error && <div className="flex items-start gap-2 bg-red-50 border border-red-200 rounded-lg p-3 text-sm text-red-700"><AlertTriangle size={14} className="flex-shrink-0 mt-0.5" />{error}</div>}
            <div className="flex gap-3">
              <button onClick={onClose} className="flex-1 py-2.5 rounded-xl border border-gray-200 dark:border-gray-600 text-sm text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700">Batal</button>
              <button onClick={handleSubmit} disabled={loading}
                className="flex-1 py-2.5 rounded-xl bg-violet-600 hover:bg-violet-700 text-white text-sm font-semibold disabled:opacity-50 flex items-center justify-center gap-2">
                {loading ? <RefreshCw size={13} className="animate-spin" /> : <Plus size={13} />}
                {loading ? 'Mengirim...' : 'Kirim Request'}
              </button>
            </div>
          </>
        )}
      </div>
    </div>,
    document.body
  );
}

// ── SubscriptionCard ───────────────────────────────────────────────────────
function SubscriptionCard({ sub, token, onRefresh }) {
  const [addonModal, setAddonModal] = useState(false);
  if (!sub || sub.no_subscription) return null;

  const d = sub.days_remaining;
  const fmtPrice = (n, period) => {
    const p = fmt(n);
    if (period === 'monthly') return `${p} / bulan`;
    if (period === 'yearly')  return `${p} / tahun`;
    if (period === 'lifetime') return `${p} (selamanya)`;
    return p;
  };

  // Warning banner config
  let banner = null;
  if (sub.is_in_grace) {
    const graceLeft = 7 + d; // d is negative, e.g. d=-3 → graceLeft=4
    banner = {
      cls: 'bg-red-50 border-red-200 text-red-800',
      icon: <AlertTriangle size={16} className="text-red-500 flex-shrink-0 mt-0.5" />,
      text: `Langganan telah berakhir. Masa tenggang ${graceLeft} hari tersisa — akses terbatas setelah ${fmtDate(sub.grace_ends_at)}. Segera bayar tagihan.`,
    };
  } else if (d >= 1 && d <= 7) {
    banner = {
      cls: 'bg-orange-50 border-orange-200 text-orange-800',
      icon: <AlertTriangle size={16} className="text-orange-500 flex-shrink-0 mt-0.5" />,
      text: `Langganan berakhir dalam ${d} hari! Akses akan dibatasi jika tidak diperpanjang tepat waktu.`,
    };
  } else if (d > 7 && d <= 30) {
    banner = {
      cls: 'bg-amber-50 border-amber-200 text-amber-800',
      icon: <Clock size={16} className="text-amber-500 flex-shrink-0 mt-0.5" />,
      text: `Langganan berakhir dalam ${d} hari (${fmtDate(sub.end_date)}). Pastikan tagihan sudah dibayar sebelum jatuh tempo.`,
    };
  }

  // Status badge
  let badgeCls = 'bg-emerald-100 text-emerald-700 border-emerald-200';
  let badgeLabel = 'Aktif';
  if (sub.is_blocked) {
    badgeCls = 'bg-red-100 text-red-700 border-red-200'; badgeLabel = 'Berakhir';
  } else if (sub.is_in_grace) {
    badgeCls = 'bg-red-100 text-red-700 border-red-200'; badgeLabel = 'Grace Period';
  } else if (d <= 7) {
    badgeCls = 'bg-orange-100 text-orange-700 border-orange-200'; badgeLabel = 'Kritis';
  } else if (d <= 30) {
    badgeCls = 'bg-amber-100 text-amber-700 border-amber-200'; badgeLabel = 'Segera Berakhir';
  }

  return (
    <div className="space-y-2">
      {banner && (
        <div className={`flex items-start gap-3 border rounded-xl px-4 py-3 text-sm ${banner.cls}`}>
          {banner.icon}
          <span>{banner.text}</span>
        </div>
      )}
      <div className="bg-white dark:bg-gray-800 rounded-2xl border border-gray-100 dark:border-gray-700 p-4">
        <div className="flex items-start justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-emerald-50 dark:bg-emerald-900/20 flex items-center justify-center flex-shrink-0">
              <Package size={18} className="text-emerald-600" />
            </div>
            <div>
              <div className="flex items-center gap-2 flex-wrap">
                <p className="font-bold text-gray-900 dark:text-gray-100 text-base">{sub.package_name}</p>
                <span className={`text-xs font-semibold px-2 py-0.5 rounded-full border ${badgeCls}`}>{badgeLabel}</span>
              </div>
              {sub.package_description && (
                <p className="text-xs text-gray-400 mt-0.5">{sub.package_description}</p>
              )}
            </div>
          </div>
          {sub.addon_rt_price > 0 ? (
            <div className="text-right">
              <p className="text-sm font-semibold text-emerald-600 whitespace-nowrap">
                {fmtPrice(sub.price + sub.addon_rt_price, sub.period)}
              </p>
              <p className="text-xs text-gray-400 whitespace-nowrap">
                Paket {fmt(sub.price)} + Addon {fmt(sub.addon_rt_price)}
              </p>
            </div>
          ) : (
            <p className="text-sm font-semibold text-emerald-600 whitespace-nowrap">{fmtPrice(sub.price, sub.period)}</p>
          )}
        </div>
        <div className="mt-3 pt-3 border-t border-gray-100 dark:border-gray-700 grid grid-cols-2 gap-3 text-sm">
          <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400">
            <CalendarDays size={14} className="flex-shrink-0" />
            <span>Mulai: <span className="text-gray-700 dark:text-gray-300 font-medium">{fmtDate(sub.start_date)}</span></span>
          </div>
          <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400">
            <CalendarDays size={14} className="flex-shrink-0" />
            <span>Berakhir: <span className={`font-medium ${d <= 7 && !sub.is_blocked ? 'text-red-600' : d <= 30 ? 'text-amber-600' : 'text-gray-700 dark:text-gray-300'}`}>{fmtDate(sub.end_date)}</span></span>
          </div>
        </div>

        {/* Addon RT info */}
        {(sub.rt_max || sub.addon_rt_active > 0 || sub.addon_rt_pending > 0) && (
          <div className="mt-3 pt-3 border-t border-gray-100 dark:border-gray-700 flex items-center justify-between gap-3">
            <div className="flex flex-wrap gap-3 text-xs text-gray-500 dark:text-gray-400">
              {sub.rt_max && (
                <span>Batas RT paket: <span className="font-semibold text-gray-700 dark:text-gray-300">{sub.rt_max} RT</span></span>
              )}
              {sub.addon_rt_active > 0 && (
                <span className="text-emerald-600 font-medium">+{sub.addon_rt_active} RT addon aktif</span>
              )}
              {sub.rt_max_effective && sub.addon_rt_active > 0 && (
                <span className="font-bold text-gray-700 dark:text-gray-300">→ Total: {sub.rt_max_effective} RT</span>
              )}
              {sub.addon_rt_pending > 0 && (
                <span className="text-amber-600">+{sub.addon_rt_pending} RT pending approval</span>
              )}
            </div>
            <button
              onClick={() => { if (!sub.addon_rt_pending) setAddonModal(true); }}
              disabled={sub.addon_rt_pending > 0}
              title={sub.addon_rt_pending > 0 ? 'Masih ada request RT yang belum aktif, tunggu hingga disetujui vendor' : 'Tambah RT'}
              className={`flex-shrink-0 flex items-center gap-1 text-xs font-medium whitespace-nowrap transition-colors ${
                sub.addon_rt_pending > 0
                  ? 'text-gray-400 cursor-not-allowed opacity-60'
                  : 'text-violet-600 hover:text-violet-700 cursor-pointer'
              }`}>
              <Plus size={12} /> Tambah RT
            </button>
          </div>
        )}

        {/* Tombol request jika tidak ada rt_max (paket tidak punya batasan RT) */}
        {!sub.rt_max && (
          <div className="mt-2 flex justify-end">
            <button
              onClick={() => { if (!sub.addon_rt_pending) setAddonModal(true); }}
              disabled={sub.addon_rt_pending > 0}
              title={sub.addon_rt_pending > 0 ? 'Masih ada request RT yang belum aktif, tunggu hingga disetujui vendor' : 'Request Tambah RT'}
              className={`flex items-center gap-1 text-xs font-medium transition-colors ${
                sub.addon_rt_pending > 0
                  ? 'text-gray-400 cursor-not-allowed opacity-60'
                  : 'text-violet-600 hover:text-violet-700 cursor-pointer'
              }`}>
              <Plus size={12} /> Request Tambah RT
            </button>
          </div>
        )}
      </div>

      {addonModal && (
        <AddonRequestModal sub={sub} token={token}
          onClose={() => setAddonModal(false)}
          onSuccess={() => { setAddonModal(false); if (onRefresh) onRefresh(); }} />
      )}
    </div>
  );
}

// ── Tab: Tagihan ───────────────────────────────────────────────────────────
function TabTagihan({ invoices, transactions, activeGateways, token, onRefresh, onSwitchTab }) {
  const [filter, setFilter] = useState('all');
  const [payModal, setPayModal] = useState(null);

  const filtered = filter === 'all' ? invoices : invoices.filter((i) => i.status === filter);
  const unpaid  = invoices.filter((i) => i.status === 'unpaid').length;
  const overdue = invoices.filter((i) => i.status === 'overdue').length;
  const outstanding = invoices.filter((i) => ['unpaid','overdue'].includes(i.status)).reduce((s,i) => s+(i.amount||0), 0);

  const nowMs = Date.now();
  const hasActivePending = (invoiceId) => transactions.some((t) =>
    t.invoice_id === invoiceId && t.status === 'pending' && txRemainingMs(t.created_at, nowMs) > 0
  );

  const TABS = [
    { key: 'all',     label: 'Semua',        count: invoices.length },
    { key: 'unpaid',  label: 'Belum Dibayar', count: unpaid },
    { key: 'overdue', label: 'Jatuh Tempo',   count: overdue },
    { key: 'paid',    label: 'Sudah Dibayar', count: invoices.filter((i) => i.status === 'paid').length },
  ];

  return (
    <div className="space-y-4">
      {/* Mini stats */}
      <div className="grid grid-cols-3 gap-3">
        {[
          { label: 'Belum Dibayar', value: unpaid,       icon: Clock,        color: 'bg-amber-50 dark:bg-amber-900/20 text-amber-600' },
          { label: 'Jatuh Tempo',   value: overdue,      icon: AlertCircle,  color: 'bg-red-50 dark:bg-red-900/20 text-red-600' },
          { label: 'Tertunggak',    value: fmt(outstanding), icon: Receipt,  color: 'bg-orange-50 dark:bg-orange-900/20 text-orange-600', small: true },
        ].map(({ label, value, icon: Icon, color, small }) => (
          <div key={label} className="bg-white dark:bg-gray-800 rounded-xl p-4 border border-gray-100 dark:border-gray-700 flex items-center gap-3">
            <div className={`w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0 ${color}`}>
              <Icon size={17} />
            </div>
            <div>
              <p className={`font-bold text-gray-900 dark:text-gray-100 ${small ? 'text-sm' : 'text-xl'}`}>{value}</p>
              <p className="text-xs text-gray-400">{label}</p>
            </div>
          </div>
        ))}
      </div>

      {/* Table card */}
      <div className="bg-white dark:bg-gray-800 rounded-2xl border border-gray-100 dark:border-gray-700">
        {/* Filter tabs */}
        <div className="px-5 pt-4 pb-0 flex flex-wrap gap-1 border-b dark:border-gray-700">
          {TABS.map((t) => (
            <button key={t.key} onClick={() => setFilter(t.key)}
              className={`px-4 py-2 text-sm font-medium rounded-t-lg transition-colors border-b-2 -mb-px ${filter === t.key ? 'border-emerald-500 text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20' : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700'}`}>
              {t.label}
              {t.count > 0 && <span className={`ml-1.5 text-xs px-1.5 py-0.5 rounded-full ${filter === t.key ? 'bg-emerald-200 text-emerald-700' : 'bg-gray-100 dark:bg-gray-700 text-gray-500'}`}>{t.count}</span>}
            </button>
          ))}
        </div>

        {filtered.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-14 text-gray-400 gap-2">
            <Receipt size={34} strokeWidth={1.5} /><p className="text-sm">Tidak ada tagihan</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow className="bg-gray-50 dark:bg-gray-700/50">
                  {['No. Invoice','Paket','Nominal','Status','Jatuh Tempo','Dibayar','Aksi'].map((h) => (
                    <TableHead key={h} className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide first:pl-5 last:pr-5">{h}</TableHead>
                  ))}
                </TableRow>
              </TableHeader>
              <TableBody>
                {filtered.map((inv) => {
                  const st = INV_STATUS[inv.status] || INV_STATUS.unpaid;
                  const canPay = inv.status === 'unpaid' || inv.status === 'overdue';
                  const pending = canPay && hasActivePending(inv.id);
                  return (
                    <TableRow key={inv.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/30 transition-colors">
                      <TableCell className="font-medium text-gray-900 dark:text-gray-100 pl-5">{inv.invoice_number}</TableCell>
                      <TableCell className="text-gray-500 dark:text-gray-400 text-sm">{inv.package_name || '-'}</TableCell>
                      <TableCell className="font-semibold text-gray-900 dark:text-gray-100">{fmt(inv.amount)}</TableCell>
                      <TableCell><span className={`text-xs font-medium px-2.5 py-1 rounded-full border ${st.cls}`}>{st.label}</span></TableCell>
                      <TableCell className={`text-sm ${inv.status === 'overdue' ? 'text-red-600 font-medium' : 'text-gray-500 dark:text-gray-400'}`}>{fmtDate(inv.due_date)}</TableCell>
                      <TableCell className="text-sm text-gray-400">{fmtDate(inv.paid_date)}</TableCell>
                      <TableCell className="pr-5">
                        {canPay && (
                          pending ? (
                            <button onClick={() => onSwitchTab && onSwitchTab('transaksi')}
                              className="flex items-center gap-1.5 px-3 py-1.5 bg-amber-500 hover:bg-amber-600 text-white text-xs font-medium rounded-lg transition-colors"
                              title="Ada transaksi pending — selesaikan atau tunggu sampai expired">
                              <Clock size={12} />Cek Transaksi
                            </button>
                          ) : (
                            <button onClick={() => setPayModal(inv)}
                              className="flex items-center gap-1.5 px-3 py-1.5 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-medium rounded-lg transition-colors">
                              <CreditCard size={12} />Bayar Online
                            </button>
                          )
                        )}
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </div>
        )}
      </div>

      {payModal && (
        <PaymentModal
          invoice={payModal} activeGateways={activeGateways} token={token}
          onClose={() => setPayModal(null)}
          onSuccess={() => {
            setPayModal(null);
            if (onSwitchTab) onSwitchTab('transaksi');
            onRefresh();
          }}
        />
      )}
    </div>
  );
}

// ── Tab: Transaksi ─────────────────────────────────────────────────────────
function TabTransaksi({ transactions, onRefresh }) {
  const [search, setSearch]   = useState('');
  const [gw, setGw]           = useState('all');
  const [status, setStatus]   = useState('all');
  const [detailTx, setDetailTx] = useState(null);
  const [now, setNow]         = useState(Date.now());

  useEffect(() => {
    const i = setInterval(() => setNow(Date.now()), 10_000);
    return () => clearInterval(i);
  }, []);

  // Derive effective status: pending tx past its 60-min window shows as expired locally
  const txEffectiveStatus = (tx) => {
    if (tx.status === 'pending' && txRemainingMs(tx.created_at, now) === 0) return 'expired';
    return tx.status;
  };

  const GW_OPTS = [
    { value: 'all', label: 'Semua Gateway' }, { value: 'xendit', label: 'Xendit' }, { value: 'midtrans', label: 'Midtrans' },
  ];
  const ST_OPTS = [
    { value: 'all', label: 'Semua Status' }, { value: 'pending', label: 'Pending' },
    { value: 'paid', label: 'Berhasil' }, { value: 'failed', label: 'Gagal' }, { value: 'expired', label: 'Expired' },
  ];

  const filtered = transactions.filter((tx) => {
    if (gw !== 'all' && tx.gateway !== gw) return false;
    if (status !== 'all' && txEffectiveStatus(tx) !== status) return false;
    if (search) {
      const q = search.toLowerCase();
      if (!tx.external_id?.toLowerCase().includes(q) && !tx.invoice_number?.toLowerCase().includes(q)) return false;
    }
    return true;
  });

  const paid  = transactions.filter((t) => txEffectiveStatus(t) === 'paid').length;
  const pend  = transactions.filter((t) => txEffectiveStatus(t) === 'pending').length;
  const fail  = transactions.filter((t) => ['failed','expired'].includes(txEffectiveStatus(t))).length;

  return (
    <div className="space-y-4">
      {/* Mini stats */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        {[
          { label: 'Total',        value: transactions.length, icon: ArrowLeftRight, color: 'bg-blue-50 dark:bg-blue-900/20 text-blue-600' },
          { label: 'Berhasil',     value: paid,                icon: CheckCircle,    color: 'bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600' },
          { label: 'Pending',      value: pend,                icon: Clock,          color: 'bg-amber-50 dark:bg-amber-900/20 text-amber-600' },
          { label: 'Gagal/Expired',value: fail,                icon: XCircle,        color: 'bg-red-50 dark:bg-red-900/20 text-red-600' },
        ].map(({ label, value, icon: Icon, color }) => (
          <div key={label} className="bg-white dark:bg-gray-800 rounded-xl p-4 border border-gray-100 dark:border-gray-700 flex items-center gap-3">
            <div className={`w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0 ${color}`}>
              <Icon size={17} />
            </div>
            <div>
              <p className="text-xl font-bold text-gray-900 dark:text-gray-100">{value}</p>
              <p className="text-xs text-gray-400">{label}</p>
            </div>
          </div>
        ))}
      </div>

      {/* Table card */}
      <div className="bg-white dark:bg-gray-800 rounded-2xl border border-gray-100 dark:border-gray-700">
        {/* Filters */}
        <div className="p-4 border-b dark:border-gray-700 flex flex-wrap gap-3 items-center">
          <div className="flex items-center gap-2 flex-1 min-w-[180px] bg-gray-50 dark:bg-gray-700/50 border border-gray-200 dark:border-gray-600 rounded-xl px-3 py-2">
            <Search size={14} className="text-gray-400 flex-shrink-0" />
            <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Cari no.ref atau invoice..." className="bg-transparent text-sm text-gray-700 dark:text-gray-300 placeholder-gray-400 outline-none flex-1" />
          </div>
          <Dropdown value={gw}     onChange={setGw}     options={GW_OPTS} />
          <Dropdown value={status} onChange={setStatus} options={ST_OPTS} />
        </div>

        {filtered.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-14 text-gray-400 gap-2">
            <ArrowLeftRight size={34} strokeWidth={1.5} /><p className="text-sm">Tidak ada transaksi</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow className="bg-gray-50 dark:bg-gray-700/50">
                  {['No. Referensi','No. Invoice','Gateway','Nominal','Status','Tanggal','Aksi'].map((h) => (
                    <TableHead key={h} className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide first:pl-5 last:pr-5">{h}</TableHead>
                  ))}
                </TableRow>
              </TableHeader>
              <TableBody>
                {filtered.map((tx) => {
                  const eff = txEffectiveStatus(tx);
                  const st  = TX_STATUS[eff] || TX_STATUS.pending;
                  const remaining = eff === 'pending' ? txRemainingMs(tx.created_at, now) : 0;
                  const remainMin = Math.floor(remaining / 60_000);
                  const remainSec = Math.floor((remaining % 60_000) / 1000);
                  return (
                    <TableRow key={tx.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/30 transition-colors">
                      <TableCell className="pl-5 font-mono text-xs text-gray-600 dark:text-gray-400">{tx.external_id}</TableCell>
                      <TableCell className="font-medium text-gray-800 dark:text-gray-200">{tx.invoice_number || '-'}</TableCell>
                      <TableCell><span className={`text-xs font-medium px-2.5 py-1 rounded-full ${GW_META[tx.gateway]?.cls || 'bg-gray-100 text-gray-600'}`}>{GW_META[tx.gateway]?.name || tx.gateway}</span></TableCell>
                      <TableCell className="font-semibold text-gray-900 dark:text-gray-100">{fmt(tx.amount)}</TableCell>
                      <TableCell>
                        <div className="flex flex-col gap-1">
                          <span className={`flex items-center gap-1.5 w-fit text-xs font-medium px-2.5 py-1 rounded-full border ${st.cls}`}>
                            <st.Icon size={11} />{st.label}
                          </span>
                          {eff === 'pending' && (
                            <span className="text-[10px] text-amber-600 dark:text-amber-400 font-medium tabular-nums">
                              {remainMin}m {remainSec.toString().padStart(2,'0')}s lagi
                            </span>
                          )}
                        </div>
                      </TableCell>
                      <TableCell className="text-sm text-gray-500 dark:text-gray-400">{fmtDateTime(tx.created_at)}</TableCell>
                      <TableCell className="pr-5">
                        <div className="flex items-center gap-1.5">
                          <button onClick={() => setDetailTx(tx)} className="flex items-center gap-1 px-2.5 py-1.5 border border-gray-200 dark:border-gray-600 text-xs font-medium text-gray-600 dark:text-gray-400 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors">
                            <Eye size={12} />Lihat
                          </button>
                          {eff === 'pending' && tx.payment_url && (
                            <a href={tx.payment_url} target="_blank" rel="noreferrer"
                              className="flex items-center gap-1 px-2.5 py-1.5 bg-amber-500 hover:bg-amber-600 text-white text-xs font-medium rounded-lg transition-colors">
                              <ExternalLink size={12} />Buka
                            </a>
                          )}
                        </div>
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </div>
        )}
      </div>
      {detailTx && <TxDetailModal tx={detailTx} onClose={() => setDetailTx(null)} />}
    </div>
  );
}

// ── Main Component ─────────────────────────────────────────────────────────
const KelurahanBilling = () => {
  const { token } = useAuth();
  const [invoices, setInvoices]         = useState([]);
  const [transactions, setTransactions] = useState([]);
  const [activeGateways, setActiveGateways] = useState([]);
  const [subscription, setSubscription] = useState(null);
  const [loading, setLoading]           = useState(true);
  const [error, setError]               = useState(null);
  const [activeTab, setActiveTab]       = useState('tagihan');

  const apiFetch = useCallback(async (path) => {
    const res = await fetch(`${API_BASE_URL}${path}`, {
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    });
    if (res.status === 401) {
      localStorage.removeItem('token');
      localStorage.removeItem('user');
      window.location.href = '/login';
      throw new Error('Sesi berakhir, silakan login kembali');
    }
    if (!res.ok) {
      let detail = `HTTP ${res.status}`;
      try { const j = await res.json(); detail = j.detail || detail; } catch (_) {}
      throw new Error(detail);
    }
    return res.json();
  }, [token]);

  const fetchAll = useCallback(async () => {
    if (!token) return;
    setLoading(true); setError(null);
    try {
      const data = await apiFetch('/api/tenant/my-subscription');
      setSubscription(data || null);
    } catch (e) {
      console.error('[Billing] subscription error:', e.message);
      setSubscription(null);
    }
    try {
      const data = await apiFetch('/api/tenant/invoices');
      setInvoices(Array.isArray(data) ? data : []);
    } catch (e) {
      console.error('[Billing] invoices error:', e.message);
      setError(e.message || 'Gagal memuat tagihan');
      setLoading(false);
      return;
    }
    try {
      const data = await apiFetch('/api/tenant/payment-transactions');
      setTransactions(Array.isArray(data) ? data : []);
    } catch (e) {
      console.error('[Billing] transactions error:', e.message);
      setTransactions([]);
    }
    try {
      const data = await apiFetch('/api/tenant/active-gateways');
      setActiveGateways(Array.isArray(data) ? data : []);
    } catch (e) {
      console.error('[Billing] gateways error:', e.message);
      setActiveGateways([]);
    }
    setLoading(false);
  }, [token, apiFetch]);

  useEffect(() => { fetchAll(); }, [fetchAll]);

  if (loading) {
    return (
      <div className="p-6 min-h-full flex items-center justify-center bg-[#efe7d2] dark:bg-gray-900">
        <div className="text-center space-y-3">
          <div className="w-11 h-11 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin mx-auto" />
          <p className="text-sm text-gray-500 dark:text-gray-400">Memuat data billing...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6 min-h-full bg-[#efe7d2] dark:bg-gray-900">
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-700 rounded-2xl p-6 flex items-start gap-4">
          <AlertCircle size={22} className="text-red-500 flex-shrink-0 mt-0.5" />
          <div>
            <p className="font-medium text-red-700 dark:text-red-400">Gagal memuat data</p>
            <p className="text-sm text-red-600 dark:text-red-300 mt-1">{error}</p>
            <button onClick={fetchAll} className="mt-3 text-sm font-medium text-red-600 underline">Coba lagi</button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full space-y-5">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100">Billing</h1>
          <p className="text-sm text-gray-500 dark:text-gray-400 mt-0.5">Kelola tagihan langganan dan riwayat pembayaran</p>
        </div>
        <button onClick={fetchAll}
          className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl text-sm font-medium text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors shadow-sm">
          <RefreshCw size={14} />Refresh
        </button>
      </div>

      {/* Subscription Info */}
      <SubscriptionCard sub={subscription} token={token} onRefresh={fetchAll} />

      {/* Tabs */}
      <div className="flex gap-1 bg-white dark:bg-gray-800 p-1 rounded-xl border border-gray-200 dark:border-gray-700 w-fit shadow-sm">
        {[
          { key: 'tagihan',   label: 'Tagihan',   icon: Receipt,         count: invoices.filter((i) => ['unpaid','overdue'].includes(i.status)).length },
          { key: 'transaksi', label: 'Transaksi', icon: ArrowLeftRight,  count: transactions.length },
        ].map(({ key, label, icon: Icon, count }) => (
          <button key={key} onClick={() => setActiveTab(key)}
            className={`flex items-center gap-2 px-5 py-2 rounded-lg text-sm font-medium transition-all ${activeTab === key ? 'bg-emerald-600 text-white shadow-sm' : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700'}`}>
            <Icon size={15} />{label}
            {count > 0 && (
              <span className={`text-xs px-1.5 py-0.5 rounded-full font-medium ${activeTab === key ? 'bg-emerald-500 text-white' : 'bg-gray-100 dark:bg-gray-700 text-gray-500 dark:text-gray-400'}`}>{count}</span>
            )}
          </button>
        ))}
      </div>

      {/* Content */}
      {activeTab === 'tagihan' ? (
        <TabTagihan
          invoices={invoices} transactions={transactions} activeGateways={activeGateways}
          token={token} onRefresh={fetchAll} onSwitchTab={setActiveTab}
        />
      ) : (
        <TabTransaksi transactions={transactions} onRefresh={fetchAll} />
      )}
    </div>
  );
};

export default KelurahanBilling;
