import { useEffect, useState } from "react";

import { API_BASE_URL } from "@/config/api";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import KeuanganTable from "./KeuanganTable";
import KeuanganForm from "./KeuanganForm";
import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogCancel,
  AlertDialogAction
} from "@/components/ui/alert-dialog";
import * as XLSX from "xlsx";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "@/components/ui/sonner";
import { useRolePermissions } from "@/hooks/useRolePermissions";


export default function KeuanganPage() {
  const [transaksi, setTransaksi] = useState([]);
  const [search, setSearch] = useState("");
  const { token, user, logout } = useAuth();
  const { canCreate, canDelete } = useRolePermissions(user?.role, token);

  // FORM
  const [openForm, setOpenForm] = useState(false);
  const [selectedTransaksi, setSelectedTransaksi] = useState(null);

  // MULTI SELECT
  const [selectedRows, setSelectedRows] = useState([]);

  // FILTER
  const [showFilter, setShowFilter] = useState(false);
  const [filterTipe, setFilterTipe] = useState("all");
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");

  // BULK DELETE DIALOG
  const [openBulkDelete, setOpenBulkDelete] = useState(false);

  // PAGINATION
  const [page, setPage] = useState(1);
  const [perPage, setPerPage] = useState(25);

  // SALDO
  const [saldo, setSaldo] = useState({
    saldo: 0,
    total_pemasukan: 0,
    total_pengeluaran: 0
  });


  const loadTransaksi = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/keuangan`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.status === 401) {
        logout();
        return;
      }

      const data = await res.json();
      setTransaksi(Array.isArray(data) ? data : []);

      // Load saldo
      const saldoRes = await fetch(`${API_BASE_URL}/api/keuangan/saldo/kas`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      const saldoData = await saldoRes.json();
      setSaldo(saldoData);

    } catch (err) {
      console.error("Gagal load transaksi", err);
      toast.error("Gagal memuat data keuangan");
    }
  };

  useEffect(() => {
    loadTransaksi();
  }, []);

  // FILTER LOGIC
  const filtered = transaksi
    .filter((t) =>
      t.kategori.toLowerCase().includes(search.toLowerCase()) ||
      (t.deskripsi && t.deskripsi.toLowerCase().includes(search.toLowerCase()))
    )
    .filter((t) => {
      if (filterTipe === "pemasukan") return t.tipe === "pemasukan";
      if (filterTipe === "pengeluaran") return t.tipe === "pengeluaran";
      return true;
    })
    .filter((t) => {
      if (!startDate && !endDate) return true;
      
      // Extract date only (YYYY-MM-DD) - hindari timezone issue
      // t.tanggal format: 2025-12-18T10:00:00 atau 2025-12-18T10:00:00+07:00
      const txDateStr = t.tanggal.split('T')[0];
      
      // Compare as strings (YYYY-MM-DD format)
      if (startDate && txDateStr < startDate) return false;  // >= startDate
      if (endDate && txDateStr > endDate) return false;      // <= endDate
      
      return true;
    });

  // SORT BY TANGGAL (NEWEST FIRST)
  const sortedData = [...filtered].sort((a, b) => 
    new Date(b.tanggal) - new Date(a.tanggal)
  );

  // PAGINATION
  const totalPages = Math.ceil(sortedData.length / perPage);
  const paginatedData = sortedData.slice((page - 1) * perPage, page * perPage);

  // EXPORT EXCEL
  const exportExcel = () => {
    const worksheet = XLSX.utils.json_to_sheet(filtered);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Keuangan");
    XLSX.writeFile(workbook, "keuangan.xlsx");
  };

  // BULK DELETE
  const doBulkDelete = async () => {
    for (const id of selectedRows) {
      await fetch(`${API_BASE_URL}/api/keuangan/${id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
    }
    toast.success(`${selectedRows.length} transaksi berhasil dihapus`);
    loadTransaksi();
    setSelectedRows([]);
    setOpenBulkDelete(false);
  };

  const formatRupiah = (val) => {
    return new Intl.NumberFormat("id-ID", {
      style: "currency",
      currency: "IDR",
      minimumFractionDigits: 0,
    }).format(val);
  };

  return (
    <div className="p-6 space-y-6">
      {/* HEADER */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold dark:text-gray-100">Keuangan</h1>
          <p className="text-sm text-gray-600 dark:text-gray-400">Kelola transaksi keuangan RT</p>
        </div>
        {canCreate('finance') && (
          <Button
            onClick={() => {
              setSelectedTransaksi(null);
              setOpenForm(true);
            }}
            className="bg-[#ed6f5c] hover:bg-[#e05544] text-white"
          >
            + Tambah Transaksi
          </Button>
        )}
      </div>

      {/* STATS CARDS */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {/* SALDO KAS */}
        <div className="bg-[#f7f1de] dark:bg-gray-900 p-6 rounded-lg border dark:border-gray-700 shadow-sm">
          <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Saldo Kas</p>
          <p className={`text-2xl font-bold mt-2 ${
            saldo.saldo >= 0
              ? "text-green-600 dark:text-green-400"
              : "text-red-600 dark:text-red-400"
          }`}>
            {formatRupiah(saldo.saldo)}
          </p>
        </div>

        {/* TOTAL PEMASUKAN */}
        <div className="bg-[#f7f1de] dark:bg-gray-900 p-6 rounded-lg border dark:border-gray-700 shadow-sm">
          <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Total Pemasukan</p>
          <p className="text-2xl font-bold text-green-600 dark:text-green-400 mt-2">
            {formatRupiah(saldo.total_pemasukan)}
          </p>
        </div>

        {/* TOTAL PENGELUARAN */}
        <div className="bg-[#f7f1de] dark:bg-gray-900 p-6 rounded-lg border dark:border-gray-700 shadow-sm">
          <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Total Pengeluaran</p>
          <p className="text-2xl font-bold text-red-600 dark:text-red-400 mt-2">
            {formatRupiah(saldo.total_pengeluaran)}
          </p>
        </div>
      </div>

      {/* SEARCH & FILTER */}
      <div className="flex gap-3">
        <Input
          placeholder="Cari kategori atau deskripsi..."
          value={search}
          onChange={(e) => {
            setSearch(e.target.value);
            setPage(1);
          }}
          className="flex-1 dark:bg-gray-800 dark:text-gray-100 dark:border-gray-700"
        />
        <Button
          variant="outline"
          onClick={() => setShowFilter(!showFilter)}
          className="dark:border-gray-700 dark:text-gray-200"
        >
          Filter
        </Button>
      </div>

      {/* FILTER PANEL */}
      {showFilter && (
        <div className="bg-[#f7f1de] dark:bg-gray-900 p-6 rounded-lg border dark:border-gray-700 space-y-4">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            {/* TIPE TRANSAKSI */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Tipe Transaksi</label>
              <select
                value={filterTipe}
                onChange={(e) => {
                  setFilterTipe(e.target.value);
                  setPage(1);
                }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[#ece4cf]"
              >
                <option value="all">Semua</option>
                <option value="pemasukan">Pemasukan</option>
                <option value="pengeluaran">Pengeluaran</option>
              </select>
            </div>

            {/* TANGGAL AWAL */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Tanggal Awal</label>
              <input
                type="date"
                value={startDate}
                onChange={(e) => {
                  setStartDate(e.target.value);
                  setPage(1);
                }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[#ece4cf]"
              />
            </div>

            {/* TANGGAL AKHIR */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Tanggal Akhir</label>
              <input
                type="date"
                value={endDate}
                onChange={(e) => {
                  setEndDate(e.target.value);
                  setPage(1);
                }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[#ece4cf]"
              />
            </div>

            {/* PER HALAMAN */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Per Halaman</label>
              <select
                value={perPage}
                onChange={(e) => {
                  setPerPage(Number(e.target.value));
                  setPage(1);
                }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[#ece4cf]"
              >
                <option value="5">5</option>
                <option value="10">10</option>
                <option value="25">25</option>
              </select>
            </div>
          </div>
        </div>
      )}

      {/* ACTIONS */}
      {selectedRows.length > 0 && canDelete('finance') && (
        <div className="flex gap-3 bg-blue-50 dark:bg-blue-900/20 p-4 rounded-lg border border-blue-200 dark:border-blue-800">
          <span className="text-sm dark:text-gray-300">
            {selectedRows.length} item dipilih
          </span>
          <Button
            size="sm"
            variant="destructive"
            onClick={() => setOpenBulkDelete(true)}
          >
            Hapus
          </Button>
          <Button
            size="sm"
            onClick={exportExcel}
            className="bg-green-500 hover:bg-green-600 text-white"
          >
            Export Excel
          </Button>
        </div>
      )}

      {/* TABLE */}
      <div className="bg-[#f7f1de] dark:bg-gray-900 rounded-lg border dark:border-gray-700">
        <KeuanganTable
          data={paginatedData}
          onEdit={(t) => {
            setSelectedTransaksi(t);
            setOpenForm(true);
          }}
          onDelete={loadTransaksi}
          selectedRows={selectedRows}
          setSelectedRows={setSelectedRows}
        />
      </div>

      {/* PAGINATION INFO */}
      <div className="flex justify-between items-center text-sm text-gray-600 dark:text-gray-400 px-2">
        <span>
          {sortedData.length === 0 ? "Tidak ada data" : `${(page - 1) * perPage + 1}-${Math.min(page * perPage, sortedData.length)} dari ${sortedData.length}`}
        </span>
        <div className="flex gap-2">
          <Button
            size="sm"
            variant="outline"
            onClick={() => setPage(Math.max(1, page - 1))}
            disabled={page === 1}
            className="dark:border-gray-700 dark:text-gray-200"
          >
            Sebelumnya
          </Button>
          <Button
            size="sm"
            variant="outline"
            onClick={() => setPage(Math.min(totalPages, page + 1))}
            disabled={page === totalPages}
            className="dark:border-gray-700 dark:text-gray-200"
          >
            Selanjutnya
          </Button>
        </div>
      </div>

      {/* FORM DIALOG */}
      <KeuanganForm
        open={openForm}
        onOpenChange={setOpenForm}
        transaksi={selectedTransaksi}
        onSaved={() => {
          loadTransaksi();
          setSelectedTransaksi(null);
        }}
      />

      {/* BULK DELETE DIALOG */}
      <AlertDialog open={openBulkDelete} onOpenChange={setOpenBulkDelete}>
        <AlertDialogContent className="bg-[#f7f1de] dark:bg-gray-900 dark:text-gray-100">
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus {selectedRows.length} Transaksi?</AlertDialogTitle>
          </AlertDialogHeader>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Tindakan ini tidak dapat dibatalkan.
          </p>
          <AlertDialogFooter>
            <AlertDialogCancel className="dark:bg-gray-800 dark:text-gray-200">
              Batal
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={doBulkDelete}
              className="bg-red-600 hover:bg-red-700"
            >
              Hapus Semua
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}
