import React, { useState, useEffect, useMemo } from 'react';
import { API_BASE_URL } from '../../config/api';
import { vendorConfirm, vendorAlert } from './VendorConfirm';
import {
  Building2,
  CheckCircle,
  XCircle,
  ChevronDown,
  ChevronRight,
} from 'lucide-react';


const TYPE_BADGE = {
  kelurahan: 'bg-purple-100 text-purple-800',
  rw:        'bg-blue-100 text-blue-800',
  rt:        'bg-teal-100 text-teal-800',
};

function buildTree(tenants) {
  const map = {};
  tenants.forEach(t => { map[t.id] = { ...t, children: [] }; });
  const roots = [];
  tenants.forEach(t => {
    if (t.parent_id && map[t.parent_id]) {
      map[t.parent_id].children.push(map[t.id]);
    } else {
      roots.push(map[t.id]);
    }
  });
  // Sort: kelurahan → rw → rt, then alphabetically within type
  const typeOrder = { kelurahan: 0, rw: 1, rt: 2 };
  const sortNodes = (nodes) => {
    nodes.sort((a, b) => {
      const ta = (a.tenant_type || '').toLowerCase();
      const tb = (b.tenant_type || '').toLowerCase();
      const diff = (typeOrder[ta] ?? 9) - (typeOrder[tb] ?? 9);
      return diff !== 0 ? diff : a.name.localeCompare(b.name);
    });
    nodes.forEach(n => sortNodes(n.children));
    return nodes;
  };
  return sortNodes(roots);
}

function TenantRow({ node, depth }) {
  const [open, setOpen] = useState(false);
  const hasChildren = node.children.length > 0;
  const isActive = node.status === 'active';
  const type = (node.tenant_type || 'rt').toLowerCase();

  const indent = depth * 24; // px

  return (
    <>
      <tr className={`border-b border-gray-100 hover:bg-gray-50 transition-colors ${depth === 0 ? 'bg-gray-50/60' : ''}`}>
        {/* Nama */}
        <td className="px-4 py-3">
          <div className="flex items-center gap-1.5" style={{ paddingLeft: indent }}>
            {hasChildren ? (
              <button
                onClick={() => setOpen(o => !o)}
                className="w-5 h-5 flex items-center justify-center text-gray-400 hover:text-gray-700 flex-shrink-0"
              >
                {open ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
              </button>
            ) : (
              <span className="w-5 h-5 flex-shrink-0 flex items-center justify-center">
                <span className="w-1.5 h-1.5 rounded-full bg-gray-300 inline-block" />
              </span>
            )}
            <span className={`font-${depth === 0 ? 'semibold' : depth === 1 ? 'medium' : 'normal'} text-gray-800 text-sm`}>
              {node.name}
            </span>
          </div>
        </td>

        {/* Tipe */}
        <td className="px-4 py-3">
          <span className={`inline-flex px-2 py-0.5 rounded-full text-xs font-semibold uppercase ${TYPE_BADGE[type] || 'bg-gray-100 text-gray-700'}`}>
            {node.tenant_type || '-'}
          </span>
        </td>

        {/* Alamat */}
        <td className="px-4 py-3">
          <p className="text-sm text-gray-600">{node.address || '-'}</p>
          {node.city && <p className="text-xs text-gray-400">{node.city}{node.province ? `, ${node.province}` : ''}</p>}
        </td>

        {/* Status */}
        <td className="px-4 py-3">
          <span className={`inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-medium ${
            isActive ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'
          }`}>
            {isActive ? <CheckCircle size={10} /> : <XCircle size={10} />}
            {isActive ? 'Aktif' : 'Suspended'}
          </span>
        </td>
      </tr>

      {/* Children */}
      {open && node.children.map(child => (
        <TenantRow key={child.id} node={child} depth={depth + 1} />
      ))}
    </>
  );
}

const VendorDashboard = () => {
  const [tenants, setTenants] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [stats, setStats] = useState({ total: 0, active: 0, suspended: 0 });

  useEffect(() => { loadTenants(); }, []);

  const loadTenants = async () => {
    const token = localStorage.getItem('vendor_token');
    if (!token) { setError('Session berakhir. Silakan login kembali.'); setLoading(false); return; }
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/tenants`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      if (!res.ok) { const d = await res.json(); throw new Error(d.detail || 'Gagal memuat data'); }
      const data = await res.json();
      setTenants(data);
      const active = data.filter(t => t.status === 'active').length;
      setStats({ total: data.length, active, suspended: data.length - active });
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleStatusChange = async (tenantId, newStatus) => {
    const label = newStatus === 'suspended' ? 'Suspend' : 'Aktifkan';
    if (!await vendorConfirm(`${label} tenant ini?`, `${label} Tenant`)) return;
    const token = localStorage.getItem('vendor_token');
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/tenants/${tenantId}/status`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({ status: newStatus })
      });
      if (!res.ok) { const d = await res.json(); throw new Error(d.detail || 'Gagal mengubah status'); }
      loadTenants();
    } catch (err) {
      vendorAlert(err.message, 'Gagal');
    }
  };

  const tree = useMemo(() => buildTree(tenants), [tenants]);

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="w-12 h-12 border-4 border-[#ed6f5c] border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-2xl font-bold text-gray-800">Dashboard Vendor</h1>
        <p className="text-gray-500">Kelola Tenant RT/RW</p>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white rounded-xl p-6 border border-gray-200">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-500">Total Tenant</p>
              <p className="text-3xl font-bold text-gray-800">{stats.total}</p>
            </div>
            <div className="w-12 h-12 bg-[#ed6f5c] rounded-lg flex items-center justify-center">
              <Building2 className="w-6 h-6 text-white" />
            </div>
          </div>
        </div>
        <div className="bg-white rounded-xl p-6 border border-gray-200">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-500">Tenant Aktif</p>
              <p className="text-3xl font-bold text-emerald-600">{stats.active}</p>
            </div>
            <div className="w-12 h-12 bg-emerald-100 rounded-lg flex items-center justify-center">
              <CheckCircle className="w-6 h-6 text-emerald-600" />
            </div>
          </div>
        </div>
        <div className="bg-white rounded-xl p-6 border border-gray-200">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-500">Tenant Suspended</p>
              <p className="text-3xl font-bold text-red-600">{stats.suspended}</p>
            </div>
            <div className="w-12 h-12 bg-red-100 rounded-lg flex items-center justify-center">
              <XCircle className="w-6 h-6 text-red-600" />
            </div>
          </div>
        </div>
      </div>

      {/* Hierarchy Tree */}
      <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
        <div className="px-6 py-4 border-b border-gray-200 flex items-center justify-between">
          <h2 className="text-lg font-semibold text-gray-800">Daftar Tenant</h2>
          <div className="flex items-center gap-3 text-xs text-gray-400">
            <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-purple-400 inline-block" /> Kelurahan</span>
            <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-blue-400 inline-block" /> RW</span>
            <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-teal-400 inline-block" /> RT</span>
          </div>
        </div>

        {error && (
          <div className="px-6 py-3 bg-red-50 border-b border-red-100 text-sm text-red-600">{error}</div>
        )}

        {tree.length === 0 ? (
          <div className="px-6 py-12 text-center">
            <Building2 className="w-12 h-12 text-gray-300 mx-auto mb-4" />
            <p className="text-gray-500">Belum ada tenant</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-gray-50 border-b border-gray-200">
                <tr>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase">Nama</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase">Tipe</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase">Alamat</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase">Status</th>
                </tr>
              </thead>
              <tbody>
                {tree.map(node => (
                  <TenantRow key={node.id} node={node} depth={0} />
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
};

export default VendorDashboard;
