// ─── HELPERS ──────────────────────────────────────────────────────────────────
function schemaToRow(f) {
  return {
    id: f.id || '',
    label: f.label || '',
    type: f.type || 'text',
    required: !!f.required,
    optionsStr: Array.isArray(f.options) ? f.options.join(', ') : '',
  };
}
function rowToSchema(r) {
  const s = { id: r.id, label: r.label, type: r.type, required: r.required };
  if (r.type === 'select') s.options = r.optionsStr.split(',').map(v => v.trim()).filter(Boolean);
  return s;
}
function extractBody(html) {
  if (!html) return '';
  if (!html.includes('<body')) return html;
  const m = html.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
  return m ? m[1].trim() : html;
}
// Detect HTML that Quill will mangle (tables, inline border styles, colspan, etc.)
function hasComplexHtml(html) {
  if (!html) return false;
  return /<table[\s>]|<td[\s>]|<tr[\s>]|border[-\w]*\s*:|colspan|rowspan/i.test(html);
}

// ─── FIELD BUILDER ────────────────────────────────────────────────────────────
function FieldBuilder({ fieldsJson, onChange }) {
  const [rows, setRows] = useState(() => {
    try {
      const p = JSON.parse(fieldsJson || '[]');
      return Array.isArray(p) ? p.map(schemaToRow) : [];
    } catch { return []; }
  });
  const [parseError] = useState(() => {
    try { const p = JSON.parse(fieldsJson || '[]'); return !Array.isArray(p); }
    catch { return true; }
  });
  const [rawFallback, setRawFallback] = useState(fieldsJson || '[]');

  const syncUp = (newRows) => {
    setRows(newRows);
    onChange(JSON.stringify(newRows.map(rowToSchema)));
  };

  const updateRow = (i, key, val) => {
    const next = rows.map((r, idx) => idx === i ? { ...r, [key]: val } : r);
    syncUp(next);
  };

  const deleteRow = (i) => syncUp(rows.filter((_, idx) => idx !== i));

  const addRow = () => syncUp([...rows, { id: '', label: '', type: 'text', required: false, optionsStr: '' }]);

  if (parseError) {
    return (
      <div className="space-y-3">
        <div className="flex items-center gap-2 bg-red-50 border border-red-200 rounded-lg p-3 text-sm text-red-600">
          <AlertTriangle size={14} /> Format JSON tidak valid — mengedit dalam mode raw
        </div>
        <textarea value={rawFallback} onChange={e => { setRawFallback(e.target.value); onChange(e.target.value); }}
          rows={10} className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-xs font-mono focus:outline-none focus:ring-2 focus:ring-orange-400 resize-none" />
      </div>
    );
  }

  return (
    <div className="space-y-2">
      <div className="flex items-center justify-between mb-3">
        <div>
          <p className="text-sm font-semibold text-gray-700">Form Fields</p>
          <p className="text-xs text-gray-400">Field yang harus diisi pemohon saat mengajukan surat</p>
        </div>
        <span className="text-xs bg-orange-100 text-orange-700 px-2 py-1 rounded-full font-medium">{rows.length} field</span>
      </div>

      {rows.length === 0 && (
        <div className="text-center py-8 text-gray-400 border-2 border-dashed border-gray-200 rounded-xl">
          <p className="text-sm">Belum ada field</p>
          <p className="text-xs mt-1">Klik "+ Tambah Field" untuk menambahkan</p>
        </div>
      )}

      {rows.map((r, i) => (
        <div key={i} className="p-3 bg-white border border-gray-200 rounded-xl space-y-2 hover:border-orange-200 transition-colors">
          <div className="flex items-center gap-2 flex-wrap">
            <input value={r.id} onChange={e => updateRow(i, 'id', e.target.value)}
              placeholder="field_id"
              className="w-28 border border-gray-200 rounded-lg px-2 py-1.5 text-xs font-mono focus:outline-none focus:ring-1 focus:ring-orange-400" />
            <input value={r.label} onChange={e => updateRow(i, 'label', e.target.value)}
              placeholder="Label Field"
              className="flex-1 min-w-[120px] border border-gray-200 rounded-lg px-2 py-1.5 text-xs focus:outline-none focus:ring-1 focus:ring-orange-400" />
            <select value={r.type} onChange={e => updateRow(i, 'type', e.target.value)}
              className="w-24 border border-gray-200 rounded-lg px-2 py-1.5 text-xs focus:outline-none focus:ring-1 focus:ring-orange-400">
              <option value="text">Teks</option>
              <option value="textarea">Paragraf</option>
              <option value="date">Tanggal</option>
              <option value="number">Angka</option>
              <option value="select">Pilihan</option>
            </select>
            <button onClick={() => updateRow(i, 'required', !r.required)}
              className={`px-2 py-1.5 text-xs rounded-lg border whitespace-nowrap transition-colors ${r.required ? 'bg-green-50 border-green-300 text-green-700' : 'bg-gray-50 border-gray-200 text-gray-400 hover:border-gray-300'}`}>
              {r.required ? '✓ Wajib' : 'Opsional'}
            </button>
            <button onClick={() => deleteRow(i)} className="p-1.5 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors">
              <Trash2 size={13} />
            </button>
          </div>
          {r.type === 'select' && (
            <input value={r.optionsStr} onChange={e => updateRow(i, 'optionsStr', e.target.value)}
              placeholder="Opsi A, Opsi B, Opsi C  (pisahkan dengan koma)"
              className="w-full border border-orange-200 bg-orange-50/40 rounded-lg px-2 py-1.5 text-xs focus:outline-none focus:ring-1 focus:ring-orange-400" />
          )}
        </div>
      ))}

      <button onClick={addRow}
        className="w-full border-2 border-dashed border-gray-200 rounded-xl py-2.5 text-sm text-gray-500 hover:border-orange-300 hover:text-orange-600 hover:bg-orange-50/30 transition-colors flex items-center justify-center gap-1.5">
        <Plus size={14} /> Tambah Field
      </button>
    </div>
  );
}

// ─── TEMPLATE BUILDER MODAL ───────────────────────────────────────────────────
function TemplateBuilderModal({ open, onClose, onSave, editData }) {
  const [activeTab, setActiveTab] = useState('info');
  const [form, setForm] = useState({ kode: '', jenis_surat: '', deskripsi: '', fields_schema: '[]', is_active: true, approval_levels: ['RT'] });
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [showVarPanel, setShowVarPanel] = useState(true);
  const [sourceMode, setSourceMode] = useState(false);
  const joditRef = useRef(null);
  const textareaRef = useRef(null);
  const [rawHtml, setRawHtml] = useState('');   // authoritative HTML — Jodit, Preview, Save, Source

  // Inject Jodit A4 styles once
  useEffect(() => {
    if (!document.getElementById('jodit-a4-template-styles')) {
      const el = document.createElement('style');
      el.id = 'jodit-a4-template-styles';
      el.textContent = JODIT_STYLES;
      document.head.appendChild(el);
    }
  }, []);

  // Reset on open / editData change
  useEffect(() => {
    if (!open) return;
    setActiveTab('info');
    setError('');
    setShowVarPanel(true);
    if (editData) {
      const bodyHtml = extractBody(editData.html_body_template);
      let approvalLevels = ['RT'];
      try { approvalLevels = JSON.parse(editData.approval_levels || '["RT"]'); } catch (_) {}
      setForm({
        kode: editData.kode || '',
        jenis_surat: editData.jenis_surat || '',
        deskripsi: editData.deskripsi || '',
        fields_schema: editData.fields_schema || '[]',
        is_active: editData.is_active !== false,
        approval_levels: approvalLevels,
      });
      setRawHtml(bodyHtml);
      setSourceMode(false);
    } else {
      setForm({ kode: '', jenis_surat: '', deskripsi: '', fields_schema: '[]', is_active: true, approval_levels: ['RT'] });
      setRawHtml('');
      setSourceMode(false);
    }
  }, [open, editData]);

  // Raw preview — uses rawHtml (authoritative source)
  const rawPreviewHtml = useMemo(() => (
    `<!DOCTYPE html><html><head><meta charset="UTF-8"><style>
      body{font-family:'Times New Roman',Times,serif;font-size:12pt;line-height:1.6;
           max-width:210mm;margin:0 auto;padding:20mm 20mm 20mm 30mm;background:white;color:#000;}
    </style></head><body>${rawHtml || '<p style="color:#aaa;font-style:italic;">Belum ada konten template.</p>'}</body></html>`
  ), [rawHtml]);

  if (!open) return null;

  // Insert helpers — mode-aware (visual vs source HTML)
  const insertAtTextareaCursor = (text) => {
    const ta = textareaRef.current;
    if (!ta) { setRawHtml(v => v + text); return; }
    const start = ta.selectionStart;
    const end = ta.selectionEnd;
    const next = rawHtml.substring(0, start) + text + rawHtml.substring(end);
    setRawHtml(next);
    setTimeout(() => {
      ta.selectionStart = ta.selectionEnd = start + text.length;
      ta.focus();
    }, 0);
  };

  const insertAtCursor = (text) => {
    if (sourceMode) { insertAtTextareaCursor(text); return; }
    const jodit = joditRef.current;
    if (!jodit) return;
    jodit.selection.insertHTML(text);
    jodit.focus();
    setTimeout(() => { if (jodit.value) setRawHtml(jodit.value); }, 80);
  };

  const insertHtmlAtCursor = (html) => {
    if (sourceMode) { insertAtTextareaCursor(html); return; }
    const jodit = joditRef.current;
    if (!jodit) return;
    jodit.selection.insertHTML(html);
    jodit.focus();
    setTimeout(() => { if (jodit.value) setRawHtml(jodit.value); }, 80);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.kode.trim() || !form.jenis_surat.trim()) {
      setError('Kode dan Jenis Surat wajib diisi');
      setActiveTab('info');
      return;
    }
    setSaving(true);
    setError('');
    try {
      const htmlToSave = sourceMode ? rawHtml : (joditRef.current?.value || rawHtml);
      const payload = { ...form, html_body_template: htmlToSave, approval_levels: JSON.stringify(form.approval_levels) };
      const url    = editData ? `${API_BASE_URL}/api/surat-template/${editData.id}` : `${API_BASE_URL}/api/surat-template`;
      const method = editData ? 'PUT' : 'POST';
      const res  = await fetch(url, { method, headers: hdrs(), body: JSON.stringify(payload) });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal menyimpan');
      onSave();
      onClose();
    } catch (err) { setError(err.message); }
    setSaving(false);
  };

  return createPortal(
    <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[9999] flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-6xl flex flex-col" style={{ maxHeight: '95vh' }}>

        {/* Header */}
        <div className="flex-shrink-0 flex items-center justify-between px-6 py-4 border-b border-gray-200">
          <div className="flex items-center gap-3">
            <FileText size={18} className="text-orange-500" />
            <div>
              <h3 className="font-bold text-gray-800 text-lg leading-tight">
                {editData ? `Edit Template: ${editData.kode}` : 'Tambah Template Surat'}
              </h3>
              {editData && <p className="text-xs text-gray-400">{editData.jenis_surat}</p>}
            </div>
          </div>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600 p-1 rounded-lg hover:bg-gray-100 transition-colors">
            <X size={18} />
          </button>
        </div>

        {/* Tab Bar */}
        <div className="flex-shrink-0 flex border-b border-gray-200 px-6 overflow-x-auto">
          {TABS.map(t => (
            <button key={t.id} onClick={() => setActiveTab(t.id)}
              className={`px-4 py-3 text-sm font-medium whitespace-nowrap border-b-2 -mb-px transition-colors ${
                activeTab === t.id
                  ? 'border-[#ed6f5c] text-[#ed6f5c]'
                  : 'border-transparent text-gray-500 hover:text-gray-700'
              }`}>
              {t.label}
            </button>
          ))}
        </div>

        {/* Tab Content */}
        <div className="flex-1 overflow-y-auto min-h-0">

          {/* Tab 1 — Informasi */}
          {activeTab === 'info' && (
            <div className="p-6 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-sm font-medium text-gray-700 block mb-1.5">Kode Surat <span className="text-red-500">*</span></label>
                  <input value={form.kode} onChange={e => setForm(f => ({ ...f, kode: e.target.value }))}
                    disabled={!!editData} placeholder="SKD, SKKlh, SPKTP..."
                    className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-orange-400 disabled:bg-gray-50 disabled:text-gray-400 font-mono" />
                  <p className="text-xs text-gray-400 mt-1">Kode unik singkatan jenis surat, tidak bisa diubah setelah disimpan</p>
                </div>
                <div>
                  <label className="text-sm font-medium text-gray-700 block mb-1.5">Status</label>
                  <select value={form.is_active ? 'true' : 'false'} onChange={e => setForm(f => ({ ...f, is_active: e.target.value === 'true' }))}
                    className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-orange-400">
                    <option value="true">Aktif</option>
                    <option value="false">Nonaktif</option>
                  </select>
                </div>
              </div>
              <div>
                <label className="text-sm font-medium text-gray-700 block mb-1.5">Jenis Surat <span className="text-red-500">*</span></label>
                <input value={form.jenis_surat} onChange={e => setForm(f => ({ ...f, jenis_surat: e.target.value }))}
                  placeholder="Surat Keterangan Domisili"
                  className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-orange-400" />
              </div>
              <div>
                <label className="text-sm font-medium text-gray-700 block mb-1.5">Deskripsi</label>
                <input value={form.deskripsi || ''} onChange={e => setForm(f => ({ ...f, deskripsi: e.target.value }))}
                  placeholder="Penjelasan singkat tentang jenis surat ini"
                  className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-orange-400" />
              </div>
              {/* Approval Levels */}
              <div className="border border-gray-200 rounded-xl p-4 space-y-3">
                <div>
                  <p className="text-sm font-medium text-gray-700">Tingkat Penerbitan Surat</p>
                  <p className="text-xs text-gray-400 mt-0.5">Centang tingkat yang harus menyetujui sebelum surat diterbitkan</p>
                </div>
                <div className="space-y-2">
                  {[
                    { key: 'RT', label: 'RT (Rukun Tetangga)', disabled: true, desc: 'Wajib — surat selalu dimulai dari RT' },
                    { key: 'RW', label: 'RW (Rukun Warga)', disabled: false, desc: 'RT menyetujui dulu, kemudian diteruskan ke RW' },
                    { key: 'Kelurahan', label: 'Kelurahan', disabled: !form.approval_levels.includes('RW'), desc: 'Hanya tersedia jika RW dipilih' },
                  ].map(({ key, label, disabled, desc }) => (
                    <label key={key} className={`flex items-start gap-3 p-3 rounded-lg border transition-colors cursor-pointer ${
                      form.approval_levels.includes(key)
                        ? 'bg-orange-50 border-orange-200'
                        : disabled ? 'bg-gray-50 border-gray-100 cursor-not-allowed' : 'border-gray-200 hover:border-orange-200 hover:bg-orange-50/50'
                    }`}>
                      <input
                        type="checkbox"
                        checked={form.approval_levels.includes(key)}
                        disabled={disabled}
                        onChange={e => {
                          if (disabled) return;
                          setForm(f => {
                            let levels = [...f.approval_levels];
                            if (e.target.checked) {
                              if (!levels.includes(key)) levels.push(key);
                            } else {
                              levels = levels.filter(l => l !== key);
                              // Uncheck Kelurahan if RW unchecked
                              if (key === 'RW') levels = levels.filter(l => l !== 'Kelurahan');
                            }
                            // Ensure proper order
                            const order = ['RT', 'RW', 'Kelurahan'];
                            levels.sort((a, b) => order.indexOf(a) - order.indexOf(b));
                            return { ...f, approval_levels: levels };
                          });
                        }}
                        className="mt-0.5 accent-orange-500"
                      />
                      <div>
                        <p className={`text-sm font-medium ${disabled && !form.approval_levels.includes(key) ? 'text-gray-400' : 'text-gray-700'}`}>{label}</p>
                        <p className="text-xs text-gray-400">{desc}</p>
                      </div>
                    </label>
                  ))}
                </div>
                <div className="bg-gray-50 rounded-lg px-3 py-2 text-xs text-gray-500">
                  Alur: Warga
                  {form.approval_levels.map(l => ` → ${l}`).join('')}
                  {' → Surat Terbit'}
                </div>
              </div>

              <div className="bg-blue-50 border border-blue-100 rounded-xl p-4 text-sm text-blue-700">
                <p className="font-medium mb-1">Petunjuk Pengisian</p>
                <ul className="text-xs space-y-1 text-blue-600 list-disc list-inside">
                  <li>Lanjutkan ke tab <strong>Form Fields</strong> untuk menentukan data yang diisi pemohon</li>
                  <li>Lanjutkan ke tab <strong>Editor Template</strong> untuk mendesain isi surat secara visual</li>
                  <li>Gunakan tab <strong>Preview</strong> untuk melihat hasil akhir dengan data contoh</li>
                </ul>
              </div>
            </div>
          )}

          {/* Tab 2 — Form Fields */}
          {activeTab === 'fields' && (
            <div className="p-6">
              <FieldBuilder
                key={`${editData?.id ?? 'new'}-${open}`}
                fieldsJson={form.fields_schema}
                onChange={v => setForm(f => ({ ...f, fields_schema: v }))}
              />
            </div>
          )}

          {/* Tab 3 — Editor Template */}
          {activeTab === 'editor' && (
            <div className="flex flex-col" style={{ minHeight: '720px' }}>
              {/* Editor toolbar bar */}
              <div className="flex-shrink-0 flex items-center gap-3 px-4 py-2 bg-gray-50 border-b border-gray-200">
                {/* Mode toggle */}
                <div className="flex items-center bg-white border border-gray-200 rounded-lg p-0.5 gap-0.5">
                  <button onClick={() => setSourceMode(false)}
                    className={`px-3 py-1.5 text-xs rounded-md font-medium transition-colors ${!sourceMode ? 'bg-[#ed6f5c] text-white shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>
                    Visual Editor
                  </button>
                  <button onClick={() => {
                    if (joditRef.current) setRawHtml(joditRef.current.value);
                    setSourceMode(true);
                  }}
                    className={`px-3 py-1.5 text-xs rounded-md font-medium transition-colors ${sourceMode ? 'bg-[#ed6f5c] text-white shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>
                    Source HTML
                  </button>
                </div>
                <span className="text-xs text-gray-400">
                  {sourceMode ? 'Edit HTML langsung — format tabel & style dipertahankan penuh' : 'Visual Editor — klik variabel di panel kanan untuk menyisipkan'}
                </span>
                <div className="ml-auto">
                  <button onClick={() => setShowVarPanel(p => !p)}
                    className="flex items-center gap-1.5 px-3 py-1.5 text-xs rounded-lg border border-gray-200 bg-white hover:border-orange-300 hover:text-orange-600 transition-colors">
                    {showVarPanel ? <ChevronRight size={13} /> : <ChevronLeft size={13} />}
                    {showVarPanel ? 'Sembunyikan Panel' : 'Panel Variabel'}
                  </button>
                </div>
              </div>

              {/* Main editor + panel row */}
              <div className="flex flex-1 min-h-0">
                {/* Editor area */}
                {!sourceMode ? (
                  <div className="flex-1 min-w-0 overflow-auto surat-template-jodit">
                    <JoditEditor
                      ref={joditRef}
                      value={rawHtml}
                      config={JODIT_CONFIG}
                      onBlur={(newContent) => setRawHtml(newContent)}
                    />
                  </div>
                ) : (
                  /* Source HTML mode — split: textarea (left) + live preview (right) */
                  <div className="flex flex-1 min-w-0" style={{ minHeight: '700px' }}>
                    {/* HTML textarea */}
                    <div className="flex-1 flex flex-col min-w-0">
                      <div className="flex items-center px-3 py-1.5 bg-gray-800 border-b border-gray-700">
                        <span className="text-xs text-gray-300 font-mono">HTML Source</span>
                        <span className="ml-auto text-xs text-gray-500">Ctrl+A untuk pilih semua</span>
                      </div>
                      <textarea
                        ref={textareaRef}
                        value={rawHtml}
                        onChange={e => setRawHtml(e.target.value)}
                        className="flex-1 p-4 text-xs font-mono bg-gray-900 text-green-300 resize-none focus:outline-none"
                        style={{ minHeight: '700px' }}
                        spellCheck={false}
                        placeholder="<div>Tulis atau paste HTML surat di sini...</div>"
                      />
                    </div>
                    {/* Live preview */}
                    <div className="flex-1 flex flex-col min-w-0 border-l border-gray-700">
                      <div className="flex items-center px-3 py-1.5 bg-gray-100 border-b border-gray-200">
                        <span className="text-xs text-gray-500">Preview Langsung</span>
                        <span className="ml-auto text-xs text-gray-400">Placeholder tampil sebagai teks</span>
                      </div>
                      <iframe
                        srcDoc={rawPreviewHtml}
                        title="source-preview"
                        style={{ flex: 1, border: 'none', minHeight: '700px' }}
                      />
                    </div>
                  </div>
                )}

                {/* Variable Panel — shown in both modes */}
                {showVarPanel && (
                  <div className="w-56 flex-shrink-0 border-l border-gray-200 overflow-y-auto bg-gray-50/80">
                    {/* Quick Insert */}
                    <div className="p-3 border-b border-gray-200">
                      <p className="text-xs font-semibold text-gray-600 uppercase tracking-wide mb-2">Sisip Cepat</p>
                      <div className="space-y-1.5">
                        {QUICK_BLOCKS.map(b => (
                          <button key={b.id} onClick={() => insertHtmlAtCursor(b.html)}
                            className="w-full text-left px-3 py-2 text-xs rounded-lg bg-white border border-gray-200 hover:border-orange-300 hover:text-orange-700 hover:bg-orange-50 transition-colors font-medium">
                            {b.label}
                          </button>
                        ))}
                      </div>
                    </div>

                    {/* Variable categories */}
                    {VARIABLE_CATEGORIES.map(cat => (
                      <div key={cat.category} className="p-3 border-b border-gray-100">
                        <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">{cat.category}</p>
                        <div className="flex flex-wrap gap-1">
                          {cat.vars.map(v => (
                            <button key={v.id}
                              onClick={() => insertAtCursor(`{{${v.id}}}`)}
                              title={`Sisipkan {{${v.id}}}`}
                              className="text-xs px-1.5 py-0.5 bg-white border border-gray-200 rounded hover:bg-orange-50 hover:border-orange-300 hover:text-orange-700 transition-colors cursor-pointer">
                              {v.label}
                            </button>
                          ))}
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          )}

          {/* Tab 4 — Preview */}
          {activeTab === 'preview' && (
            <div className="p-4 space-y-3">
              <div className="flex items-start gap-2 bg-blue-50 border border-blue-100 rounded-xl p-3 text-sm text-blue-700">
                <Eye size={14} className="flex-shrink-0 mt-0.5" />
                <div>
                  <p className="font-medium">Preview Template</p>
                  <p className="text-xs mt-0.5 text-blue-600">Tampilan surat dengan variabel placeholder. Variabel akan diisi otomatis saat surat diterbitkan.</p>
                </div>
              </div>
              <div className="border border-gray-200 rounded-xl overflow-hidden bg-gray-50">
                <iframe
                  srcDoc={rawPreviewHtml}
                  title="preview-surat"
                  style={{ width: '100%', minHeight: '750px', border: 'none', display: 'block' }}
                />
              </div>
            </div>
          )}

          {/* Tab 5 — QR & TTD */}
          {activeTab === 'qr' && (
            <div className="p-6 space-y-5">
              {/* QR Verification */}
              <div className="bg-white border border-gray-200 rounded-xl p-4">
                <div className="flex items-start justify-between gap-4">
                  <div>
                    <h4 className="font-semibold text-gray-800 text-sm mb-1">QR Code Verifikasi</h4>
                    <p className="text-xs text-gray-500 mb-2">
                      Sisipkan placeholder <code className="bg-gray-100 px-1 rounded">{'{{qr_verification}}'}</code> ke dalam template.
                      Saat surat diterbitkan, sistem akan otomatis mengisi dengan kode verifikasi unik surat tersebut.
                    </p>
                    <div className="bg-gray-50 border border-gray-200 rounded-lg p-3 text-xs font-mono text-gray-700">
                      {'{{qr_verification}}'}
                    </div>
                  </div>
                  <button onClick={() => { insertHtmlAtCursor(QUICK_BLOCKS.find(b => b.id === 'qr').html); setActiveTab('editor'); }}
                    className="flex-shrink-0 px-4 py-2 bg-[#ed6f5c] text-white rounded-xl text-xs font-semibold hover:bg-[#e05a47] transition-colors whitespace-nowrap">
                    Sisipkan ke Editor
                  </button>
                </div>
              </div>

              {/* Signature blocks */}
              {[
                { title: 'Blok Tanda Tangan RT', block: QUICK_BLOCKS.find(b => b.id === 'ttd_rt') },
                { title: 'Blok Tanda Tangan RW', block: QUICK_BLOCKS.find(b => b.id === 'ttd_rw') },
                { title: 'Blok Tanda Tangan Lurah', block: QUICK_BLOCKS.find(b => b.id === 'ttd_lurah') },
              ].map(({ title, block }) => (
                <div key={block.id} className="bg-white border border-gray-200 rounded-xl p-4">
                  <div className="flex items-start justify-between gap-4">
                    <div className="flex-1 min-w-0">
                      <h4 className="font-semibold text-gray-800 text-sm mb-2">{title}</h4>
                      <div className="bg-gray-50 border border-gray-200 rounded-lg p-3 overflow-auto max-h-36"
                        dangerouslySetInnerHTML={{ __html: block.html }} />
                    </div>
                    <button onClick={() => { insertHtmlAtCursor(block.html); setActiveTab('editor'); }}
                      className="flex-shrink-0 px-4 py-2 bg-[#ed6f5c] text-white rounded-xl text-xs font-semibold hover:bg-[#e05a47] transition-colors whitespace-nowrap">
                      Sisipkan ke Editor
                    </button>
                  </div>
                </div>
              ))}

              {/* Variable reference table */}
              <div className="bg-white border border-gray-200 rounded-xl overflow-hidden">
                <div className="px-4 py-3 bg-gray-50 border-b border-gray-200">
                  <h4 className="font-semibold text-gray-700 text-sm">Referensi Variabel Otomatis</h4>
                  <p className="text-xs text-gray-400 mt-0.5">Diisi otomatis dari Profil Surat Tenant (tidak perlu diisi pemohon)</p>
                </div>
                <table className="w-full text-xs">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-4 py-2 text-left text-gray-500 font-semibold">Variabel</th>
                      <th className="px-4 py-2 text-left text-gray-500 font-semibold">Sumber Data</th>
                      <th className="px-4 py-2 text-left text-gray-500 font-semibold">Contoh</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100">
                    {[
                      ['{{nama_pejabat}}', 'Profil Surat → nama_pejabat', 'Budi Santoso'],
                      ['{{jabatan}}', 'Profil Surat → jabatan', 'Ketua RT 001 RW. 009'],
                      ['{{no_rt}}', 'Profil Surat → no_rt', '001'],
                      ['{{no_rw}}', 'Profil Surat → no_rw', '009'],
                      ['{{nama_kelurahan}}', 'Hierarki Tenant → kelurahan', 'Cempaka Baru'],
                      ['{{kecamatan}}', 'Hierarki Tenant → kecamatan', 'Kemayoran'],
                      ['{{kabupaten}}', 'Hierarki Tenant → kabupaten', 'Jakarta Pusat'],
                      ['{{kota}}', 'Profil Surat → kota', 'Jakarta'],
                      ['{{nomor_surat}}', 'Generate otomatis saat penerbitan', '001/SKD/RT/V/2026 (atau /RW/ atau /KEL/)'],
                      ['{{tanggal_terbit}}', 'Generate otomatis saat penerbitan', '26 Mei 2026'],
                      ['{{ttd_image}}', 'Gambar TTD penerbit (RT / RW / Kelurahan)', '— inline base64 otomatis —'],
                    ].map(([v, src, ex]) => (
                      <tr key={v} className="hover:bg-gray-50">
                        <td className="px-4 py-2 font-mono text-orange-700">{v}</td>
                        <td className="px-4 py-2 text-gray-500">{src}</td>
                        <td className="px-4 py-2 text-gray-500">{ex}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

        </div>{/* end Tab Content */}

        {/* Error Banner */}
        {error && (
          <div className="flex-shrink-0 px-6 pb-1">
            <div className="flex items-center gap-2 bg-red-50 border border-red-200 rounded-xl p-3 text-sm text-red-600">
              <AlertTriangle size={14} />{error}
            </div>
          </div>
        )}

        {/* Footer */}
        <div className="flex-shrink-0 border-t border-gray-200 px-6 py-4 flex gap-3">
          <button type="button" onClick={onClose}
            className="flex-1 border border-gray-200 rounded-xl py-2.5 text-sm font-medium hover:bg-gray-50 transition-colors">
            Batal
          </button>
          <button type="button" onClick={handleSubmit} disabled={saving}
            className="flex-1 bg-[#ed6f5c] text-white rounded-xl py-2.5 text-sm font-semibold disabled:opacity-50 hover:bg-[#e05a47] transition-colors">
            {saving ? 'Menyimpan...' : editData ? 'Simpan Perubahan' : 'Tambah Template'}
          </button>
        </div>

      </div>
    </div>,
    document.body
  );
}

// ─── PREVIEW MODAL ────────────────────────────────────────────────────────────
function PreviewModal({ open, onClose, template }) {
  if (!open || !template) return null;
  return createPortal(
    <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[9999] flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-3xl max-h-[90vh] flex flex-col">
        <div className="p-5 border-b border-gray-200 flex items-center justify-between flex-shrink-0">
          <h3 className="font-bold text-gray-800 text-lg">Preview: {template.jenis_surat}</h3>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><X size={18}/></button>
        </div>
        <div className="flex-1 overflow-auto p-4">
          <iframe
            srcDoc={template.html_body_template}
            title="preview"
            className="w-full border border-gray-200 rounded-lg"
            style={{ minHeight: '600px' }}
          />
        </div>
      </div>
    </div>,
    document.body
  );
}

// ─── MAIN PAGE ────────────────────────────────────────────────────────────────
export default function SuratTemplate() {
  const [templates, setTemplates] = useState([]);
  const [loading, setLoading]     = useState(true);
  const [modal, setModal]         = useState(false);
  const [editData, setEdit]       = useState(null);
  const [preview, setPreview]     = useState(null);
  const [seeding, setSeeding]     = useState(false);
  const [seedMsg, setSeedMsg]     = useState('');

  const fetchTemplates = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/surat-template`, { headers: hdrs() });
      if (res.ok) setTemplates(await res.json());
    } catch (_) {}
    setLoading(false);
  }, []);

  useEffect(() => { fetchTemplates(); }, [fetchTemplates]);

  const handleDelete = async (id, nama) => {
    if (!await vendorConfirm(`Hapus template "${nama}"? Tindakan ini tidak dapat dibatalkan.`, 'Hapus Template')) return;
    await fetch(`${API_BASE_URL}/api/surat-template/${id}`, { method: 'DELETE', headers: hdrs() });
    fetchTemplates();
  };

  const handleSeed = async () => {
    if (!await vendorConfirm('Tambahkan 17 template surat default? Template yang sudah ada akan dilewati.', 'Seed Template')) return;
    setSeeding(true); setSeedMsg('');
    try {
      const res = await fetch(`${API_BASE_URL}/api/surat-template/seed/default`, { method: 'POST', headers: hdrs() });
      const data = await res.json();
      setSeedMsg(data.message || 'Selesai');
      fetchTemplates();
    } catch (_) { setSeedMsg('Gagal melakukan seed'); }
    setSeeding(false);
  };

  return (
    <div className="space-y-5">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Template Surat Resmi</h1>
          <p className="text-sm text-gray-500">Kelola master template surat pemerintahan</p>
        </div>
        <div className="flex gap-2">
          <button onClick={fetchTemplates}
            className="px-3 py-2 border border-gray-200 rounded-xl text-sm hover:bg-gray-50">
            <RefreshCw size={14} className={loading ? 'animate-spin' : ''} />
          </button>
          <button onClick={handleSeed} disabled={seeding}
            className="flex items-center gap-2 px-4 py-2 border border-orange-300 text-orange-600 rounded-xl text-sm font-medium hover:bg-orange-50 disabled:opacity-50">
            <CheckCircle size={15}/> {seeding ? 'Memproses...' : 'Seed 17 Default'}
          </button>
          <button onClick={() => { setEdit(null); setModal(true); }}
            className="flex items-center gap-2 px-4 py-2 bg-[#ed6f5c] text-white rounded-xl text-sm font-semibold">
            <Plus size={15}/> Tambah Template
          </button>
        </div>
      </div>

      {seedMsg && (
        <div className="bg-green-50 border border-green-200 rounded-lg px-4 py-3 text-sm text-green-700 flex items-center gap-2">
          <CheckCircle size={14}/>{seedMsg}
        </div>
      )}

      <div className="bg-white rounded-2xl border border-gray-100 overflow-hidden">
        {loading ? (
          <div className="flex justify-center py-12">
            <div className="w-8 h-8 border-4 border-[#ed6f5c] border-t-transparent rounded-full animate-spin"/>
          </div>
        ) : templates.length === 0 ? (
          <div className="py-12 text-center">
            <FileText size={36} className="mx-auto text-gray-300 mb-3"/>
            <p className="text-gray-500 font-medium">Belum ada template surat</p>
            <p className="text-gray-400 text-sm mt-1 mb-4">Klik "Seed 17 Default" untuk menambahkan template standar</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-gray-50">
                <tr>
                  {['Kode', 'Jenis Surat', 'Deskripsi', 'Status', 'Aksi'].map(h => (
                    <th key={h} className="px-5 py-3 text-left text-xs font-semibold text-gray-500 uppercase">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {templates.map(t => (
                  <tr key={t.id} className="hover:bg-gray-50">
                    <td className="px-5 py-3">
                      <span className="text-xs font-bold px-2 py-1 rounded-lg bg-orange-100 text-orange-700">{t.kode}</span>
                    </td>
                    <td className="px-5 py-3 font-medium text-gray-800">{t.jenis_surat}</td>
                    <td className="px-5 py-3 text-gray-500 max-w-xs truncate">{t.deskripsi || '—'}</td>
                    <td className="px-5 py-3">
                      <span className={`text-xs px-2 py-1 rounded-full font-medium ${t.is_active ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-500'}`}>
                        {t.is_active ? 'Aktif' : 'Nonaktif'}
                      </span>
                    </td>
                    <td className="px-5 py-3">
                      <div className="flex items-center gap-2">
                        <button onClick={() => setPreview(t)}
                          className="text-xs px-2.5 py-1 border border-gray-200 rounded-lg hover:bg-blue-50 hover:border-blue-300 hover:text-blue-600 text-gray-500 flex items-center gap-1">
                          <Eye size={11}/> Preview
                        </button>
                        <button onClick={() => { setEdit(t); setModal(true); }}
                          className="text-xs px-2.5 py-1 border border-gray-200 rounded-lg hover:bg-[#fdf1ef] hover:border-[#ed6f5c] hover:text-[#ed6f5c] text-gray-500 flex items-center gap-1">
                          <Edit2 size={11}/> Edit
                        </button>
                        <button onClick={() => handleDelete(t.id, t.jenis_surat)}
                          className="p-1.5 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg">
                          <Trash2 size={13}/>
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            <div className="px-5 py-3 border-t border-gray-100 text-xs text-gray-400">
              {templates.length} template terdaftar
            </div>
          </div>
        )}
      </div>

      <TemplateBuilderModal
        open={modal}
        onClose={() => { setModal(false); setEdit(null); }}
        onSave={fetchTemplates}
        editData={editData}
      />
      <PreviewModal open={!!preview} onClose={() => setPreview(null)} template={preview} />
    </div>
  );
}
