import React, { createContext, useContext, useState, useEffect } from 'react';
import { API_BASE_URL } from '../config/api';

const DEFAULTS = {
  appName:        'Ruang Warga',
  appVersion:     '2.4',
  appTitle:       'Ruang Warga App',
  appDescription: 'Solusi Terintegrasi untuk RT, RW, dan Kelurahan',
  logoUrl:        null,
  kopLogoUrl:     null,
};

const AppSettingsContext = createContext(DEFAULTS);

const resolveUrl = (url) => {
  if (!url) return null;
  if (url.startsWith('http')) return url;
  return `${API_BASE_URL}${url}`;
};

export function AppSettingsProvider({ children }) {
  const [settings, setSettings] = useState(DEFAULTS);

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/app/settings`)
      .then(r => r.ok ? r.json() : null)
      .then(data => {
        if (!data) return;
        const next = {
          appName:        data.app_name        || DEFAULTS.appName,
          appVersion:     data.app_version     || DEFAULTS.appVersion,
          appTitle:       data.app_title       || DEFAULTS.appTitle,
          appDescription: data.app_description || DEFAULTS.appDescription,
          logoUrl:        resolveUrl(data.logo_url),
          kopLogoUrl:     resolveUrl(data.kop_logo_url),
        };
        setSettings(next);
        document.title = next.appTitle;
        if (next.logoUrl) {
          let link = document.querySelector("link[rel~='icon']");
          if (!link) {
            link = document.createElement('link');
            link.rel = 'icon';
            document.head.appendChild(link);
          }
          link.href = next.logoUrl;
        }
      })
      .catch(() => {});
  }, []);

  return (
    <AppSettingsContext.Provider value={settings}>
      {children}
    </AppSettingsContext.Provider>
  );
}

export const useAppSettings = () => useContext(AppSettingsContext);
