import React, { useEffect, useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from '@/components/ui/select';
import { useAuth } from '@/contexts/AuthContext';
import { API_ENDPOINTS } from '@/config/api';
import { toast } from 'sonner';

export default function BudgetForm({ open, onClose, editData, onSuccess, month, year, isTemplate = false }) {
    const { token } = useAuth();
    const [categories, setCategories] = useState([]);
    const [formData, setFormData] = useState({
        finance_category_id: '',
        budget_amount: ''
    });
    const [loading, setLoading] = useState(false);

    // Load categories on mount
    useEffect(() => {
        if (open) {
            loadCategories();
            if (editData) {
                setFormData({
                    finance_category_id: editData.category_id || editData.finance_category_id,
                    budget_amount: editData.budget_amount || editData.default_amount || ''
                });
            } else {
                setFormData({ finance_category_id: '', budget_amount: '' });
            }
        }
    }, [open, token, editData]);

    const loadCategories = async () => {
        try {
            const res = await fetch(API_ENDPOINTS.FINANCE_CATEGORY, {
                headers: { Authorization: `Bearer ${token}` }
            });
            if (res.ok) {
                const data = await res.json();
                setCategories(data.filter(c => {
                    const tipe = (c.tipe || '').toLowerCase();
                    return tipe === 'pengeluaran' || tipe === 'fund';
                }));
            }
        } catch (err) {
            console.error(err);
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);

        try {
            let url = isTemplate ? API_ENDPOINTS.BUDGET_TEMPLATE : API_ENDPOINTS.BUDGET;
            let payload = {
                finance_category_id: formData.finance_category_id
            };

            if (isTemplate) {
                payload.default_amount = parseFloat(formData.budget_amount);
            } else {
                payload.budget_amount = parseFloat(formData.budget_amount);
                payload.bulan = month;
                payload.tahun = year;
            }

            const res = await fetch(url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    Authorization: `Bearer ${token}`
                },
                body: JSON.stringify(payload)
            });

            if (!res.ok) {
                const errData = await res.json().catch(() => ({}));
                throw new Error(errData.detail || 'Gagal menyimpan budget');
            }

            toast.success(isTemplate ? `Default Template tersimpan` : `Budget berhasil disimpan`);
            onSuccess();
            onClose();

        } catch (error) {
            toast.error(error.message);
        } finally {
            setLoading(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={onClose}>
            <DialogContent className="sm:max-w-md">
                <DialogHeader>
                    <DialogTitle>
                        {isTemplate
                            ? (editData ? 'Edit Budget Template' : 'Set Default Budget')
                            : (editData ? 'Edit Budget Bulanan' : 'Tambah Budget Baru')}
                    </DialogTitle>
                </DialogHeader>

                <form onSubmit={handleSubmit} className="space-y-4 py-4">
                    <div className="space-y-2">
                        <Label>Pos Keuangan (Pengeluaran / Dana)</Label>
                        <Select
                            value={formData.finance_category_id}
                            onValueChange={(val) => setFormData({ ...formData, finance_category_id: val })}
                            disabled={!!editData}
                        >
                            <SelectTrigger>
                                <SelectValue placeholder="Pilih Pos..." />
                            </SelectTrigger>
                            <SelectContent>
                                {categories.map(cat => (
                                    <SelectItem key={cat.id} value={cat.id}>{cat.nama}</SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </div>

                    <div className="space-y-2">
                        <Label>Nominal Budget (Pagu)</Label>
                        <div className="relative">
                            <span className="absolute left-3 top-2.5 text-gray-500 text-sm">Rp</span>
                            <Input
                                type="text"
                                placeholder="1.000.000"
                                className="pl-9"
                                value={formData.budget_amount ? parseFloat(formData.budget_amount.toString().replace(/\./g, '')).toLocaleString('id-ID') : ''}
                                onChange={(e) => {
                                    const value = e.target.value.replace(/\D/g, '');
                                    setFormData({ ...formData, budget_amount: value });
                                }}
                                required
                            />
                        </div>
                        {!isTemplate && (
                            <p className="text-xs text-gray-500">
                                Berlaku untuk periode: <strong>{month}/{year}</strong>
                            </p>
                        )}
                        {isTemplate && (
                            <p className="text-xs text-gray-500">
                                Anggaran ini akan menjadi <strong>default</strong> untuk bulan-bulan berikutnya secara otomatis.
                            </p>
                        )}
                    </div>

                    <DialogFooter>
                        <Button type="button" variant="outline" onClick={onClose}>Batal</Button>
                        <Button type="submit" disabled={loading} className="bg-[#ed6f5c]">
                            {loading ? 'Menyimpan...' : 'Simpan'}
                        </Button>
                    </DialogFooter>
                </form>
            </DialogContent>
        </Dialog>
    );
}
