import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Search, Plus, Edit, Trash2, Eye, FileDown } from 'lucide-react';
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { useAuthHeader, useAuth } from '@/contexts/AuthContext';
import { useAppSettings } from '@/contexts/AppSettingsContext';
import { hasPermission } from '@/lib/permissionsMatrix';
import axios from 'axios';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';
import { toast } from "@/components/ui/sonner";
import ReactQuill from 'react-quill';
import 'react-quill/dist/quill.snow.css';

// Custom styles for Quill editor
const quillStyles = `
  .ql-container {
    font-size: 14px;
    font-family: 'Arial', sans-serif;
  }
  .ql-editor {
    min-height: 450px;
    line-height: 1.6;
    color: #000;
  }
  .dark .ql-editor {
    color: #e5e7eb;
    background-color: #1f2937;
  }
  .ql-toolbar {
    border-top-left-radius: 8px;
    border-top-right-radius: 8px;
    background: #f8f9fa;
  }
  .dark .ql-toolbar {
    background: #374151;
    border-color: #4b5563;
  }
  .ql-container {
    border-bottom-left-radius: 8px;
    border-bottom-right-radius: 8px;
  }
  .dark .ql-container {
    border-color: #4b5563;
  }
  .ql-editor ul, .ql-editor ol {
    padding-left: 1.5em;
  }
  .ql-editor li {
    margin-bottom: 0.5em;
  }
  .dark .ql-toolbar.ql-snow .ql-stroke {
    stroke: #9ca3af;
  }
  .dark .ql-toolbar.ql-snow .ql-fill,
  .dark .ql-toolbar.ql-snow .ql-stroke.ql-fill {
    fill: #9ca3af;
  }
  .dark .ql-toolbar.ql-snow button:hover .ql-stroke,
  .dark .ql-toolbar.ql-snow button.ql-active .ql-stroke {
    stroke: #d1d5db;
  }
  .dark .ql-toolbar.ql-snow button:hover .ql-fill,
  .dark .ql-toolbar.ql-snow button.ql-active .ql-fill {
    fill: #d1d5db;
  }
  .dark .ql-snow .ql-picker-label {
    color: #9ca3af;
  }
`;

const SuratPage = () => {
  const authHeader = useAuthHeader();
  const { user } = useAuth();
  const { kopLogoUrl } = useAppSettings();
  const [suratList, setSuratList] = useState([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [loading, setLoading] = useState(false);
  const [showFormDialog, setShowFormDialog] = useState(false);
  const [showPreviewDialog, setShowPreviewDialog] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [currentSurat, setCurrentSurat] = useState(null);
  const [deleteConfirm, setDeleteConfirm] = useState(null);
  
  // Form fields
  const [judulSurat, setJudulSurat] = useState('');
  const [isiSuratHtml, setIsiSuratHtml] = useState('');
  
  const quillRef = useRef(null);
  const [profil, setProfil] = useState({});

  // Inject custom styles once
  useEffect(() => {
    if (!document.getElementById('quill-custom-styles')) {
      const styleEl = document.createElement('style');
      styleEl.id = 'quill-custom-styles';
      styleEl.textContent = quillStyles;
      document.head.appendChild(styleEl);
    }
  }, []);

  // Quill modules configuration - memoized to prevent re-renders
  const quillModules = useMemo(() => ({
    toolbar: {
      container: [
        [{ 'header': [1, 2, 3, 4, 5, 6, false] }],
        [{ 'font': [] }],
        [{ 'size': ['small', false, 'large', 'huge'] }],
        ['bold', 'italic', 'underline', 'strike'],
        [{ 'color': [] }, { 'background': [] }],
        [{ 'list': 'ordered' }, { 'list': 'bullet' }],
        [{ 'indent': '-1' }, { 'indent': '+1' }],
        [{ 'align': [] }],
        ['link', 'image'],
        ['clean']
      ],
      handlers: {
        image: function() {
          const input = document.createElement('input');
          input.setAttribute('type', 'file');
          input.setAttribute('accept', 'image/*');
          input.click();
          
          input.onchange = () => {
            const file = input.files[0];
            if (file) {
              const reader = new FileReader();
              reader.onload = (e) => {
                const quill = quillRef.current?.getEditor();
                if (quill) {
                  const range = quill.getSelection(true);
                  quill.insertEmbed(range.index, 'image', e.target.result);
                  quill.setSelection(range.index + 1);
                }
              };
              reader.readAsDataURL(file);
            }
          };
        }
      }
    },
    clipboard: {
      matchVisual: false
    }
  }), []);

  // Quill formats
  const quillFormats = [
    'header', 'font', 'size',
    'bold', 'italic', 'underline', 'strike',
    'color', 'background',
    'list', 'bullet', 'indent',
    'align',
    'link', 'image'
  ];

  useEffect(() => {
    fetchSuratList();
  }, [searchQuery]);

  useEffect(() => {
    const fetchProfil = async () => {
      try {
        const res = await axios.get('/api/surat-resmi/profil', { headers: authHeader });
        setProfil(res.data || {});
      } catch {}
    };
    fetchProfil();
  }, []);

  const fetchSuratList = async () => {
    try {
      setLoading(true);
      const response = await axios.get(
        `/api/surat`,
        {
          params: { search: searchQuery },
          headers: authHeader
        }
      );
      setSuratList(response.data);
    } catch (error) {
      console.error('Error fetching surat list:', error);
      const message = error?.response?.data?.detail || "Gagal memuat data surat";
      toast.error(message);
    } finally {
      setLoading(false);
    }
  };

  const handleOpenCreateDialog = () => {
    setEditMode(false);
    setCurrentSurat(null);
    setJudulSurat('');
    setIsiSuratHtml('');
    setShowFormDialog(true);
  };

  const handleOpenEditDialog = (surat) => {
    setEditMode(true);
    setCurrentSurat(surat);
    setJudulSurat(surat.judul_surat);
    setIsiSuratHtml(surat.isi_surat_html || '');
    setShowFormDialog(true);
  };

  const handleCloseFormDialog = () => {
    setShowFormDialog(false);
    setEditMode(false);
    setCurrentSurat(null);
    setJudulSurat('');
    setIsiSuratHtml('');
  };

  const handleEditorChange = (content) => {
    setIsiSuratHtml(content);
  };

  const handleSubmit = async () => {
    if (!judulSurat.trim()) {
      toast.error("Judul surat harus diisi");
      return;
    }

    // Check if content is empty (Quill returns <p><br></p> for empty)
    const strippedContent = isiSuratHtml.replace(/<(.|\n)*?>/g, '').trim();
    if (!strippedContent) {
      toast.error("Isi surat harus diisi");
      return;
    }

    try {
      setLoading(true);
      const payload = {
        judul_surat: judulSurat,
        isi_surat_html: isiSuratHtml
      };

      if (editMode && currentSurat) {
        await axios.put(
          `/api/surat/${currentSurat.id}`,
          payload,
          { headers: authHeader }
        );
        toast.success("Surat berhasil diperbarui!");
      } else {
        await axios.post(
          `/api/surat`,
          payload,
          { headers: authHeader }
        );
        toast.success("Surat berhasil dibuat!");
      }

      handleCloseFormDialog();
      fetchSuratList();
    } catch (error) {
      console.error('Error saving surat:', error);
      const message = error?.response?.data?.detail || "Gagal menyimpan surat";
      toast.error(message);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id) => {
    try {
      setLoading(true);
      await axios.delete(
        `/api/surat/${id}`,
        { headers: authHeader }
      );
      toast.success("Surat berhasil dihapus!");
      fetchSuratList();
    } catch (error) {
      console.error('Error deleting surat:', error);
      const message = error?.response?.data?.detail || "Gagal menghapus surat";
      toast.error(message);
    } finally {
      setLoading(false);
    }
  };

  const confirmDelete = async () => {
    if (!deleteConfirm?.id) return;
    await handleDelete(deleteConfirm.id);
    setDeleteConfirm(null);
  };

  const handlePreview = (surat) => {
    setCurrentSurat(surat);
    setShowPreviewDialog(true);
  };

  const handleExportPDF = async (surat) => {
    try {
      const pdf = new jsPDF('p', 'mm', 'a4');
      const pageWidth = pdf.internal.pageSize.getWidth();
      const pageHeight = pdf.internal.pageSize.getHeight();
      const margin = 20;
      const contentWidth = pageWidth - 2 * margin;

      const namaKelurahan = (profil.nama_kelurahan || '').toUpperCase();
      const noRt  = profil.no_rt  || '-';
      const noRw  = profil.no_rw  || '-';
      const alamatBawah = [profil.nama_kelurahan, profil.kecamatan, profil.kabupaten]
        .filter(Boolean).join(', ');

      const drawHeader = async () => {
        try {
          const img = new Image();
          img.crossOrigin = 'anonymous';
          img.src = kopLogoUrl || '/logo-garuda.png';
          await new Promise((resolve, reject) => {
            img.onload = resolve;
            img.onerror = reject;
          });
          pdf.addImage(img, 'PNG', margin, 8, 22, 22);
        } catch {}

        pdf.setTextColor(0, 0, 0);
        pdf.setFontSize(14);
        pdf.setFont('helvetica', 'bold');
        pdf.text(`PEMERINTAH KELURAHAN ${namaKelurahan}`, pageWidth / 2, 15, { align: 'center' });

        pdf.setFontSize(13);
        pdf.text(`KETUA RT. ${noRt} RW. ${noRw}`, pageWidth / 2, 22, { align: 'center' });

        pdf.setFontSize(9);
        pdf.setFont('helvetica', 'normal');
        pdf.text(alamatBawah, pageWidth / 2, 29, { align: 'center' });

        pdf.setDrawColor(0, 0, 0);
        pdf.setLineWidth(0.5);
        pdf.line(margin, 34, pageWidth - margin, 34);
      };

      const drawFooter = () => {
        const barY = pageHeight - 18;
        pdf.setDrawColor(0, 0, 0);
        pdf.setLineWidth(0.4);
        pdf.line(margin, barY, pageWidth - margin, barY);

        pdf.setTextColor(0, 0, 0);
        pdf.setFont('helvetica', 'normal');
        pdf.setFontSize(8);
        pdf.text(alamatBawah, pageWidth / 2, barY + 6, { align: 'center' });
      };

      const topOffset = 40;
      const bottomOffset = 24;

      await drawHeader();

      // Create temp container with proper list styling for PDF
      const tempDiv = document.createElement('div');
      tempDiv.innerHTML = surat.isi_surat_html;
      tempDiv.style.width = `${contentWidth * 3.7795}px`;
      tempDiv.style.padding = '20px';
      tempDiv.style.fontFamily = 'Arial, sans-serif';
      tempDiv.style.fontSize = '12px';
      tempDiv.style.lineHeight = '1.6';
      tempDiv.style.backgroundColor = 'white';
      tempDiv.style.color = '#000'; // Ensure text is black for PDF
      
      // Important: Add explicit list styling for PDF rendering with proper alignment
      const styleTag = document.createElement('style');
      styleTag.textContent = `
        ol, ul {
          margin: 0.5em 0 0.5em 0 !important;
          padding: 0 0 0 2.5em !important;
        }
        ol {
          list-style-type: decimal !important;
        }
        ul {
          list-style-type: disc !important;
        }
        ol li, ul li {
          display: list-item !important;
          margin-bottom: 0.5em !important;
          padding-left: 0 !important;
          text-align: left !important;
          list-style-position: outside !important;
          color: #000 !important;
        }
        ol li {
          list-style-type: decimal !important;
        }
        ul li {
          list-style-type: disc !important;
        }
        p, div, span {
          color: #000 !important;
        }
      `;
      tempDiv.appendChild(styleTag);
      
      // Process Quill's list format - convert data-list attributes to proper lists
      const processQuillLists = (container) => {
        // Find all li elements with data-list attribute
        const listItems = container.querySelectorAll('li[data-list]');
        listItems.forEach(li => {
          const listType = li.getAttribute('data-list');
          if (listType === 'ordered') {
            li.style.listStyleType = 'decimal';
            li.style.display = 'list-item';
            li.style.listStylePosition = 'outside';
            // Ensure parent is ol
            const parent = li.parentElement;
            if (parent && parent.tagName.toLowerCase() !== 'ol') {
              const ol = document.createElement('ol');
              ol.style.listStyleType = 'decimal';
              ol.style.padding = '0 0 0 2.5em';
              ol.style.margin = '0.5em 0';
              parent.insertBefore(ol, li);
              ol.appendChild(li);
            }
          } else if (listType === 'bullet') {
            li.style.listStyleType = 'disc';
            li.style.display = 'list-item';
            li.style.listStylePosition = 'outside';
          }
        });
        
        // Force all ol elements to show numbers with proper alignment
        const olElements = container.querySelectorAll('ol');
        olElements.forEach(ol => {
          ol.style.listStyleType = 'decimal';
          ol.style.padding = '0 0 0 2.5em';
          ol.style.margin = '0.5em 0';
          ol.querySelectorAll('li').forEach(li => {
            li.style.display = 'list-item';
            li.style.listStyleType = 'decimal';
            li.style.listStylePosition = 'outside';
            li.style.paddingLeft = '0';
            li.style.marginBottom = '0.5em';
          });
        });
        
        // Force all ul elements to show bullets with proper alignment
        const ulElements = container.querySelectorAll('ul');
        ulElements.forEach(ul => {
          ul.style.listStyleType = 'disc';
          ul.style.padding = '0 0 0 2.5em';
          ul.style.margin = '0.5em 0';
          ul.querySelectorAll('li').forEach(li => {
            li.style.display = 'list-item';
            li.style.listStyleType = 'disc';
            li.style.listStylePosition = 'outside';
            li.style.paddingLeft = '0';
            li.style.marginBottom = '0.5em';
          });
        });
      };
      
      processQuillLists(tempDiv);
      
      document.body.appendChild(tempDiv);

      // Optimize: Use scale 1.5 instead of 2 to reduce file size while maintaining quality
      const canvas = await html2canvas(tempDiv, {
        scale: 1.5, // Reduced from 2 to reduce file size
        useCORS: true,
        logging: false,
        backgroundColor: '#ffffff' // Ensure white background
      });

      document.body.removeChild(tempDiv);

      // Compress canvas to JPEG instead of PNG to reduce file size significantly
      const imgData = canvas.toDataURL('image/jpeg', 0.85); // 85% quality
      const imgWidthMm = contentWidth;
      const pxPerMm = canvas.width / imgWidthMm;
      const usableHeightMm = pageHeight - topOffset - bottomOffset;
      const sliceHeightPx = Math.floor(usableHeightMm * pxPerMm);

      let yPx = 0;
      let pageIndex = 0;
      while (yPx < canvas.height) {
        if (pageIndex > 0) {
          pdf.addPage('a4', 'p');
          await drawHeader();
        }

        const remainingPx = canvas.height - yPx;
        const currentSlicePx = Math.min(sliceHeightPx, remainingPx);

        const sliceCanvas = document.createElement('canvas');
        sliceCanvas.width = canvas.width;
        sliceCanvas.height = currentSlicePx;
        const ctx = sliceCanvas.getContext('2d');
        ctx.drawImage(
          canvas,
          0,
          yPx,
          canvas.width,
          currentSlicePx,
          0,
          0,
          canvas.width,
          currentSlicePx
        );

        // Use JPEG compression for smaller file size (0.85 quality)
        const sliceData = sliceCanvas.toDataURL('image/jpeg', 0.85);
        const sliceHeightMm = currentSlicePx / pxPerMm;
        pdf.addImage(sliceData, 'JPEG', margin, topOffset, imgWidthMm, sliceHeightMm);
        drawFooter();

        yPx += currentSlicePx;
        pageIndex += 1;
      }

      const filename = `Surat_${surat.judul_surat.replace(/\s+/g, '_')}_${new Date().getTime()}.pdf`;
      pdf.save(filename);
      toast.success("PDF berhasil diunduh!");
    } catch (error) {
      console.error('Error exporting PDF:', error);
      toast.error("Gagal mengekspor PDF");
    }
  };

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    return date.toLocaleDateString('id-ID', {
      day: '2-digit',
      month: 'long',
      year: 'numeric'
    });
  };

  return (
    <div className="p-6 space-y-6">
      <Card>
        <CardHeader>
          <CardTitle className="text-2xl font-bold">Manajemen Surat</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex gap-4 mb-6">
            <div className="flex-1 relative">
              <Search className="absolute left-3 top-3 h-4 w-4 text-gray-400" />
              <Input
                placeholder="Cari judul surat..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10"
              />
            </div>
            {hasPermission(user?.role, 'surat', 'create') && (
              <Button onClick={handleOpenCreateDialog}>
                <Plus className="h-4 w-4 mr-2" />
                Buat Surat Baru
              </Button>
            )}
          </div>

          {loading ? (
            <div className="text-center py-8 text-gray-700 dark:text-gray-300">Loading...</div>
          ) : suratList.length === 0 ? (
            <div className="text-center py-8 text-gray-500 dark:text-gray-400">
              Belum ada surat. Klik tombol "Buat Surat Baru" untuk membuat surat pertama.
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full border-collapse">
                <thead>
                  <tr className="bg-gray-100 dark:bg-gray-800 border-b dark:border-gray-700">
                    <th className="p-3 text-left font-semibold text-gray-900 dark:text-gray-100">No</th>
                    <th className="p-3 text-left font-semibold text-gray-900 dark:text-gray-100">Judul Surat</th>
                    <th className="p-3 text-left font-semibold text-gray-900 dark:text-gray-100">Dibuat Oleh</th>
                    <th className="p-3 text-left font-semibold text-gray-900 dark:text-gray-100">Tanggal Dibuat</th>
                    <th className="p-3 text-center font-semibold text-gray-900 dark:text-gray-100">Aksi</th>
                  </tr>
                </thead>
                <tbody>
                  {suratList.map((surat, index) => (
                    <tr key={surat.id} className="border-b dark:border-gray-700 hover:bg-[#e4dcc8] dark:hover:bg-gray-800">
                      <td className="p-3 text-gray-900 dark:text-gray-100">{index + 1}</td>
                      <td className="p-3 font-medium text-gray-900 dark:text-gray-100">{surat.judul_surat}</td>
                      <td className="p-3 text-gray-700 dark:text-gray-300">{surat.creator_name || 'N/A'}</td>
                      <td className="p-3 text-gray-700 dark:text-gray-300">{formatDate(surat.created_at)}</td>
                      <td className="p-3">
                        <div className="flex gap-2 justify-center">
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => handlePreview(surat)}
                            title="Preview"
                          >
                            <Eye className="h-4 w-4" />
                          </Button>
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => handleExportPDF(surat)}
                            title="Export PDF"
                          >
                            <FileDown className="h-4 w-4" />
                          </Button>
                          {hasPermission(user?.role, 'surat', 'update') && (
                            <Button
                              size="sm"
                              variant="outline"
                              onClick={() => handleOpenEditDialog(surat)}
                              title="Edit"
                            >
                              <Edit className="h-4 w-4" />
                            </Button>
                          )}
                          {hasPermission(user?.role, 'surat', 'delete') && (
                            <Button
                              size="sm"
                              variant="destructive"
                              onClick={() => setDeleteConfirm(surat)}
                              title="Hapus"
                            >
                              <Trash2 className="h-4 w-4" />
                            </Button>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Delete Confirmation */}
      <AlertDialog
        open={deleteConfirm !== null}
        onOpenChange={(open) => {
          if (!open) setDeleteConfirm(null);
        }}
      >
        <AlertDialogContent className="bg-[#f7f1de] dark:bg-gray-900 dark:text-gray-100">
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Surat?</AlertDialogTitle>
          </AlertDialogHeader>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Tindakan ini tidak dapat dibatalkan.
            {deleteConfirm?.judul_surat ? ` (${deleteConfirm.judul_surat})` : ''}
          </p>
          <AlertDialogFooter>
            <AlertDialogCancel className="dark:bg-gray-800 dark:text-gray-200">
              Batal
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={confirmDelete}
              className="bg-red-600 hover:bg-red-700"
              disabled={loading}
            >
              {loading ? 'Menghapus...' : 'Hapus'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Form Dialog */}
      <Dialog
        open={showFormDialog}
        onOpenChange={(open) => {
          if (!open) handleCloseFormDialog();
        }}
      >
        <DialogContent className="max-w-6xl h-[95vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="text-xl">
              {editMode ? 'Edit Surat' : 'Buat Surat Baru'}
            </DialogTitle>
          </DialogHeader>
          
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium mb-2">
                Judul Surat <span className="text-red-500">*</span>
              </label>
              <Input
                value={judulSurat}
                onChange={(e) => setJudulSurat(e.target.value)}
                placeholder="Masukkan judul surat"
                className="text-base"
              />
            </div>
            
            <div>
              <label className="block text-sm font-medium mb-2">
                Isi Surat <span className="text-red-500">*</span>
              </label>
              <div className="border rounded-lg">
                <ReactQuill
                  ref={quillRef}
                  theme="snow"
                  value={isiSuratHtml}
                  onChange={handleEditorChange}
                  modules={quillModules}
                  formats={quillFormats}
                  placeholder="Tulis isi surat di sini..."
                  style={{ minHeight: '500px' }}
                />
              </div>
            </div>
          </div>

          <DialogFooter className="mt-6">
            <Button variant="outline" onClick={handleCloseFormDialog}>
              Batal
            </Button>
            <Button onClick={handleSubmit} disabled={loading}>
              {loading ? 'Menyimpan...' : editMode ? 'Update' : 'Simpan'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Preview Dialog */}
      <Dialog open={showPreviewDialog} onOpenChange={() => setShowPreviewDialog(false)}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Preview Surat</DialogTitle>
          </DialogHeader>
          
          {currentSurat && (
            <div className="space-y-4">
              {/* Letter Header */}
              <div className="border-b border-black pb-3 mb-4">
                <div className="flex items-center gap-4">
                  <img
                    src={kopLogoUrl || '/logo-garuda.png'}
                    alt="Logo"
                    className="w-14 h-14 object-contain flex-shrink-0"
                    onError={(e) => e.target.style.display = 'none'}
                  />
                  <div className="flex-1 text-center">
                    <p className="text-sm font-bold text-black uppercase tracking-wide">
                      PEMERINTAH KELURAHAN {(profil.nama_kelurahan || '').toUpperCase()}
                    </p>
                    <p className="text-base font-bold text-black uppercase">
                      KETUA RT. {profil.no_rt || '-'} RW. {profil.no_rw || '-'}
                    </p>
                    <p className="text-xs text-black mt-0.5">
                      {[profil.nama_kelurahan, profil.kecamatan, profil.kabupaten].filter(Boolean).join(', ')}
                    </p>
                  </div>
                </div>
              </div>

              {/* Letter Content */}
              <div 
                className="prose max-w-none ql-editor"
                dangerouslySetInnerHTML={{ __html: currentSurat.isi_surat_html }}
              />

              {/* Letter Footer */}
              <div className="mt-6">
                <hr className="border-black border-t" />
                <p className="text-center text-xs text-black mt-1">
                  {[profil.nama_kelurahan, profil.kecamatan, profil.kabupaten].filter(Boolean).join(', ')}
                </p>
              </div>
            </div>
          )}

          <DialogFooter>
            <Button variant="outline" onClick={() => setShowPreviewDialog(false)}>
              Tutup
            </Button>
            <Button onClick={() => handleExportPDF(currentSurat)}>
              <FileDown className="h-4 w-4 mr-2" />
              Export PDF
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default SuratPage;
