import React from 'react';
import { Heart } from 'lucide-react';

const BANTUAN_CONFIG = {
  KIS: {
    label: 'KIS',
    desc: 'Kartu Indonesia Sehat',
    cardBg: 'bg-blue-50 dark:bg-blue-900/20',
    cardBorder: 'border-blue-200 dark:border-blue-700',
    numColor: 'text-blue-700 dark:text-blue-300',
    labelColor: 'text-blue-600 dark:text-blue-400',
    badge: 'bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-300',
  },
  PIP: {
    label: 'PIP',
    desc: 'Program Indonesia Pintar',
    cardBg: 'bg-emerald-50 dark:bg-emerald-900/20',
    cardBorder: 'border-emerald-200 dark:border-emerald-700',
    numColor: 'text-emerald-700 dark:text-emerald-300',
    labelColor: 'text-emerald-600 dark:text-emerald-400',
    badge: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300',
  },
  BLT: {
    label: 'BLT',
    desc: 'Bantuan Langsung Tunai',
    cardBg: 'bg-orange-50 dark:bg-orange-900/20',
    cardBorder: 'border-orange-200 dark:border-orange-700',
    numColor: 'text-orange-700 dark:text-orange-300',
    labelColor: 'text-orange-600 dark:text-orange-400',
    badge: 'bg-orange-100 text-orange-700 dark:bg-orange-900/40 dark:text-orange-300',
  },
  BNPT: {
    label: 'BNPT',
    desc: 'Bantuan Non Tunai',
    cardBg: 'bg-purple-50 dark:bg-purple-900/20',
    cardBorder: 'border-purple-200 dark:border-purple-700',
    numColor: 'text-purple-700 dark:text-purple-300',
    labelColor: 'text-purple-600 dark:text-purple-400',
    badge: 'bg-purple-100 text-purple-700 dark:bg-purple-900/40 dark:text-purple-300',
  },
  RUTILAHU: {
    label: 'RUTILAHU',
    desc: 'Rumah Tidak Layak Huni',
    cardBg: 'bg-amber-50 dark:bg-amber-900/20',
    cardBorder: 'border-amber-200 dark:border-amber-700',
    numColor: 'text-amber-700 dark:text-amber-300',
    labelColor: 'text-amber-600 dark:text-amber-400',
    badge: 'bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300',
  },
};

const BANTUAN_KEYS = ['KIS', 'PIP', 'BLT', 'BNPT', 'RUTILAHU'];

const BantuanSosialWidget = ({ stats }) => {
  if (!stats || stats.total_penerima === 0) return null;

  const penerima = stats.penerima || [];
  const hasRT = penerima.some((p) => p.rt_name && p.rt_name !== '-');
  const hasRW = penerima.some((p) => p.rw_name && p.rw_name !== '-');

  return (
    <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow">
      {/* Header */}
      <div className="p-4 border-b border-[#d5cebc] dark:border-gray-700 flex items-center gap-2">
        <Heart className="h-5 w-5 text-rose-500 flex-shrink-0" />
        <div>
          <h3 className="text-base font-semibold text-gray-900 dark:text-gray-100">
            Penerima Bantuan Sosial
          </h3>
          <p className="text-xs text-gray-500 dark:text-gray-400">
            {stats.total_penerima} warga penerima bantuan
            {stats.total_warga ? ` dari ${stats.total_warga} total warga` : ''}
          </p>
        </div>
      </div>

      {/* Stat Cards */}
      <div className="p-4 border-b border-[#d5cebc] dark:border-gray-700">
        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3">
          {BANTUAN_KEYS.map((key) => {
            const cfg = BANTUAN_CONFIG[key];
            const count = stats[key] || 0;
            return (
              <div
                key={key}
                className={`rounded-lg border p-3 text-center ${cfg.cardBg} ${cfg.cardBorder}`}
              >
                <p className={`text-2xl font-bold ${cfg.numColor}`}>{count}</p>
                <p className={`text-xs font-semibold mt-0.5 ${cfg.labelColor}`}>{cfg.label}</p>
                <p className="text-[10px] text-gray-400 dark:text-gray-500 leading-tight mt-0.5">
                  {cfg.desc}
                </p>
              </div>
            );
          })}
        </div>
      </div>

      {/* Table */}
      {penerima.length > 0 && (
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-[#d5cebc] dark:border-gray-700 bg-[#efe7d2]/50 dark:bg-gray-700/30">
                <th className="text-left px-4 py-2.5 text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">
                  Nama Warga
                </th>
                <th className="text-left px-4 py-2.5 text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">
                  Blok Rumah
                </th>
                {hasRT && (
                  <th className="text-left px-4 py-2.5 text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">
                    RT
                  </th>
                )}
                {hasRW && (
                  <th className="text-left px-4 py-2.5 text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">
                    RW
                  </th>
                )}
                <th className="text-left px-4 py-2.5 text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">
                  Bantuan Diterima
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[#d5cebc] dark:divide-gray-700">
              {penerima.map((p, i) => (
                <tr key={i} className="hover:bg-[#efe7d2]/40 dark:hover:bg-gray-700/20 transition-colors">
                  <td className="px-4 py-2.5 font-medium text-gray-900 dark:text-gray-100">
                    {p.nama}
                  </td>
                  <td className="px-4 py-2.5 text-gray-600 dark:text-gray-400 font-mono text-sm">
                    {p.blok_rumah}
                  </td>
                  {hasRT && (
                    <td className="px-4 py-2.5 text-gray-600 dark:text-gray-400 text-xs">
                      {p.rt_name || '-'}
                    </td>
                  )}
                  {hasRW && (
                    <td className="px-4 py-2.5 text-gray-600 dark:text-gray-400 text-xs">
                      {p.rw_name || '-'}
                    </td>
                  )}
                  <td className="px-4 py-2.5">
                    <div className="flex flex-wrap gap-1">
                      {(p.bantuan || []).map((b) => {
                        const cfg = BANTUAN_CONFIG[b];
                        return (
                          <span
                            key={b}
                            className={`px-1.5 py-0.5 rounded text-[10px] font-semibold ${
                              cfg ? cfg.badge : 'bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-300'
                            }`}
                          >
                            {b}
                          </span>
                        );
                      })}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default BantuanSosialWidget;
