import React, { useState, useEffect, useCallback } from 'react';
import { API_BASE_URL } from '../../config/api';
import {
  Plus, Edit2, Trash2, Search, X, Upload, Database,
  AlertTriangle, ChevronDown, ChevronLeft, ChevronRight,
} from 'lucide-react';

const token = () => localStorage.getItem('vendor_token');
const hdrs  = () => ({ Authorization: `Bearer ${token()}`, 'Content-Type': 'application/json' });

// Dynamic badge colors based on tipe string (deterministic hash)
const BADGE_COLORS = [
  'bg-orange-100 text-orange-700',
  'bg-blue-100 text-blue-700',
  'bg-green-100 text-green-700',
  'bg-purple-100 text-purple-700',
  'bg-pink-100 text-pink-700',
  'bg-teal-100 text-teal-700',
  'bg-yellow-100 text-yellow-700',
  'bg-indigo-100 text-indigo-700',
];

const tipeColor = (tipe) => {
  let h = 0;
  for (let i = 0; i < (tipe || '').length; i++) h = (h * 31 + (tipe || '').charCodeAt(i)) | 0;
  return BADGE_COLORS[Math.abs(h) % BADGE_COLORS.length];
};

const TipeBadge = ({ tipe }) => (
  <span className={`text-xs px-2 py-0.5 rounded-full font-semibold ${tipeColor(tipe)}`}>
    {tipe}
  </span>
);

// ── Form Dialog ───────────────────────────────────────────────────────────────
function FormDialog({ open, onClose, onSave, editItem, provinsiList, tipeOptions }) {
  const availableTipes = tipeOptions?.length > 0 ? tipeOptions : ['provinsi', 'kota'];
  const [form, setForm] = useState({ tipe: availableTipes[0], nama: '', parent_id: '', kode: '' });
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (editItem) {
      setForm({ tipe: editItem.tipe, nama: editItem.nama, parent_id: editItem.parent_id || '', kode: editItem.kode || '' });
    } else {
      setForm({ tipe: availableTipes[0] || 'kota', nama: '', parent_id: '', kode: '' });
    }
    setError('');
  }, [open, editItem]);

  if (!open) return null;

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.nama.trim()) { setError('Nama harus diisi'); return; }
    setSaving(true); setError('');
    try {
      const body = { tipe: form.tipe, nama: form.nama.trim(), parent_id: form.parent_id || null, kode: form.kode || null };
      const url    = editItem ? `${API_BASE_URL}/api/vendor/wilayah-referensi/${editItem.id}` : `${API_BASE_URL}/api/vendor/wilayah-referensi/`;
      const method = editItem ? 'PUT' : 'POST';
      const res  = await fetch(url, { method, headers: hdrs(), body: JSON.stringify(body) });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal menyimpan');
      onSave();
      onClose();
    } catch (err) { setError(err.message); }
    setSaving(false);
  };

  return (
    <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[9999] flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md">
        <div className="p-5 border-b border-gray-200 flex items-center justify-between">
          <h3 className="font-bold text-gray-800 text-lg">{editItem ? 'Edit Referensi' : 'Tambah Referensi'}</h3>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><X size={18} /></button>
        </div>
        <form onSubmit={handleSubmit} className="p-5 space-y-4">
          {error && (
            <div className="flex items-center gap-2 bg-red-50 border border-red-200 rounded-lg p-3 text-sm text-red-600">
              <AlertTriangle size={14} />{error}
            </div>
          )}

          <div>
            <label className="text-sm font-medium text-gray-700 block mb-1.5">Tipe</label>
            <select value={form.tipe}
              onChange={e => setForm(f => ({ ...f, tipe: e.target.value, parent_id: '' }))}
              className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-violet-500">
              {availableTipes.map(t => <option key={t} value={t}>{t}</option>)}
            </select>
          </div>

          <div>
            <label className="text-sm font-medium text-gray-700 block mb-1.5">Nama <span className="text-red-500">*</span></label>
            <input value={form.nama}
              onChange={e => setForm(f => ({ ...f, nama: e.target.value }))}
              placeholder={form.tipe === 'provinsi' ? 'contoh: Jawa Tengah' : 'contoh: Kota Semarang'}
              className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-violet-500" />
          </div>

          {form.tipe !== 'provinsi' && (
            <div>
              <label className="text-sm font-medium text-gray-700 block mb-1.5">Induk (Provinsi)</label>
              <select value={form.parent_id}
                onChange={e => setForm(f => ({ ...f, parent_id: e.target.value }))}
                className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-violet-500">
                <option value="">-- Pilih Induk --</option>
                {provinsiList.map(p => <option key={p.id} value={p.id}>{p.nama}</option>)}
              </select>
            </div>
          )}

          <div>
            <label className="text-sm font-medium text-gray-700 block mb-1.5">Kode (opsional)</label>
            <input value={form.kode}
              onChange={e => setForm(f => ({ ...f, kode: e.target.value }))}
              placeholder="mis: 32"
              className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-violet-500" />
          </div>

          <div className="flex gap-3 pt-1">
            <button type="button" onClick={onClose}
              className="flex-1 border border-gray-200 rounded-xl py-2.5 text-sm font-medium hover:bg-gray-50 text-gray-700">
              Batal
            </button>
            <button type="submit" disabled={saving}
              className="flex-1 bg-[#ed6f5c] hover:bg-[#e05544] text-white rounded-xl py-2.5 text-sm font-semibold disabled:opacity-50">
              {saving ? 'Menyimpan...' : editItem ? 'Simpan Perubahan' : 'Tambah'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

// ── Import Dialog ─────────────────────────────────────────────────────────────
function ImportDialog({ open, onClose, onImported }) {
  const [tab, setTab] = useState('json');
  const [jsonText, setJsonText] = useState('');
  const [excelFile, setExcelFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!open) { setJsonText(''); setExcelFile(null); setResult(null); setError(''); }
  }, [open]);

  if (!open) return null;

  const handleImportJson = async () => {
    setError(''); setResult(null);
    let parsed;
    try { parsed = JSON.parse(jsonText); } catch { setError('JSON tidak valid'); return; }
    if (!Array.isArray(parsed)) { setError('JSON harus berupa array'); return; }
    setLoading(true);
    try {
      const res  = await fetch(`${API_BASE_URL}/api/vendor/wilayah-referensi/import-json`, {
        method: 'POST', headers: hdrs(), body: JSON.stringify(parsed),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal import');
      setResult(data);
      onImported();
    } catch (err) { setError(err.message); }
    setLoading(false);
  };

  const handleImportExcel = async () => {
    if (!excelFile) { setError('Pilih file Excel terlebih dahulu'); return; }
    setError(''); setResult(null); setLoading(true);
    try {
      const body = new FormData();
      body.append('file', excelFile);
      const res  = await fetch(`${API_BASE_URL}/api/vendor/wilayah-referensi/import-excel`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token()}` },
        body,
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal import');
      setResult(data);
      onImported();
    } catch (err) { setError(err.message); }
    setLoading(false);
  };

  return (
    <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[9999] flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg">
        <div className="p-5 border-b border-gray-200 flex items-center justify-between">
          <h3 className="font-bold text-gray-800 text-lg">Import Referensi</h3>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><X size={18} /></button>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-gray-200 px-5">
          {['json', 'excel'].map(t => (
            <button key={t} onClick={() => setTab(t)}
              className={`py-3 px-4 text-sm font-medium border-b-2 transition-colors ${
                tab === t ? 'border-[#ed6f5c] text-[#ed6f5c]' : 'border-transparent text-gray-500 hover:text-gray-700'
              }`}>
              {t === 'json' ? 'JSON' : 'Excel (.xlsx)'}
            </button>
          ))}
        </div>

        <div className="p-5 space-y-4">
          {error && (
            <div className="flex items-center gap-2 bg-red-50 border border-red-200 rounded-lg p-3 text-sm text-red-600">
              <AlertTriangle size={14} />{error}
            </div>
          )}
          {result && (
            <div className="bg-green-50 border border-green-200 rounded-lg p-3 text-sm text-green-700">
              ✓ Berhasil: <strong>{result.inserted}</strong> data dimasukkan
              {result.skipped > 0 && `, ${result.skipped} dilewati`}
            </div>
          )}

          {tab === 'json' ? (
            <>
              <p className="text-xs text-gray-500">Format: <code className="bg-gray-100 px-1 rounded">[{`{"tipe":"kota","nama":"Nama Kota","parent_id":"uuid-provinsi"}`}]</code></p>
              <textarea
                value={jsonText}
                onChange={e => setJsonText(e.target.value)}
                rows={8}
                placeholder={'[\n  {"tipe": "provinsi", "nama": "Jawa Tengah"},\n  {"tipe": "kota", "nama": "Kota Semarang", "parent_id": "uuid..."}\n]'}
                className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-xs font-mono focus:outline-none focus:ring-2 focus:ring-violet-500 resize-none"
              />
              <button onClick={handleImportJson} disabled={loading}
                className="w-full bg-[#ed6f5c] hover:bg-[#e05544] text-white rounded-xl py-2.5 text-sm font-semibold disabled:opacity-50">
                {loading ? 'Mengimpor...' : 'Import JSON'}
              </button>
            </>
          ) : (
            <>
              <p className="text-xs text-gray-500">Kolom wajib: <strong>tipe</strong>, <strong>nama</strong>. Opsional: parent_id, kode</p>
              <div className="border-2 border-dashed border-gray-200 rounded-xl p-6 text-center">
                <input type="file" accept=".xlsx,.xls" id="excel-upload"
                  className="hidden"
                  onChange={e => setExcelFile(e.target.files[0])} />
                <label htmlFor="excel-upload" className="cursor-pointer">
                  <Upload size={28} className="mx-auto text-gray-400 mb-2" />
                  <p className="text-sm text-gray-600 font-medium">
                    {excelFile ? excelFile.name : 'Klik untuk pilih file .xlsx'}
                  </p>
                  <p className="text-xs text-gray-400 mt-1">Format: .xlsx / .xls</p>
                </label>
              </div>
              <button onClick={handleImportExcel} disabled={loading || !excelFile}
                className="w-full bg-[#ed6f5c] hover:bg-[#e05544] text-white rounded-xl py-2.5 text-sm font-semibold disabled:opacity-50">
                {loading ? 'Mengimpor...' : 'Import Excel'}
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

// ── Main Page ─────────────────────────────────────────────────────────────────
export default function VendorWilayahReferensi() {
  const [items,        setItems]        = useState([]);
  const [provinsiList, setProvinsiList] = useState([]);
  const [tipeOptions,  setTipeOptions]  = useState([]);
  const [loading,      setLoading]      = useState(false);
  const [search,       setSearch]       = useState('');
  const [filterTipe,   setFilterTipe]   = useState('');
  const [totalAll,     setTotalAll]     = useState(null);   // total semua data tanpa filter
  const [totalFiltered, setTotalFiltered] = useState(0);   // total hasil filter (untuk pagination)
  const [page,         setPage]         = useState(1);
  const [perPage,      setPerPage]      = useState(25);
  const [showForm,     setShowForm]     = useState(false);
  const [editItem,     setEditItem]     = useState(null);
  const [showImport,   setShowImport]   = useState(false);
  const [deleteId,     setDeleteId]     = useState(null);
  const [seeding,      setSeeding]      = useState(false);

  const fetchTipeOptions = useCallback(async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/wilayah-referensi/tipe-list`, { headers: hdrs() });
      if (res.ok) { const d = await res.json(); setTipeOptions(d.tipes || []); }
    } catch {}
  }, []);

  const fetchTotalAll = useCallback(async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/wilayah-referensi/count`, { headers: hdrs() });
      if (res.ok) { const d = await res.json(); setTotalAll(d.count); }
    } catch {}
  }, []);

  const fetchItems = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (search)     params.set('search', search);
      if (filterTipe) params.set('tipe', filterTipe);
      params.set('limit', String(perPage));
      params.set('offset', String((page - 1) * perPage));

      const countParams = new URLSearchParams();
      if (search)     countParams.set('search', search);
      if (filterTipe) countParams.set('tipe', filterTipe);

      const [itemsRes, countRes] = await Promise.all([
        fetch(`${API_BASE_URL}/api/vendor/wilayah-referensi/?${params}`, { headers: hdrs() }),
        fetch(`${API_BASE_URL}/api/vendor/wilayah-referensi/count?${countParams}`, { headers: hdrs() }),
      ]);
      if (itemsRes.ok) setItems(await itemsRes.json());
      if (countRes.ok) { const d = await countRes.json(); setTotalFiltered(d.count); }
    } catch {}
    setLoading(false);
  }, [search, filterTipe, page, perPage]);

  const fetchProvinsi = useCallback(async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/wilayah-referensi/provinsi`);
      if (res.ok) setProvinsiList(await res.json());
    } catch {}
  }, []);

  useEffect(() => { fetchItems(); }, [fetchItems]);
  useEffect(() => { fetchProvinsi(); }, [fetchProvinsi]);
  useEffect(() => { fetchTipeOptions(); }, [fetchTipeOptions]);
  useEffect(() => { fetchTotalAll(); }, [fetchTotalAll]);

  const handleSearchChange = (val) => {
    setSearch(val);
    setPage(1);
  };

  const handleFilterTipeChange = (val) => {
    setFilterTipe(val);
    setPage(1);
  };

  const handleDelete = async (id) => {
    try {
      await fetch(`${API_BASE_URL}/api/vendor/wilayah-referensi/${id}`, { method: 'DELETE', headers: hdrs() });
      fetchItems();
      fetchTotalAll();
    } catch {}
    setDeleteId(null);
  };

  const handleSeed = async () => {
    setSeeding(true);
    try {
      await fetch(`${API_BASE_URL}/api/vendor/wilayah-referensi/seed-default`, { method: 'POST', headers: hdrs() });
      fetchItems();
      fetchProvinsi();
      fetchTipeOptions();
      fetchTotalAll();
    } catch {}
    setSeeding(false);
  };

  const totalPages = Math.ceil(totalFiltered / perPage) || 1;
  const isFiltered = !!(search || filterTipe);

  return (
    <div className="space-y-5">
      {/* Header */}
      <div className="bg-white rounded-2xl p-5 border border-gray-100 shadow-sm">
        <div className="flex items-center justify-between flex-wrap gap-3">
          <div>
            <h1 className="text-xl font-bold text-gray-900">Tabel Referensi Wilayah</h1>
            <p className="text-sm text-gray-500 mt-0.5">
              Data provinsi dan kota/kabupaten untuk isian onboarding tenant
              {totalAll !== null && (
                <span className="ml-2 text-gray-400">
                  {isFiltered
                    ? `(${totalFiltered} dari ${totalAll} data)`
                    : `(${totalAll} data)`}
                </span>
              )}
            </p>
          </div>
          <div className="flex items-center gap-2 flex-wrap">
            {totalAll === 0 && (
              <button onClick={handleSeed} disabled={seeding}
                className="flex items-center gap-2 px-3 py-2 bg-orange-500 hover:bg-orange-600 text-white rounded-xl text-sm font-medium disabled:opacity-50">
                <Database size={15} />
                {seeding ? 'Seeding...' : 'Seed Data Jawa Barat'}
              </button>
            )}
            <button onClick={() => setShowImport(true)}
              className="flex items-center gap-2 px-3 py-2 border border-gray-200 rounded-xl text-sm font-medium text-gray-700 hover:bg-gray-50">
              <Upload size={15} />Import
            </button>
            <button onClick={() => { setEditItem(null); setShowForm(true); }}
              className="flex items-center gap-2 px-4 py-2 bg-[#ed6f5c] hover:bg-[#e05544] text-white rounded-xl text-sm font-semibold">
              <Plus size={15} />Tambah
            </button>
          </div>
        </div>

        {/* Filter bar */}
        <div className="flex gap-3 mt-4 flex-wrap">
          <div className="relative flex-1 min-w-[200px]">
            <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
            <input
              value={search}
              onChange={e => handleSearchChange(e.target.value)}
              placeholder="Cari nama, tipe, kode..."
              className="w-full pl-9 pr-3 py-2 border border-gray-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-violet-500"
            />
          </div>
          <div className="relative">
            <select value={filterTipe} onChange={e => handleFilterTipeChange(e.target.value)}
              className="appearance-none pl-3 pr-8 py-2 border border-gray-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-violet-500 bg-white">
              <option value="">Semua Tipe</option>
              {tipeOptions.map(t => <option key={t} value={t}>{t}</option>)}
            </select>
            <ChevronDown size={13} className="absolute right-2.5 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" />
          </div>
        </div>
      </div>

      {/* Table */}
      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
        {loading ? (
          <div className="py-16 text-center text-gray-400 text-sm">Memuat data...</div>
        ) : items.length === 0 ? (
          <div className="py-16 text-center">
            <Database size={36} className="mx-auto text-gray-300 mb-3" />
            <p className="text-gray-500 font-medium">
              {isFiltered ? 'Tidak ada data yang cocok' : 'Belum ada data referensi'}
            </p>
            <p className="text-gray-400 text-sm mt-1">
              {isFiltered ? 'Coba ubah kata kunci atau filter tipe' : 'Gunakan tombol "Tambah", "Import", atau "Seed Data Jawa Barat"'}
            </p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-gray-50 border-b border-gray-100">
                <tr>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide w-10">No</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide">Tipe</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide">Nama</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide">Provinsi Induk</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide">Kode</th>
                  <th className="px-4 py-3 text-center text-xs font-semibold text-gray-500 uppercase tracking-wide">Aksi</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {items.map((item, idx) => (
                  <tr key={item.id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-4 py-3 text-gray-400">{(page - 1) * perPage + idx + 1}</td>
                    <td className="px-4 py-3"><TipeBadge tipe={item.tipe} /></td>
                    <td className="px-4 py-3 font-medium text-gray-800">{item.nama}</td>
                    <td className="px-4 py-3 text-gray-500">{item.parent_nama || <span className="text-gray-300">—</span>}</td>
                    <td className="px-4 py-3 text-gray-500">{item.kode || <span className="text-gray-300">—</span>}</td>
                    <td className="px-4 py-3">
                      <div className="flex items-center justify-center gap-2">
                        <button onClick={() => { setEditItem(item); setShowForm(true); }}
                          className="p-1.5 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors">
                          <Edit2 size={14} />
                        </button>
                        <button onClick={() => setDeleteId(item.id)}
                          className="p-1.5 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors">
                          <Trash2 size={14} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* Pagination */}
        {!loading && totalFiltered > 0 && (
          <div className="flex items-center justify-between px-4 py-3 border-t border-gray-100 flex-wrap gap-2">
            <div className="flex items-center gap-2 text-sm text-gray-500">
              <span>
                {(page - 1) * perPage + 1}–{Math.min(page * perPage, totalFiltered)} dari {totalFiltered} data
              </span>
              <span className="text-gray-300">|</span>
              <span>Tampilkan</span>
              <select
                value={perPage}
                onChange={e => { setPerPage(Number(e.target.value)); setPage(1); }}
                className="border border-gray-200 rounded-lg px-2 py-1 text-sm focus:outline-none focus:ring-2 focus:ring-violet-500 bg-white"
              >
                <option value={25}>25</option>
                <option value={50}>50</option>
                <option value={100}>100</option>
              </select>
              <span>per halaman</span>
            </div>
            <div className="flex items-center gap-1">
              <button
                onClick={() => setPage(p => Math.max(1, p - 1))}
                disabled={page === 1}
                className="p-1.5 rounded-lg border border-gray-200 text-gray-500 hover:bg-gray-50 disabled:opacity-40 disabled:cursor-not-allowed"
              >
                <ChevronLeft size={15} />
              </button>
              <span className="px-3 py-1 text-sm text-gray-700 font-medium">
                {page} / {totalPages}
              </span>
              <button
                onClick={() => setPage(p => Math.min(totalPages, p + 1))}
                disabled={page === totalPages}
                className="p-1.5 rounded-lg border border-gray-200 text-gray-500 hover:bg-gray-50 disabled:opacity-40 disabled:cursor-not-allowed"
              >
                <ChevronRight size={15} />
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Delete confirm */}
      {deleteId && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[9999] flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm p-6 text-center">
            <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <Trash2 size={20} className="text-red-500" />
            </div>
            <h3 className="font-bold text-gray-800 text-lg mb-1">Hapus Data?</h3>
            <p className="text-sm text-gray-500 mb-5">Tindakan ini tidak dapat dibatalkan.</p>
            <div className="flex gap-3">
              <button onClick={() => setDeleteId(null)}
                className="flex-1 border border-gray-200 rounded-xl py-2.5 text-sm font-medium hover:bg-gray-50 text-gray-700">
                Batal
              </button>
              <button onClick={() => handleDelete(deleteId)}
                className="flex-1 bg-red-500 hover:bg-red-600 text-white rounded-xl py-2.5 text-sm font-semibold">
                Hapus
              </button>
            </div>
          </div>
        </div>
      )}

      <FormDialog
        open={showForm}
        onClose={() => { setShowForm(false); setEditItem(null); }}
        onSave={() => { fetchItems(); fetchProvinsi(); fetchTipeOptions(); fetchTotalAll(); }}
        editItem={editItem}
        provinsiList={provinsiList}
        tipeOptions={tipeOptions}
      />

      <ImportDialog
        open={showImport}
        onClose={() => setShowImport(false)}
        onImported={() => { fetchItems(); fetchProvinsi(); fetchTipeOptions(); fetchTotalAll(); }}
      />
    </div>
  );
}
