import { useEffect, useRef, useState, useCallback } from 'react';
import { API_BASE_URL } from '@/config/api';

const ADMIN_ROLES = ['admin', 'pengurus_rw', 'pengurus_kelurahan'];

const FCM_CONFIG_OK =
  process.env.REACT_APP_FIREBASE_API_KEY &&
  process.env.REACT_APP_FIREBASE_PROJECT_ID &&
  process.env.REACT_APP_FIREBASE_MESSAGING_SENDER_ID &&
  process.env.REACT_APP_FIREBASE_APP_ID &&
  process.env.REACT_APP_FIREBASE_VAPID_KEY;

/**
 * Returns { needsPermission, enableNotifications }
 * - needsPermission: true jika admin belum grant notifikasi
 * - enableNotifications: panggil dari user gesture (klik button)
 */
export default function useFCM(user, token) {
  const registeredRef  = useRef(false);
  const messagingRef   = useRef(null);
  const [needsPermission, setNeedsPermission] = useState(false);

  // Inisialisasi Firebase messaging (tanpa minta permission)
  useEffect(() => {
    if (!user || !token) return;
    if (!ADMIN_ROLES.includes(user.role)) return;
    if (!FCM_CONFIG_OK) return;
    if (registeredRef.current) return;

    const init = async () => {
      try {
        const { initializeApp, getApps } = await import('firebase/app');
        const { getMessaging, onMessage } = await import('firebase/messaging');

        const cfg = {
          apiKey:            process.env.REACT_APP_FIREBASE_API_KEY,
          projectId:         process.env.REACT_APP_FIREBASE_PROJECT_ID,
          messagingSenderId: process.env.REACT_APP_FIREBASE_MESSAGING_SENDER_ID,
          appId:             process.env.REACT_APP_FIREBASE_APP_ID,
        };
        const app       = getApps().length === 0 ? initializeApp(cfg) : getApps()[0];
        const messaging = getMessaging(app);
        messagingRef.current = messaging;

        // Handle foreground push (saat app terbuka)
        onMessage(messaging, (payload) => {
          if (payload.data?.type === 'panic_button') {
            playAlertSound();
            navigator.vibrate?.([300, 100, 300, 100, 300]);
            const title   = payload.notification?.title || '🚨 Alert Darurat!';
            const body    = payload.notification?.body  || 'Ada laporan darurat baru.';
            const alertId = payload.data?.alert_id || Date.now();
            const url     = payload.data?.url || '/panic-alerts';
            if (Notification.permission === 'granted') {
              // Lewat SW agar konsisten — new Notification() diblokir Chrome saat SW aktif
              navigator.serviceWorker.ready.then(swReg => {
                swReg.showNotification(title, {
                  body,
                  icon:              '/logo192.png',
                  requireInteraction: true,
                  tag:               `panic-alert-${alertId}`,
                  data:              { url },
                });
              });
            }
          }
        });

        const currentPerm = Notification.permission;
        if (currentPerm === 'granted') {
          await registerToken(messaging, token);
        } else {
          // 'default' atau 'denied' — tampilkan banner
          // 'denied': banner akan tunjukkan instruksi unblock
          setNeedsPermission(true);
        }
      } catch (err) {
        console.warn('[FCM] Init gagal:', err.message);
      }
    };

    init();
  }, [user, token]); // only re-run when user/token changes

  // Dipanggil dari klik user (user gesture) — agar browser tidak block
  const enableNotifications = useCallback(async () => {
    try {
      const permission = await Notification.requestPermission();
      if (permission !== 'granted') {
        setNeedsPermission(false); // user tolak, sembunyikan banner
        return false;
      }
      setNeedsPermission(false);
      if (messagingRef.current) {
        await registerToken(messagingRef.current, token);
      }
      return true;
    } catch (err) {
      console.warn('[FCM] Enable gagal:', err.message);
      return false;
    }
  }, [token]);

  return { needsPermission, enableNotifications };
}

function waitUntilActive(swReg) {
  return new Promise((resolve) => {
    if (swReg.active) { resolve(); return; }
    const sw = swReg.installing || swReg.waiting;
    if (!sw) { resolve(); return; }
    sw.addEventListener('statechange', function handler(e) {
      if (e.target.state === 'activated') {
        sw.removeEventListener('statechange', handler);
        resolve();
      }
    });
    setTimeout(resolve, 6000); // fallback — jangan tunggu selamanya
  });
}

async function registerToken(messaging, authToken) {
  try {
    const { getToken } = await import('firebase/messaging');
    const vapidKey = process.env.REACT_APP_FIREBASE_VAPID_KEY;

    // Register SW dan tunggu sampai state 'activated' pada registrasi ini
    const swReg = await navigator.serviceWorker.register('/firebase-messaging-sw.js');
    await waitUntilActive(swReg);

    const fcmToken = await getToken(messaging, { vapidKey, serviceWorkerRegistration: swReg });
    if (!fcmToken) {
      window.__fcmErr = 'getToken returned empty';
      return;
    }

    // Skip update DB kalau token tidak berubah (hindari token cycling tiap refresh)
    const prevToken = localStorage.getItem('fcm_token_cached');
    if (prevToken === fcmToken) {
      console.info('[FCM] Token sama, skip update DB');
      window.__fcmErr = null;
      return;
    }

    await fetch(`${API_BASE_URL}/api/panic-button/fcm-token`, {
      method:  'PUT',
      headers: { Authorization: `Bearer ${authToken}`, 'Content-Type': 'application/json' },
      body:    JSON.stringify({ fcm_token: fcmToken }),
    });
    localStorage.setItem('fcm_token_cached', fcmToken);
    console.info('[FCM] Token terdaftar:', fcmToken.slice(0, 20) + '...');
    window.__fcmErr = null;
  } catch (err) {
    // Simpan error di window — ketik window.__fcmErr di console untuk lihat
    window.__fcmErr = err.code + ': ' + err.message;
    console.error('[FCM] Register token GAGAL:', err.code, err.message);
  }
}

function playAlertSound() {
  try {
    const ctx  = new (window.AudioContext || window.webkitAudioContext)();
    const dur  = 3.2;   // total durasi sirine (detik)
    const now  = ctx.currentTime;

    const osc  = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);

    osc.type = 'sawtooth';

    // Sirine polisi: sweep 600Hz → 1200Hz → 600Hz → 1200Hz (2 siklus)
    const lo = 600, hi = 1200, half = dur / 4;
    osc.frequency.setValueAtTime(lo, now);
    osc.frequency.linearRampToValueAtTime(hi, now + half);
    osc.frequency.linearRampToValueAtTime(lo, now + half * 2);
    osc.frequency.linearRampToValueAtTime(hi, now + half * 3);
    osc.frequency.linearRampToValueAtTime(lo, now + half * 4);

    // Volume: fade in → sustain → fade out
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.4, now + 0.1);
    gain.gain.setValueAtTime(0.4, now + dur - 0.2);
    gain.gain.linearRampToValueAtTime(0, now + dur);

    osc.start(now);
    osc.stop(now + dur);
  } catch { /* Audio API tidak tersedia */ }
}
