import { useState } from "react";
import { Button } from "@/components/ui/button";
import { API_BASE_URL } from "@/config/api";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow
} from "@/components/ui/table";
import {
  AlertDialog,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogContent,
  AlertDialogCancel,
  AlertDialogAction
} from "@/components/ui/alert-dialog";
import { ChevronDown, ChevronRight, Image } from "lucide-react";
import { toast } from "@/components/ui/sonner";
import { useAuth } from "@/contexts/AuthContext";
import { useRolePermissions } from "@/hooks/useRolePermissions";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";

export default function KeuanganTable({
  data,
  onEdit,
  onDelete,
  selectedRows,
  setSelectedRows
}) {
  const [sortField, setSortField] = useState("");
  const [sortDir, setSortDir] = useState("asc");
  const { token, user } = useAuth(); // 🔐 JWT
  const { canRead, canUpdate: canEdit, canDelete } = useRolePermissions(user?.role, token);
  const [deleteConfirm, setDeleteConfirm] = useState(null);
  const [expandedRows, setExpandedRows] = useState([]);
  const [openGalleryModal, setOpenGalleryModal] = useState(false);
  const [galleryImages, setGalleryImages] = useState([]);
  const [selectedGalleryIndex, setSelectedGalleryIndex] = useState(0);
  const [galleryImageDataUrls, setGalleryImageDataUrls] = useState({});

  const toggleSort = (field) => {
    const newDir =
      sortField === field && sortDir === "asc" ? "desc" : "asc";
    setSortField(field);
    setSortDir(newDir);
  };

  const sortedData = [...data].sort((a, b) => {
    if (!sortField) return 0;
    const aVal = a[sortField] ?? "";
    const bVal = b[sortField] ?? "";
    return sortDir === "asc"
      ? aVal.toString().localeCompare(bVal.toString())
      : bVal.toString().localeCompare(aVal.toString());
  });

  const toggleRow = (id) => {
    setSelectedRows(
      selectedRows.includes(id)
        ? selectedRows.filter((r) => r !== id)
        : [...selectedRows, id]
    );
  };

  const toggleAll = () => {
    if (selectedRows.length === data.length) setSelectedRows([]);
    else setSelectedRows(data.map((t) => t.id));
  };

  const remove = async (id) => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/keuangan/${id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (!res.ok) throw new Error();

      toast.success("Transaksi dihapus");
      onDelete();
    } catch {
      toast.error("Gagal menghapus transaksi");
    }
    setDeleteConfirm(null);
  };

  const formatDate = (val) => {
    if (!val) return "-";
    return new Date(val).toLocaleDateString("id-ID");
  };

  const formatRupiah = (val) => {
    return new Intl.NumberFormat("id-ID", {
      style: "currency",
      currency: "IDR",
      minimumFractionDigits: 0,
    }).format(val);
  };
  const openImageGalleryModal = (biayaRutinId) => {
    if (!biayaRutinId) {
      toast.error("Tidak ada gambar untuk transaksi ini");
      return;
    }

    // Fetch images from biaya rutin
    const loadImages = async () => {
      try {
        const imgRes = await fetch(
          `${API_BASE_URL}/api/finance-recurring/${biayaRutinId}/images`,
          {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          }
        );

        if (!imgRes.ok) {
          toast.error("Gagal load gambar");
          return;
        }

        const imgData = await imgRes.json();
        const images = imgData.images || [];

        if (images.length === 0) {
          toast.error("Tidak ada gambar untuk biaya ini");
          return;
        }

        setGalleryImages(images);
        setSelectedGalleryIndex(0);
        setGalleryImageDataUrls({});
        setOpenGalleryModal(true);

        // Fetch all images as blobs
        const dataUrls = {};
        for (const img of images) {
          try {
            const res = await fetch(
              `${API_BASE_URL}/api/finance-recurring/${biayaRutinId}/images/${img.id}`,
              {
                headers: {
                  Authorization: `Bearer ${token}`,
                },
              }
            );

            if (res.ok) {
              const blob = await res.blob();
              const dataUrl = URL.createObjectURL(blob);
              dataUrls[img.id] = dataUrl;
            }
          } catch (err) {
            console.warn(`Failed to load image ${img.id}:`, err);
          }
        }
        setGalleryImageDataUrls(dataUrls);
      } catch (err) {
        console.error("Error loading gallery:", err);
        toast.error("Gagal membuka galeri");
      }
    };

    loadImages();
  };
  const toggleExpanded = (id) => {
    setExpandedRows(
      expandedRows.includes(id)
        ? expandedRows.filter((r) => r !== id)
        : [...expandedRows, id]
    );
  };

  return (
    <>
      <Table className="border rounded-lg bg-[#f7f1de] dark:bg-gray-900 shadow-sm">
        <TableHeader>
          <TableRow className="dark:border-gray-700">
            {/* EXPAND ICON */}
            <TableHead className="w-10"></TableHead>

            {/* CHECKBOX */}
            <TableHead className="w-10">
              <input
                type="checkbox"
                checked={
                  data.length > 0 && selectedRows.length === data.length
                }
                onChange={toggleAll}
              />
            </TableHead>

            <TableHead
              onClick={() => toggleSort("tanggal")}
              className="cursor-pointer dark:text-gray-300"
            >
              Tanggal {sortField === "tanggal" && (sortDir === "asc" ? "▲" : "▼")}
            </TableHead>

            <TableHead className="dark:text-gray-300">Kategori</TableHead>

            <TableHead
              onClick={() => toggleSort("tipe")}
              className="cursor-pointer dark:text-gray-300"
            >
              Tipe {sortField === "tipe" && (sortDir === "asc" ? "▲" : "▼")}
            </TableHead>

            <TableHead className="text-right dark:text-gray-300">Jumlah</TableHead>
            {canRead('finance') && canEdit('finance') && (<TableHead className="text-right dark:text-gray-300">Edit</TableHead>)}
          </TableRow>
        </TableHeader>

        <TableBody>
          {sortedData.map((t) => (
            <>
              <TableRow key={t.id} className="dark:border-gray-700 dark:hover:bg-gray-800">
                {/* EXPAND ICON */}
                <TableCell 
                  className="w-10 cursor-pointer"
                  onClick={() => toggleExpanded(t.id)}
                >
                  {expandedRows.includes(t.id) ? (
                    <ChevronDown className="w-5 h-5 text-gray-600 dark:text-gray-400" />
                  ) : (
                    <ChevronRight className="w-5 h-5 text-gray-600 dark:text-gray-400" />
                  )}
                </TableCell>

                {/* CHECKBOX */}
                <TableCell className="w-10">
                  <input
                    type="checkbox"
                    checked={selectedRows.includes(t.id)}
                    onChange={() => toggleRow(t.id)}
                  />
                </TableCell>

                <TableCell className="dark:text-gray-200">{formatDate(t.tanggal)}</TableCell>
                <TableCell className="dark:text-gray-200">{t.kategori}</TableCell>

                <TableCell className="dark:text-gray-200">
                  <span
                    className={`px-2 py-1 rounded-full text-xs font-semibold ${
                      t.tipe === "pemasukan"
                        ? "bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-200"
                        : "bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-200"
                    }`}
                  >
                    {t.tipe === "pemasukan" ? "↑ Pemasukan" : "↓ Pengeluaran"}
                  </span>
                </TableCell>

                <TableCell className="text-right dark:text-gray-200 font-semibold">
                  <span
                    className={
                      t.tipe === "pemasukan"
                        ? "text-green-600 dark:text-green-400"
                        : "text-red-600 dark:text-red-400"
                    }
                  >
                    {t.tipe === "pemasukan" ? "+" : "-"} {formatRupiah(t.jumlah)}
                  </span>
                </TableCell>

                <TableCell className="text-right">
                  {canRead('finance') && canEdit('finance') && (
                    <Button
                      size="sm"
                      onClick={() => onEdit(t)}
                      className="bg-[#ed6f5c] hover:bg-[#e05544] text-white"
                    >
                      Edit
                    </Button>
                  )}
                </TableCell>
              </TableRow>

              {/* EXPANDED DETAIL ROW */}
              {expandedRows.includes(t.id) && (
                <TableRow className="dark:border-gray-700 bg-[#ece4cf] dark:bg-gray-800/50">
                  <TableCell colSpan="7" className="p-6">
                    <div className="grid grid-cols-2 md:grid-cols-3 gap-6">
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Tanggal</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">{formatDate(t.tanggal)}</p>
                      </div>
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Kategori</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">{t.kategori}</p>
                      </div>
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Tipe</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">
                          {t.tipe === "pemasukan" ? "Pemasukan" : "Pengeluaran"}
                        </p>
                      </div>
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Jumlah</p>
                        <p className={`text-sm font-semibold mt-1 ${
                          t.tipe === "pemasukan"
                            ? "text-green-600 dark:text-green-400"
                            : "text-red-600 dark:text-red-400"
                        }`}>
                          {t.tipe === "pemasukan" ? "+" : "-"} {formatRupiah(t.jumlah)}
                        </p>
                      </div>
                      <div className="md:col-span-2">
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Deskripsi</p>
                        <div className="flex items-center gap-2 mt-1">
                          <p className="text-sm font-medium text-gray-900 dark:text-gray-100">{t.deskripsi || "-"}</p>
                          {t.biaya_rutin_id && t.deskripsi?.includes("[nota]") && (
                            <Button
                              size="sm"
                              variant="ghost"
                              onClick={() => openImageGalleryModal(t.biaya_rutin_id)}
                              className="h-6 w-6 p-0"
                              title="Lihat nota"
                            >
                              <Image className="h-4 w-4 text-green-500" />
                            </Button>
                          )}
                        </div>
                      </div>
                      {canDelete(user?.role) && (
                        <div className="flex gap-2 items-end">
                          <Button
                            size="sm"
                            variant="destructive"
                            onClick={() => setDeleteConfirm(t.id)}
                          >
                            Hapus
                          </Button>
                        </div>
                      )}
                    </div>
                  </TableCell>
                </TableRow>
              )}
            </>
          ))}
        </TableBody>
      </Table>

      {/* DELETE CONFIRMATION */}
      <AlertDialog open={deleteConfirm !== null} onOpenChange={(open) => !open && setDeleteConfirm(null)}>
        <AlertDialogContent className="bg-[#f7f1de] dark:bg-gray-900 dark:text-gray-100">
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Transaksi?</AlertDialogTitle>
          </AlertDialogHeader>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Tindakan ini tidak dapat dibatalkan.
          </p>
          <AlertDialogFooter>
            <AlertDialogCancel className="dark:bg-gray-800 dark:text-gray-200">
              Batal
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={() => remove(deleteConfirm)}
              className="bg-red-600 hover:bg-red-700"
            >
              Hapus
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* IMAGE GALLERY MODAL */}
      <Dialog open={openGalleryModal} onOpenChange={setOpenGalleryModal}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Galeri Foto Nota</DialogTitle>
          </DialogHeader>

          {galleryImages.length > 0 ? (
            <div className="space-y-4">
              {/* Main Image Display */}
              {galleryImageDataUrls[galleryImages[selectedGalleryIndex]?.id] && (
                <div className="flex justify-center bg-gray-100 dark:bg-gray-800 rounded-lg p-4 min-h-[280px] max-h-[350px]">
                  <img
                    src={galleryImageDataUrls[galleryImages[selectedGalleryIndex]?.id]}
                    alt="Gallery"
                    className="max-w-full max-h-full object-contain rounded"
                  />
                </div>
              )}

              {/* Image Info */}
              {galleryImages[selectedGalleryIndex] && (
                <div className="bg-gray-50 dark:bg-gray-900 p-3 rounded space-y-1 text-sm">
                  <p className="text-gray-600 dark:text-gray-400">
                    <span className="font-semibold">File:</span> {galleryImages[selectedGalleryIndex].file_name}
                  </p>
                  <p className="text-gray-600 dark:text-gray-400">
                    <span className="font-semibold">Ukuran:</span> {Math.round(galleryImages[selectedGalleryIndex].file_size / 1024)} KB
                  </p>
                  <p className="text-gray-600 dark:text-gray-400">
                    <span className="font-semibold">Gambar:</span> {selectedGalleryIndex + 1} / {galleryImages.length}
                  </p>
                </div>
              )}

              {/* Thumbnail Grid */}
              {galleryImages.length > 1 && (
                <div className="grid grid-cols-4 gap-2">
                  {galleryImages.map((img, idx) => (
                    <button
                      key={img.id}
                      onClick={() => setSelectedGalleryIndex(idx)}
                      className={`rounded border-2 overflow-hidden transition-colors h-16 ${
                        selectedGalleryIndex === idx
                          ? "border-blue-500 bg-blue-50 dark:bg-blue-900"
                          : "border-[#d5cebc] dark:border-gray-700 hover:border-gray-400"
                      }`}
                    >
                      {galleryImageDataUrls[img.id] && (
                        <img
                          src={galleryImageDataUrls[img.id]}
                          alt={`Thumbnail ${idx + 1}`}
                          className="w-full h-full object-cover"
                        />
                      )}
                    </button>
                  ))}
                </div>
              )}

              {/* Navigation Buttons */}
              {galleryImages.length > 1 && (
                <div className="flex gap-2 justify-center">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setSelectedGalleryIndex(Math.max(0, selectedGalleryIndex - 1))}
                    disabled={selectedGalleryIndex === 0}
                  >
                    Sebelumnya
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setSelectedGalleryIndex(Math.min(galleryImages.length - 1, selectedGalleryIndex + 1))}
                    disabled={selectedGalleryIndex === galleryImages.length - 1}
                  >
                    Berikutnya
                  </Button>
                </div>
              )}
            </div>
          ) : (
            <p className="text-center text-gray-500 dark:text-gray-400 py-4">Tidak ada gambar</p>
          )}

          <DialogFooter>
            <Button variant="outline" onClick={() => setOpenGalleryModal(false)}>
              Tutup
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}
