import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useAuth } from '@/contexts/AuthContext';
import { API_BASE_URL } from '@/config/api';
import { toast } from '@/components/ui/sonner';
import { Siren, X, Send } from 'lucide-react';

const COOLDOWN_SECONDS = 60;
const ALLOWED_ROLES = ['warga', 'admin', 'pengurus_rw', 'pengurus_kelurahan'];
const DRAG_THRESHOLD = 8; // px sedikit lebih besar untuk mobile
const BTN_SIZE = 56; // px (w-14)

function playSiren() {
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    const dur = 3.2;
    const now = ctx.currentTime;
    const osc  = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.type = 'sawtooth';
    const lo = 600, hi = 1200, half = dur / 4;
    osc.frequency.setValueAtTime(lo, now);
    osc.frequency.linearRampToValueAtTime(hi, now + half);
    osc.frequency.linearRampToValueAtTime(lo, now + half * 2);
    osc.frequency.linearRampToValueAtTime(hi, now + half * 3);
    osc.frequency.linearRampToValueAtTime(lo, now + half * 4);
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.4, now + 0.1);
    gain.gain.setValueAtTime(0.4, now + dur - 0.2);
    gain.gain.linearRampToValueAtTime(0, now + dur);
    osc.start(now);
    osc.stop(now + dur);
  } catch { /* Audio API tidak tersedia */ }
}

function getDefaultPos() {
  const vw = window.innerWidth  || 375;
  const vh = window.innerHeight || 667;
  // Pojok kanan bawah, beri ruang 16px dari tepi + safe area
  return { x: vw - BTN_SIZE - 16, y: vh - BTN_SIZE - 80 };
}

export default function PanicButton() {
  const { token, user } = useAuth();

  // Posisi floating — load dari localStorage, fallback ke pojok kanan bawah
  const [pos, setPos] = useState(() => {
    try {
      const saved = JSON.parse(localStorage.getItem('panic_btn_pos'));
      if (saved && typeof saved.x === 'number' && typeof saved.y === 'number') return saved;
    } catch { /* ignore */ }
    return getDefaultPos();
  });
  const [isDragging, setIsDragging] = useState(false);
  const [enabled, setEnabled]   = useState(true);
  const [cooldown, setCooldown] = useState(0);       // detik tersisa
  const [showModal, setShowModal] = useState(false);
  const [pesan, setPesan]       = useState('');
  const [sending, setSending]   = useState(false);

  const dragRef      = useRef(null); // {startX, startY, posX, posY}
  const movedRef     = useRef(false);
  const cooldownRef  = useRef(null);
  const btnRef       = useRef(null);

  // Cek status panic button dari vendor — poll setiap 60 detik
  useEffect(() => {
    if (!token || !ALLOWED_ROLES.includes(user?.role)) return;
    const checkStatus = () => {
      fetch(`${API_BASE_URL}/api/panic-button/status`, {
        headers: { Authorization: `Bearer ${token}` },
      })
        .then(r => r.ok ? r.json() : null)
        .then(d => { if (d != null) setEnabled(d.enabled); })
        .catch(() => {});
    };
    checkStatus();
    const interval = setInterval(checkStatus, 10_000);
    return () => clearInterval(interval);
  }, [token, user?.role]);

  // Cooldown dari localStorage (agar persist antar reload)
  useEffect(() => {
    const savedCooldown = parseInt(localStorage.getItem('panic_cooldown_until') || '0');
    const remaining = Math.ceil((savedCooldown - Date.now()) / 1000);
    if (remaining > 0) {
      setCooldown(remaining);
      startCooldownTimer(remaining);
    }
  }, []);

  const startCooldownTimer = useCallback((seconds) => {
    if (cooldownRef.current) clearInterval(cooldownRef.current);
    let remaining = seconds;
    cooldownRef.current = setInterval(() => {
      remaining -= 1;
      setCooldown(remaining);
      if (remaining <= 0) {
        clearInterval(cooldownRef.current);
        setCooldown(0);
        localStorage.removeItem('panic_cooldown_until');
      }
    }, 1000);
  }, []);

  useEffect(() => () => { if (cooldownRef.current) clearInterval(cooldownRef.current); }, []);

  // Re-clamp posisi saat resize/orientasi berubah (penting di mobile)
  useEffect(() => {
    const handleResize = () => {
      setPos(prev => {
        const maxX = window.innerWidth  - BTN_SIZE - 4;
        const maxY = window.innerHeight - BTN_SIZE - 4;
        const clamped = {
          x: Math.max(4, Math.min(maxX, prev.x)),
          y: Math.max(4, Math.min(maxY, prev.y)),
        };
        localStorage.setItem('panic_btn_pos', JSON.stringify(clamped));
        return clamped;
      });
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // ─── DRAG LOGIC (pointer events — works on both mouse & touch) ────
  const onPointerDown = useCallback((e) => {
    e.preventDefault();
    e.currentTarget.setPointerCapture(e.pointerId); // capture pointer agar tidak lepas di mobile
    document.body.classList.add('panic-dragging');   // blokir overscroll Android
    movedRef.current = false;
    dragRef.current  = {
      startX: e.clientX, startY: e.clientY,
      posX: pos.x,       posY:   pos.y,
    };
    setIsDragging(true);
  }, [pos.x, pos.y]);

  const onPointerMove = useCallback((e) => {
    if (!dragRef.current) return;
    const dx = e.clientX - dragRef.current.startX;
    const dy = e.clientY - dragRef.current.startY;
    if (Math.abs(dx) > DRAG_THRESHOLD || Math.abs(dy) > DRAG_THRESHOLD) {
      movedRef.current = true;
    }
    const newX = Math.max(4, Math.min(window.innerWidth  - BTN_SIZE - 4, dragRef.current.posX + dx));
    const newY = Math.max(4, Math.min(window.innerHeight - BTN_SIZE - 4, dragRef.current.posY + dy));
    const newPos = { x: newX, y: newY };
    setPos(newPos);
    localStorage.setItem('panic_btn_pos', JSON.stringify(newPos));
  }, []);

  const onPointerUp = useCallback(() => {
    dragRef.current = null;
    setIsDragging(false);
    document.body.classList.remove('panic-dragging');
    if (!movedRef.current) {
      setShowModal(true);
    }
  }, []);

  // ─── KIRIM ALERT ───────────────────────────────────────
  const handleSend = async () => {
    if (!token || cooldown > 0 || sending) return;
    setSending(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/panic-button/trigger`, {
        method:  'POST',
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
        body:    JSON.stringify({ pesan: pesan.trim() }),
      });
      const data = await res.json();
      if (!res.ok) {
        toast.error(data.detail || 'Gagal mengirim alert');
        return;
      }
      toast.error(`🚨 ${data.message || 'Alert darurat terkirim!'}`, { duration: 6000 });
      setShowModal(false);
      setPesan('');
      // Sirine + haptic
      playSiren();
      navigator.vibrate?.([300, 100, 300, 100, 300]);
      // Start cooldown
      const until = Date.now() + COOLDOWN_SECONDS * 1000;
      localStorage.setItem('panic_cooldown_until', String(until));
      setCooldown(COOLDOWN_SECONDS);
      startCooldownTimer(COOLDOWN_SECONDS);
    } catch {
      toast.error('Gagal menghubungi server');
    } finally {
      setSending(false);
    }
  };

  if (!token || !user || !ALLOWED_ROLES.includes(user.role) || !enabled) return null;

  return (
    <>
      {/* ── FLOATING BUTTON ── */}
      <div
        ref={btnRef}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerUp}
        style={{
          left:        pos.x,
          top:         pos.y,
          cursor:      isDragging ? 'grabbing' : 'grab',
          touchAction: 'none',      // mencegah scroll saat drag di mobile
          userSelect:  'none',
          WebkitUserSelect: 'none',
        }}
        className="fixed z-[9000]"
        title="Tombol Darurat SOS — Seret untuk pindahkan"
        aria-label="Tombol SOS Darurat"
      >
        <button
          disabled={cooldown > 0}
          className={`w-14 h-14 rounded-full shadow-2xl flex flex-col items-center justify-center transition-all
            ${cooldown > 0
              ? 'bg-gray-400 text-gray-200 cursor-not-allowed'
              : 'bg-red-600 text-white'
            }`}
          style={cooldown > 0 ? {
            boxShadow: '0 4px 20px rgba(0,0,0,0.3)',
          } : {
            boxShadow: '0 4px 20px rgba(220,38,38,0.5)',
            animation: 'panic-ring 2s infinite',
          }}
        >
          <Siren size={22} />
          <span className="text-[9px] font-bold leading-none mt-0.5">
            {cooldown > 0 ? `${cooldown}s` : 'SOS'}
          </span>
        </button>
      </div>

      {/* ── MODAL KONFIRMASI ── */}
      {showModal && (
        <div
          className="fixed inset-0 z-[9100] flex items-end sm:items-center justify-center p-4"
          style={{ background: 'rgba(0,0,0,0.6)', backdropFilter: 'blur(4px)' }}
          onClick={(e) => { if (e.target === e.currentTarget) setShowModal(false); }}
        >
          {/* Di mobile muncul dari bawah (bottom sheet style), di desktop muncul di tengah */}
          <div className="bg-white dark:bg-gray-900 rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden"
            style={{ paddingBottom: 'env(safe-area-inset-bottom, 0px)' }}>
            {/* Header */}
            <div className="bg-red-600 px-5 py-4 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <Siren size={22} className="text-white" />
                <h2 className="text-white font-bold text-lg">Kirim Alert Darurat?</h2>
              </div>
              <button onClick={() => setShowModal(false)} className="text-white/80 hover:text-white">
                <X size={20} />
              </button>
            </div>

            <div className="p-5 space-y-4">
              <p className="text-sm text-gray-600 dark:text-gray-400">
                Alert ini akan langsung dikirim ke semua pengurus RT/RW via <strong>WhatsApp</strong> dan <strong>notifikasi browser</strong>.
              </p>

              <div>
                <label className="text-xs font-semibold text-gray-500 uppercase mb-1 block">
                  Pesan singkat <span className="text-gray-400 font-normal">(opsional)</span>
                </label>
                <textarea
                  value={pesan}
                  onChange={e => setPesan(e.target.value.slice(0, 200))}
                  placeholder="Contoh: Ada maling, kebakaran, orang pingsan..."
                  rows={3}
                  className="w-full text-sm border rounded-xl px-3 py-2 resize-none dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-red-500"
                />
                <p className="text-xs text-gray-400 text-right mt-0.5">{pesan.length}/200</p>
              </div>

              <div className="flex gap-3 pt-1">
                <button
                  onClick={() => setShowModal(false)}
                  className="flex-1 py-2.5 rounded-xl border border-gray-200 dark:border-gray-700 text-sm font-medium text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors"
                >
                  Batal
                </button>
                <button
                  onClick={handleSend}
                  disabled={sending}
                  className="flex-1 py-2.5 rounded-xl bg-red-600 hover:bg-red-700 text-white text-sm font-bold transition-colors disabled:opacity-60 flex items-center justify-center gap-2"
                >
                  <Send size={14} />
                  {sending ? 'Mengirim...' : 'Kirim Alert!'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* CSS untuk pulse ring animation */}
      <style>{`
        @keyframes panic-ring {
          0%   { box-shadow: 0 4px 20px rgba(220,38,38,0.5), 0 0 0 0   rgba(220,38,38,0.7); }
          70%  { box-shadow: 0 4px 20px rgba(220,38,38,0.5), 0 0 0 14px rgba(220,38,38,0);   }
          100% { box-shadow: 0 4px 20px rgba(220,38,38,0.5), 0 0 0 0   rgba(220,38,38,0);   }
        }
        /* Hapus overscroll saat drag di Android */
        body.panic-dragging { overflow: hidden; }
      `}</style>
    </>
  );
}
